window.TRANSCRIPTS = {"knowledge-tracing-bkt-dkt":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.194,"text":"Every right or wrong answer is a clue"},{"start":2.194,"end":3.725,"text":"about what a learner knows."},{"start":4.065,"end":6.503,"text":"Knowledge tracing turns those clues into a"},{"start":6.503,"end":7.467,"text":"running estimate."},{"start":7.807,"end":10.188,"text":"This video goes from the classic Bayesian"},{"start":10.188,"end":12.513,"text":"model to deep learning, and the debate"},{"start":12.513,"end":13.25,"text":"between them."},{"start":15.15,"end":17.264,"text":"A tutor sees a stream of answers for one"},{"start":17.264,"end":17.574,"text":"skill."},{"start":17.883,"end":19.894,"text":"It has to guess what the learner knows"},{"start":19.894,"end":22.111,"text":"now, and whether the next answer will be"},{"start":22.111,"end":22.421,"text":"right."},{"start":25.9,"end":28.709,"text":"Knowledge tracing, from Albert Corbett and"},{"start":28.709,"end":30.831,"text":"John Anderson in the mid nineteen"},{"start":30.831,"end":33.328,"text":"nineties, now usually called Bayesian"},{"start":33.328,"end":36.074,"text":"knowledge tracing, treats each skill as a"},{"start":36.074,"end":38.945,"text":"hidden switch: known, or not yet known."},{"start":39.77,"end":42.05,"text":"At each practice opportunity, an unknown"},{"start":42.05,"end":44.33,"text":"skill can switch to known with probability"},{"start":44.33,"end":44.701,"text":"P of T."},{"start":45.02,"end":47.247,"text":"In the classic model, it never switches"},{"start":47.247,"end":47.512,"text":"back."},{"start":48.32,"end":50.732,"text":"We never see the switch, only answers."},{"start":51.094,"end":53.626,"text":"A learner who does not know the skill can"},{"start":53.626,"end":56.219,"text":"still guess right, with probability P of"},{"start":56.219,"end":56.339,"text":"G."},{"start":56.701,"end":59.113,"text":"One who knows it can still slip, with"},{"start":59.113,"end":60.258,"text":"probability P of S."},{"start":61.17,"end":63.194,"text":"Add the chance the skill was already known"},{"start":63.194,"end":65.265,"text":"at the start, P of L zero, and you have"},{"start":65.265,"end":66.348,"text":"four numbers per skill."},{"start":68.22,"end":70.398,"text":"Let's run one update by hand, with a"},{"start":70.398,"end":72.13,"text":"starting belief of point three."},{"start":72.465,"end":74.923,"text":"The first answer is wrong, so Bayes' rule"},{"start":74.923,"end":77.04599999999999,"text":"lowers the belief to about point zero"},{"start":77.04599999999999,"end":77.325,"text":"five."},{"start":79.21000000000001,"end":81.431,"text":"Then the model adds a chance to learn from"},{"start":81.431,"end":83.496,"text":"the practice itself, which brings the"},{"start":83.496,"end":85.51,"text":"belief back up to about point one nine."},{"start":87.38,"end":89.797,"text":"Over eight answers the belief rises and"},{"start":89.797,"end":92.637,"text":"falls: each mistake pulls it down, each"},{"start":92.637,"end":94.87299999999999,"text":"success pushes it up, and a run of"},{"start":94.87299999999999,"end":96.92699999999999,"text":"successes carries it close to one."},{"start":97.81,"end":100.219,"text":"If a tutor sets a mastery threshold, say"},{"start":100.219,"end":102.51599999999999,"text":"point nine five, it can decide when to"},{"start":102.51599999999999,"end":102.964,"text":"move on."},{"start":104.9,"end":106.868,"text":"The big strength of this model is that"},{"start":106.868,"end":108.987,"text":"every number means something to a teacher."},{"start":109.28999999999999,"end":111.207,"text":"A low learning rate says the skill is"},{"start":111.207,"end":111.964,"text":"learned slowly."},{"start":112.267,"end":114.285,"text":"A high guess rate says right answers on"},{"start":114.285,"end":115.64699999999999,"text":"that skill tell you little."},{"start":117.56700000000001,"end":119.765,"text":"In two thousand fifteen, Chris Piech and"},{"start":119.765,"end":121.708,"text":"colleagues replaced the switch with a"},{"start":121.708,"end":122.986,"text":"recurrent neural network."},{"start":123.292,"end":125.286,"text":"Deep knowledge tracing reads the whole"},{"start":125.286,"end":126.82,"text":"sequence of items and answers."},{"start":127.67699999999999,"end":129.888,"text":"At each step it outputs the chance of"},{"start":129.888,"end":131.983,"text":"answering every item correctly next."},{"start":132.332,"end":134.834,"text":"No expert has to say which skill each item"},{"start":134.834,"end":135.358,"text":"measures."},{"start":137.347,"end":140.005,"text":"The paper reported a striking result: on"},{"start":140.005,"end":142.663,"text":"one benchmark, an AUC of point eight six,"},{"start":142.663,"end":144.743,"text":"against point six nine for the best"},{"start":144.743,"end":145.61,"text":"earlier result."},{"start":147.61,"end":149.694,"text":"Within a year, two papers took a closer"},{"start":149.694,"end":149.942,"text":"look."},{"start":151.94,"end":154.547,"text":"Xiaolu Xiong and colleagues found that"},{"start":154.547,"end":157.155,"text":"nearly a quarter of the benchmark rows"},{"start":157.155,"end":160.297,"text":"were duplicates, and that on cleaned data,"},{"start":160.297,"end":163.305,"text":"deep knowledge tracing still beat BKT, but"},{"start":163.305,"end":166.046,"text":"held no overall edge over another simple"},{"start":166.046,"end":167.049,"text":"model, P F A."},{"start":167.92000000000002,"end":170.06,"text":"Mohammad Khajah and colleagues extended"},{"start":170.06,"end":171.772,"text":"Bayesian knowledge tracing with"},{"start":171.772,"end":174.072,"text":"forgetting, student ability, and skill"},{"start":174.072,"end":176.211,"text":"discovery, and its performance became"},{"start":176.211,"end":178.405,"text":"indistinguishable from the deep model,"},{"start":178.405,"end":180.491,"text":"suggesting the deep model's gains came"},{"start":180.491,"end":182.791,"text":"from patterns that simpler models can also"},{"start":182.791,"end":183.219,"text":"capture."},{"start":185.133,"end":187.8,"text":"We ran our own small test: six hundred"},{"start":187.8,"end":189.981,"text":"simulated students practicing three"},{"start":189.981,"end":192.648,"text":"fraction skills, with a hidden dependency"},{"start":192.648,"end":193.86,"text":"between two of them."},{"start":194.743,"end":197.402,"text":"On the held out students, BKT reached an"},{"start":197.402,"end":200.185,"text":"AUC of point eight zero nine, and the deep"},{"start":200.185,"end":201.978,"text":"model point eight zero seven."},{"start":202.349,"end":205.008,"text":"In this one small simulation, the simple"},{"start":205.008,"end":206.492,"text":"model did about as well."},{"start":208.327,"end":211.369,"text":"Later models use attention, such as SAKT"},{"start":211.369,"end":211.935,"text":"and AKT."},{"start":212.36,"end":215.332,"text":"But the core trade off remains: deep"},{"start":215.332,"end":218.233,"text":"models can predict well on large data,"},{"start":218.233,"end":220.992,"text":"while BKT's numbers tell a teacher why."},{"start":221.877,"end":224.54,"text":"So choose a learner model by the decision"},{"start":224.54,"end":227.076,"text":"it needs to support, not by AUC alone."},{"start":229.077,"end":231.24099999999999,"text":"For the discussion board, pick one"},{"start":231.24099999999999,"end":233.698,"text":"tutoring decision, such as moving on or"},{"start":233.698,"end":236.038,"text":"alerting a teacher, and explain which"},{"start":236.038,"end":238.612,"text":"learner model you would trust for it, and"},{"start":238.612,"end":238.846,"text":"why."}]},"iEc8Dt3ePWo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.538,"text":"When a learning game adapts to a player,"},{"start":2.538,"end":5.136,"text":"it can change two very different things:"},{"start":5.136,"end":7.791,"text":"what happens right now, inside a level, or"},{"start":7.791,"end":9.711,"text":"what comes next, between levels."},{"start":10.05,"end":11.631,"text":"This video compares the two."},{"start":13.587,"end":15.914,"text":"Back in Launch Lab, player B has missed"},{"start":15.914,"end":18.075,"text":"the target three times in a row on the"},{"start":18.075,"end":18.684,"text":"same level."},{"start":20.547,"end":22.37,"text":"A game could respond in two ways."},{"start":22.702,"end":25.023,"text":"It could step in now with a hint, or it"},{"start":25.023,"end":27.289,"text":"could send player B to a different level"},{"start":27.289,"end":27.565,"text":"next."},{"start":32.767,"end":34.904,"text":"Both are adaptation, but they work on"},{"start":34.904,"end":36.935,"text":"different timescales, use different"},{"start":36.935,"end":38.966,"text":"evidence, and carry different risks."},{"start":41.087,"end":43.847,"text":"Micro adaptation happens inside a task,"},{"start":43.847,"end":47.067,"text":"from moment to moment: hints, feedback,"},{"start":47.067,"end":49.761,"text":"small changes to pacing or difficulty,"},{"start":49.761,"end":51.732,"text":"even how a character responds."},{"start":52.547,"end":54.947,"text":"Michael Kickmeier-Rust and Dietrich Albert"},{"start":54.947,"end":57.236,"text":"argued that in games, micro adaptivity"},{"start":57.236,"end":59.525,"text":"should be subtle, so that help arrives"},{"start":59.525,"end":61.032,"text":"without breaking immersion."},{"start":62.877,"end":65.583,"text":"Macro adaptation happens between tasks:"},{"start":65.583,"end":67.929,"text":"which level comes next, which path a"},{"start":67.929,"end":70.515,"text":"learner takes, and how fast the sequence"},{"start":70.515,"end":70.876,"text":"moves."},{"start":72.857,"end":74.491,"text":"The idea is older than games."},{"start":74.82900000000001,"end":77.252,"text":"Ok-Choon Park and Jung Lee described macro"},{"start":77.252,"end":79.674,"text":"adaptive instruction, which fits a whole"},{"start":79.674,"end":82.09700000000001,"text":"program to what we know about a learner,"},{"start":82.09700000000001,"end":84.351,"text":"and micro adaptive instruction, which"},{"start":84.351,"end":86.549,"text":"diagnoses needs during learning itself."},{"start":88.34700000000001,"end":90.857,"text":"Kurt VanLehn gave the same split a name in"},{"start":90.857,"end":93.542,"text":"tutoring systems: an inner loop for each"},{"start":93.542,"end":95.876,"text":"step, and an outer loop for each task."},{"start":97.91,"end":100.563,"text":"Micro adaptation acts in seconds, using"},{"start":100.563,"end":102.142,"text":"what the player just did."},{"start":102.521,"end":105.301,"text":"Macro adaptation acts over minutes, using"},{"start":105.301,"end":107.701,"text":"a learner model built from many tasks."},{"start":108.61,"end":111.59,"text":"Micro changes hints, feedback, and local"},{"start":111.59,"end":114.107,"text":"difficulty, while macro changes the"},{"start":114.107,"end":116.82300000000001,"text":"sequence, the level, and the content."},{"start":118.08,"end":119.532,"text":"Each one has its own risk."},{"start":119.86699999999999,"end":122.212,"text":"Micro help that comes too often can break"},{"start":122.212,"end":124.725,"text":"flow, or let players lean on hints instead"},{"start":124.725,"end":125.395,"text":"of thinking."},{"start":126.31,"end":128.66,"text":"Macro decisions can send a player down the"},{"start":128.66,"end":131.23,"text":"wrong path, and they react slowly, because"},{"start":131.23,"end":133.252,"text":"they wait for evidence to accumulate."},{"start":135.117,"end":137.588,"text":"To see how the two loops interact, we"},{"start":137.588,"end":140.122,"text":"simulated two thousand players in Launch"},{"start":140.122,"end":143.15,"text":"Lab under four designs: a fixed sequence,"},{"start":143.15,"end":145.436,"text":"macro only, micro only, and both."},{"start":147.447,"end":150.018,"text":"The rules are simple and stated up front:"},{"start":150.018,"end":152.317,"text":"players learn most when success is likely"},{"start":152.317,"end":154.67000000000002,"text":"but not certain, hints help them succeed"},{"start":154.67000000000002,"end":157.077,"text":"but teach a little less, and three misses"},{"start":157.077,"end":158.828,"text":"in a row can make a player quit."},{"start":165.007,"end":167.476,"text":"With a fixed sequence, fifty eight percent"},{"start":167.476,"end":169.835,"text":"of players quit early, and almost all of"},{"start":169.835,"end":171.097,"text":"the weakest third quit."},{"start":171.947,"end":174.28,"text":"Hints alone barely help: forty seven"},{"start":174.28,"end":176.724,"text":"percent still quit, because a hint cannot"},{"start":176.724,"end":178.723,"text":"rescue a level that is far too hard."},{"start":179.527,"end":182.181,"text":"Choosing the next level well matters more:"},{"start":182.181,"end":184.448,"text":"macro adaptation cuts quitting to twenty"},{"start":184.448,"end":186.66,"text":"one percent, and combining both loops"},{"start":186.66,"end":188.595,"text":"brings it down to fourteen percent."},{"start":190.627,"end":192.034,"text":"There is a catch, though."},{"start":192.346,"end":194.431,"text":"Under macro adaptation, the strongest"},{"start":194.431,"end":196.568,"text":"players learned less than with the fixed"},{"start":196.568,"end":198.548,"text":"sequence, because the learner model"},{"start":198.548,"end":200.789,"text":"started at average and took several levels"},{"start":200.789,"end":201.414,"text":"to catch up."},{"start":205.3,"end":207.449,"text":"The game Reboot Seoul twenty fifty uses"},{"start":207.449,"end":209.222,"text":"both loops in its drone missions."},{"start":209.544,"end":211.801,"text":"The macro loop moves players through five"},{"start":211.801,"end":214.003,"text":"tiers, from small grids to larger ones"},{"start":214.003,"end":215.508,"text":"with tighter command limits."},{"start":216.45,"end":218.373,"text":"The micro loop watches for repeated"},{"start":218.373,"end":220.563,"text":"trouble inside a mission and offers help"},{"start":220.563,"end":223.02,"text":"in steps: first an explanation, then a"},{"start":223.02,"end":224.195,"text":"map, then more time."},{"start":224.515,"end":226.70499999999998,"text":"Support fades once a player clears a new"},{"start":226.70499999999998,"end":227.4,"text":"tier cleanly."},{"start":229.24,"end":231.531,"text":"So when you design adaptivity for a"},{"start":231.531,"end":234.204,"text":"learning game, decide what each loop is"},{"start":234.204,"end":237.131,"text":"for: micro to keep a player productively"},{"start":237.131,"end":239.93200000000002,"text":"engaged in this task, and macro to choose"},{"start":239.93200000000002,"end":241.968,"text":"the task that teaches most next."},{"start":242.97,"end":245.516,"text":"Then check three things: does the help"},{"start":245.516,"end":248.061,"text":"protect immersion, does the learner model"},{"start":248.061,"end":250.607,"text":"have enough evidence, and can the learner"},{"start":250.607,"end":253.152,"text":"see or choose the change, which Jan Plass"},{"start":253.152,"end":255.293,"text":"and Shashank Pawar call adaptability."},{"start":257.257,"end":259.516,"text":"For the discussion board, think of a game"},{"start":259.516,"end":261.723,"text":"you know and find one micro adaptation and"},{"start":261.723,"end":263.11,"text":"one macro adaptation in it."},{"start":263.418,"end":265.677,"text":"Then ask what evidence each one uses, and"},{"start":265.677,"end":267.731,"text":"what would happen if that evidence were"},{"start":267.731,"end":268.039,"text":"wrong."}]},"aADMw1NjWKU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.351,"text":"Why do children spend hours on some games,"},{"start":2.351,"end":3.441,"text":"and minutes on others?"},{"start":3.739,"end":5.821,"text":"In nineteen eighty, Thomas Malone asked"},{"start":5.821,"end":7.903,"text":"that question about computer games, and"},{"start":7.903,"end":9.638,"text":"turned the answer into a theory of"},{"start":9.638,"end":11.473,"text":"intrinsically motivating instruction."},{"start":13.41,"end":15.977,"text":"Malone's Stanford dissertation was titled"},{"start":15.977,"end":17.872,"text":"What Makes Things Fun to Learn?"},{"start":18.239,"end":20.745,"text":"He studied which games children chose to"},{"start":20.745,"end":23.312,"text":"play, then built versions of games with"},{"start":23.312,"end":25.818,"text":"features added or removed, to see what"},{"start":25.818,"end":26.673,"text":"made them fun."},{"start":27.62,"end":29.842,"text":"In one study he took Darts, a fractions"},{"start":29.842,"end":32.276,"text":"game, and removed features one at a time,"},{"start":32.276,"end":34.763,"text":"such as scoring, music, and the fantasy of"},{"start":34.763,"end":36.033,"text":"arrows popping balloons."},{"start":37.04,"end":39.584,"text":"One finding stood out: boys liked the"},{"start":39.584,"end":42.188,"text":"version where arrows popped balloons, but"},{"start":42.188,"end":43.016,"text":"girls did not."},{"start":43.371,"end":45.382,"text":"The same fantasy did not motivate"},{"start":45.382,"end":45.915,"text":"everyone."},{"start":47.79,"end":50.137,"text":"In the journal Cognitive Science, in"},{"start":50.137,"end":52.785,"text":"nineteen eighty one, he organized what he"},{"start":52.785,"end":55.674,"text":"found into three ingredients: challenge,"},{"start":55.674,"end":57.179,"text":"fantasy, and curiosity."},{"start":59.043,"end":61.06,"text":"Challenge needs a goal whose outcome is"},{"start":61.06,"end":61.564,"text":"uncertain."},{"start":61.866,"end":64.135,"text":"If you are sure to win, or sure to lose,"},{"start":64.135,"end":66.101,"text":"there is little reason to keep playing."},{"start":66.813,"end":69.182,"text":"Malone listed ways to keep outcomes"},{"start":69.182,"end":72.34,"text":"uncertain: variable difficulty, goals at"},{"start":72.34,"end":75.235,"text":"several levels, hidden information, and"},{"start":75.235,"end":75.959,"text":"randomness."},{"start":77.873,"end":80.21600000000001,"text":"Fantasy places the player in an imagined"},{"start":80.21600000000001,"end":80.559,"text":"world."},{"start":80.901,"end":83.015,"text":"Malone's key distinction was between"},{"start":83.015,"end":85.301,"text":"extrinsic fantasy and intrinsic fantasy."},{"start":87.243,"end":89.332,"text":"In an extrinsic version of a fractions"},{"start":89.332,"end":91.688,"text":"game, you answer a question, and then a"},{"start":91.688,"end":93.991,"text":"cannon fires, whether or not the fantasy"},{"start":93.991,"end":95.812,"text":"has anything to do with fractions."},{"start":97.703,"end":100.051,"text":"In an intrinsic version, the fraction you"},{"start":100.051,"end":102.55799999999999,"text":"type is the aim: three quarters sends the"},{"start":102.55799999999999,"end":104.74600000000001,"text":"shot three quarters of the way, so the"},{"start":104.74600000000001,"end":106.293,"text":"fantasy depends on the skill."},{"start":107.093,"end":109.366,"text":"Malone argued that intrinsic fantasies are"},{"start":109.366,"end":111.163,"text":"usually more interesting and more"},{"start":111.163,"end":113.435,"text":"instructional, because every move in the"},{"start":113.435,"end":115.49600000000001,"text":"fantasy gives feedback about the skill."},{"start":117.363,"end":119.23400000000001,"text":"Curiosity comes in two kinds."},{"start":119.62100000000001,"end":122.265,"text":"Sensory curiosity is drawn by changes in"},{"start":122.265,"end":123.296,"text":"light and sound."},{"start":123.68299999999999,"end":126.392,"text":"Cognitive curiosity is drawn by the sense"},{"start":126.392,"end":128.714,"text":"that our knowledge is incomplete,"},{"start":128.714,"end":130.906,"text":"inconsistent, or unparsimonious."},{"start":131.713,"end":134.084,"text":"In the cannon game, a player who types two"},{"start":134.084,"end":136.35,"text":"quarters and then one half sees both shots"},{"start":136.35,"end":137.562,"text":"land in the same place."},{"start":137.878,"end":140.038,"text":"That small surprise invites the question"},{"start":140.038,"end":140.407,"text":"of why."},{"start":142.333,"end":145.552,"text":"Later, with Mark Lepper, Malone extended"},{"start":145.552,"end":148.913,"text":"the list: control, meaning choice and a"},{"start":148.913,"end":151.917,"text":"sense of power, and three interpersonal"},{"start":151.917,"end":155.636,"text":"motivations: cooperation, competition, and"},{"start":155.636,"end":156.494,"text":"recognition."},{"start":158.44299999999998,"end":160.778,"text":"Decades later, Jacob Habgood and Shaaron"},{"start":160.778,"end":163.112,"text":"Ainsworth tested a version of this idea,"},{"start":163.112,"end":165.446,"text":"which they called intrinsic integration,"},{"start":165.446,"end":167.618,"text":"with a math game called Zombie Division."},{"start":168.463,"end":170.642,"text":"Children learned more from the intrinsic"},{"start":170.642,"end":173.03300000000002,"text":"version under fixed time, and in free time"},{"start":173.03300000000002,"end":175.265,"text":"chose to play it about seven times longer."},{"start":176.173,"end":178.653,"text":"Later studies show a more mixed picture,"},{"start":178.653,"end":181.133,"text":"so treat intrinsic integration as a strong"},{"start":181.133,"end":183.267,"text":"design hypothesis, not a guarantee."},{"start":185.22,"end":187.368,"text":"When you design a learning game, check"},{"start":187.368,"end":189.621,"text":"whether the goal's outcome is uncertain,"},{"start":189.621,"end":191.926,"text":"whether the fantasy depends on the skill,"},{"start":191.926,"end":193.813,"text":"and whether feedback leaves players"},{"start":193.813,"end":194.756,"text":"curious about why."},{"start":196.73,"end":198.735,"text":"For the discussion board, pick an"},{"start":198.735,"end":201.073,"text":"educational game and classify its fantasy"},{"start":201.073,"end":202.52100000000002,"text":"as intrinsic or extrinsic."},{"start":202.855,"end":204.971,"text":"Then redesign one element so that the"},{"start":204.971,"end":206.92000000000002,"text":"fantasy depends on the skill being"},{"start":206.92000000000002,"end":207.36599999999999,"text":"learned."}]},"SfIj7mrAHwI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.577,"text":"Every learning design hides a guess about"},{"start":2.577,"end":3.805,"text":"how learning happens."},{"start":4.156,"end":6.496,"text":"A conjecture map, laid out by William"},{"start":6.496,"end":9.129,"text":"Sandoval in a two thousand fourteen paper,"},{"start":9.129,"end":11.41,"text":"puts those guesses on paper so you can"},{"start":11.41,"end":11.995,"text":"test them."},{"start":12.346,"end":14.569,"text":"This video builds one, step by step."},{"start":16.34,"end":18.413,"text":"Sandoval noticed that most writing on"},{"start":18.413,"end":20.595,"text":"design research described what it is,"},{"start":20.595,"end":23.049,"text":"rather than how to do it, and critics were"},{"start":23.049,"end":24.413,"text":"asking for clearer rigor."},{"start":25.37,"end":27.654,"text":"His premise is simple: any learning"},{"start":27.654,"end":29.882,"text":"environment already embodies hypotheses"},{"start":29.882,"end":32.388,"text":"about how learning happens, so researchers"},{"start":32.388,"end":34.56,"text":"should state them explicitly, and in"},{"start":34.56,"end":35.006,"text":"advance."},{"start":36.867,"end":39.157,"text":"The map reads from left to right: a high"},{"start":39.157,"end":40.949,"text":"level conjecture is embodied in the"},{"start":40.949,"end":43.139,"text":"design, the embodiment produces mediating"},{"start":43.139,"end":45.18,"text":"processes, and those processes produce"},{"start":45.18,"end":45.628,"text":"outcomes."},{"start":46.457,"end":48.676,"text":"Two kinds of arrows connect the boxes."},{"start":49.026,"end":51.479,"text":"Design conjectures run from embodiment to"},{"start":51.479,"end":52.064,"text":"processes."},{"start":52.414,"end":54.925,"text":"Theoretical conjectures run from processes"},{"start":54.925,"end":55.626,"text":"to outcomes."},{"start":56.567,"end":59.034,"text":"The middle box is the one Sandoval insists"},{"start":59.034,"end":59.206,"text":"on."},{"start":59.55,"end":61.788,"text":"A mediating process is what the design"},{"start":61.788,"end":64.37,"text":"should make happen in between, and you can"},{"start":64.37,"end":66.435,"text":"see it in interactions, or in the"},{"start":66.435,"end":67.812,"text":"artifacts learners make."},{"start":70.787,"end":71.638,"text":"Let's build one."},{"start":71.957,"end":74.352,"text":"Our example is Recipe Remix, a sixth grade"},{"start":74.352,"end":76.48,"text":"fractions lesson where students scale a"},{"start":76.48,"end":78.555,"text":"cookie recipe for different numbers of"},{"start":78.555,"end":78.92699999999999,"text":"guests."},{"start":80.81700000000001,"end":83.451,"text":"Step one, the high level conjecture:"},{"start":83.451,"end":85.188,"text":"students understand fraction"},{"start":85.188,"end":87.404,"text":"multiplication better when they must"},{"start":87.404,"end":89.979,"text":"justify their scaling to a peer, using a"},{"start":89.979,"end":91.29599999999999,"text":"visual representation."},{"start":91.655,"end":94.41,"text":"It is too general, by design, to tell you"},{"start":94.41,"end":95.727,"text":"exactly what to build."},{"start":96.56700000000001,"end":98.094,"text":"Step two, the embodiment."},{"start":98.434,"end":100.866,"text":"Sandoval names four kinds of element:"},{"start":100.866,"end":103.24199999999999,"text":"tools and materials, task structures,"},{"start":103.24199999999999,"end":105.562,"text":"participant structures, and discursive"},{"start":105.562,"end":106.12700000000001,"text":"practices."},{"start":107.06700000000001,"end":109.947,"text":"Here that means recipe cards and fraction"},{"start":109.947,"end":113.17,"text":"strips, scaling for six, nine, and three"},{"start":113.17,"end":115.913,"text":"guests with a proof sketch each time,"},{"start":115.913,"end":118.382,"text":"pairs with a Chef who scales and an"},{"start":118.382,"end":121.194,"text":"Auditor who must be convinced, and the"},{"start":121.194,"end":123.525,"text":"talk move, show me how you know."},{"start":124.42699999999999,"end":126.322,"text":"A design does not need all four."},{"start":126.678,"end":129.107,"text":"In Ann Brown's design work, reciprocal"},{"start":129.107,"end":131.536,"text":"teaching changed tasks and roles without"},{"start":131.536,"end":132.661,"text":"any new technology."},{"start":133.547,"end":135.724,"text":"Step three, the mediating processes."},{"start":136.068,"end":138.703,"text":"You can see them in two ways: observable"},{"start":138.703,"end":141.225,"text":"interactions, like an Auditor challenging"},{"start":141.225,"end":143.574,"text":"and a Chef justifying with strips, and"},{"start":143.574,"end":145.923,"text":"artifacts, like annotated recipe cards."},{"start":146.767,"end":149.637,"text":"Sandoval's analogy: an airplane flies only"},{"start":149.637,"end":151.191,"text":"because it generates lift."},{"start":151.55,"end":154.36,"text":"Designs, likewise, do not lead directly to"},{"start":154.36,"end":154.898,"text":"outcomes."},{"start":156.767,"end":159.435,"text":"Step four, the outcomes, as specific as"},{"start":159.435,"end":161.86,"text":"you can make them: better fraction"},{"start":161.86,"end":163.922,"text":"multiplication scores, and more"},{"start":163.922,"end":165.923,"text":"justification in written answers."},{"start":167.953,"end":170.15800000000002,"text":"Now write each arrow as a sentence."},{"start":170.536,"end":173.245,"text":"The design conjecture: if pairs scale"},{"start":173.245,"end":175.575,"text":"recipes in Chef and Auditor roles,"},{"start":175.575,"end":177.78,"text":"justification exchanges will occur."},{"start":178.15800000000002,"end":180.993,"text":"The theoretical conjecture: if students"},{"start":180.993,"end":183.639,"text":"regularly justify with representations,"},{"start":183.639,"end":185.465,"text":"their understanding improves."},{"start":186.403,"end":189.349,"text":"Each arrow needs its own evidence: video,"},{"start":189.349,"end":191.993,"text":"interaction, or artifact analysis for the"},{"start":191.993,"end":194.698,"text":"design conjecture, and outcome measures,"},{"start":194.698,"end":197.223,"text":"on top of that, for the theoretical one."},{"start":199.177,"end":201.323,"text":"Now the map meets a real classroom, and"},{"start":201.323,"end":203.01,"text":"the evidence starts to talk back."},{"start":204.977,"end":207.255,"text":"Suppose quiz scores barely move, and"},{"start":207.255,"end":209.475,"text":"classroom video shows Auditors mostly"},{"start":209.475,"end":210.176,"text":"saying okay."},{"start":215.30700000000002,"end":217.377,"text":"The design arrow failed: the design never"},{"start":217.377,"end":218.91899999999998,"text":"produced the justification process."},{"start":219.183,"end":221.077,"text":"When the outcome is missing, first check"},{"start":221.077,"end":222.927,"text":"whether the middle box happened at all,"},{"start":222.927,"end":224.777,"text":"because a failed design tells you nothing"},{"start":224.777,"end":225.702,"text":"yet about the theory."},{"start":226.55700000000002,"end":229.302,"text":"So you revise the embodiment: an Auditor"},{"start":229.302,"end":231.987,"text":"checklist, and a class norm that an answer"},{"start":231.987,"end":234.554,"text":"is not done until your Auditor can explain"},{"start":234.554,"end":234.733,"text":"it."},{"start":235.091,"end":237.359,"text":"Then you redraw the map and try again."},{"start":239.317,"end":242.314,"text":"Sandoval's own project followed the same"},{"start":242.314,"end":242.753,"text":"logic."},{"start":243.192,"end":246.262,"text":"Analyzing two teachers' classrooms showed"},{"start":246.262,"end":249.333,"text":"productive argument where talk focused on"},{"start":249.333,"end":252.404,"text":"building consensus, so his team revised"},{"start":252.404,"end":254.89,"text":"the map to design the classroom's"},{"start":254.89,"end":257.668,"text":"discursive practice, its social and"},{"start":257.668,"end":258.838,"text":"epistemic norms."},{"start":260.773,"end":263.378,"text":"Three cautions come from Sandoval himself:"},{"start":263.378,"end":265.332,"text":"read the map as a process, not as"},{"start":265.332,"end":267.665,"text":"variables; different studies can test"},{"start":267.665,"end":270.27,"text":"different arrows; and the map does not yet"},{"start":270.27,"end":271.51800000000003,"text":"represent context well."},{"start":273.497,"end":275.989,"text":"Your turn: write one high level"},{"start":275.989,"end":279.02,"text":"conjecture, fill the embodiment slots your"},{"start":279.02,"end":281.849,"text":"design uses, name one process you could"},{"start":281.849,"end":284.813,"text":"see, one outcome you could measure, and"},{"start":284.813,"end":287.642,"text":"write both arrows as if, then sentences."},{"start":289.473,"end":291.479,"text":"For the discussion board, share your map"},{"start":291.479,"end":293.252,"text":"and mark the arrow you are least sure"},{"start":293.252,"end":293.531,"text":"about."},{"start":293.811,"end":295.77,"text":"Then say what evidence would convince you"},{"start":295.77,"end":296.423,"text":"that it holds."}]},"GcsN8Ozqvec":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.422,"text":"Two models come up whenever people design"},{"start":2.422,"end":4.67,"text":"motivating lessons or games: Thomas"},{"start":4.67,"end":6.479,"text":"Malone's theory of intrinsically"},{"start":6.479,"end":8.891,"text":"motivating instruction, and John Keller's"},{"start":8.891,"end":9.494,"text":"ARCS model."},{"start":9.823,"end":12.071,"text":"This video compares what each one is for."},{"start":13.92,"end":15.644,"text":"They answer different questions."},{"start":15.967,"end":18.176,"text":"Malone studied what makes computer games"},{"start":18.176,"end":20.223,"text":"fun, and turned it into a theory of"},{"start":20.223,"end":22.217,"text":"intrinsically motivating instruction."},{"start":23.16,"end":25.466,"text":"Keller asked how a designer can find and"},{"start":25.466,"end":27.828,"text":"fix a motivation problem in any course,"},{"start":27.828,"end":29.403,"text":"whether or not it is a game."},{"start":31.333,"end":34.117,"text":"Malone's theory has three ingredients:"},{"start":34.117,"end":36.964,"text":"challenge, built from goals with uncertain"},{"start":36.964,"end":39.875,"text":"outcomes; fantasy, which Malone argued"},{"start":39.875,"end":42.532,"text":"works better when it is tied to the skill"},{"start":42.532,"end":45.569,"text":"itself; and curiosity, sparked when what"},{"start":45.569,"end":47.214,"text":"you know feels incomplete."},{"start":48.083,"end":50.735,"text":"With Mark Lepper he later added control,"},{"start":50.735,"end":53.572,"text":"and three social motives: cooperation,"},{"start":53.572,"end":55.483,"text":"competition, and recognition."},{"start":57.313,"end":60.094,"text":"ARCS stands for attention, relevance,"},{"start":60.094,"end":62.146,"text":"confidence, and satisfaction."},{"start":62.983,"end":65.05,"text":"Keller grounded it in expectancy value"},{"start":65.05,"end":67.434,"text":"theory: we put in effort when something"},{"start":67.434,"end":69.501,"text":"matters to us and we expect to succeed."},{"start":69.819,"end":71.78,"text":"The model grew from work he began in"},{"start":71.78,"end":72.945,"text":"nineteen seventy nine."},{"start":74.773,"end":77.547,"text":"In Keller's later versions, each category"},{"start":77.547,"end":78.682,"text":"splits into three."},{"start":79.06,"end":81.582,"text":"Relevance, for example, covers goal"},{"start":81.582,"end":83.977,"text":"orientation, motive matching, and"},{"start":83.977,"end":84.73400000000001,"text":"familiarity."},{"start":85.112,"end":87.57,"text":"Note that satisfaction openly includes"},{"start":87.57,"end":88.705,"text":"extrinsic rewards."},{"start":90.65299999999999,"end":94.12100000000001,"text":"ARCS is also a design process: define,"},{"start":94.12100000000001,"end":97.363,"text":"design, develop, and evaluate, which"},{"start":97.363,"end":100.077,"text":"Keller describes as compatible with"},{"start":100.077,"end":102.791,"text":"typical instructional design models."},{"start":103.773,"end":106.19800000000001,"text":"And the first step is a check: is this"},{"start":106.19800000000001,"end":108.291,"text":"really a motivation problem, or are"},{"start":108.291,"end":109.614,"text":"learners missing skills?"},{"start":109.944,"end":111.763,"text":"ARCS is meant for the first case."},{"start":113.71000000000001,"end":114.82,"text":"Here is a toy audit."},{"start":115.154,"end":117.208,"text":"A twenty minute fractions lesson has"},{"start":117.208,"end":119.65100000000001,"text":"students serving pizza orders, like three"},{"start":119.65100000000001,"end":120.65,"text":"eighths pepperoni."},{"start":120.983,"end":123.371,"text":"Five learners rate each ARCS category from"},{"start":123.371,"end":124.037,"text":"one to five."},{"start":124.93,"end":126.174,"text":"Average each column."},{"start":126.547,"end":129.16,"text":"Attention and satisfaction are already at"},{"start":129.16,"end":129.47,"text":"four."},{"start":129.844,"end":132.643,"text":"Relevance averages two, and confidence two"},{"start":132.643,"end":133.327,"text":"point four."},{"start":134.21,"end":136.922,"text":"So against a target of four, relevance is"},{"start":136.922,"end":139.079,"text":"the biggest gap, then confidence."},{"start":139.448,"end":141.482,"text":"The game already grabs attention."},{"start":141.852,"end":144.255,"text":"Learners just do not see why fractions"},{"start":144.255,"end":146.72,"text":"matter, or feel unsure they can do it."},{"start":148.61,"end":150.965,"text":"An ARCS designer targets the gap that was"},{"start":150.965,"end":153.65699999999998,"text":"measured: use the class's own lunch orders"},{"start":153.65699999999998,"end":155.788,"text":"for relevance, and show the success"},{"start":155.788,"end":157.13400000000001,"text":"criteria for confidence."},{"start":158.01,"end":160.678,"text":"A Malone designer adds features: make the"},{"start":160.678,"end":163.232,"text":"fantasy intrinsic, so slicing the pizza is"},{"start":163.232,"end":165.787,"text":"the fraction skill, and add challenge with"},{"start":165.787,"end":167.489,"text":"hidden orders that get harder."},{"start":168.46,"end":170.73,"text":"Put simply, Malone tells you which fun"},{"start":170.73,"end":173,"text":"ingredients to add, and ARCS tells you"},{"start":173,"end":174.938,"text":"which one this audience is missing."},{"start":176.787,"end":178.035,"text":"You can see parallels."},{"start":178.375,"end":180.759,"text":"Malone's challenge sits close to Keller's"},{"start":180.759,"end":183.142,"text":"confidence, which calls for conquerable"},{"start":183.142,"end":185.468,"text":"challenge, and curiosity sits close to"},{"start":185.468,"end":186.376,"text":"inquiry arousal."},{"start":187.227,"end":188.85,"text":"But the difference matters."},{"start":189.21,"end":191.194,"text":"Malone describes features of fun"},{"start":191.194,"end":191.856,"text":"activities."},{"start":192.216,"end":194.26,"text":"ARCS is a procedure driven by the"},{"start":194.26,"end":196.845,"text":"audience, and it openly allows extrinsic"},{"start":196.845,"end":197.326,"text":"rewards."},{"start":199.32,"end":200.54,"text":"How strong is the evidence?"},{"start":200.811,"end":202.755,"text":"A meta analysis of thirty eight controlled"},{"start":202.755,"end":204.472,"text":"ARCS studies found an effect of point"},{"start":204.472,"end":206.325,"text":"seven four on achievement and point four"},{"start":206.325,"end":207.22899999999998,"text":"three on motivation."},{"start":208.06,"end":209.956,"text":"But the authors warn these numbers are"},{"start":209.956,"end":212.047,"text":"only as good as the primary studies, and"},{"start":212.047,"end":213.992,"text":"Keller's own early field tests measured"},{"start":213.992,"end":215.548,"text":"teachers' views, not learning."},{"start":217.46,"end":218.62,"text":"So use them together."},{"start":218.952,"end":220.996,"text":"Diagnose with ARCS to find what this"},{"start":220.996,"end":223.428,"text":"audience is missing, then borrow Malone's"},{"start":223.428,"end":225.804,"text":"features to fix it, and keep the fantasy"},{"start":225.804,"end":226.798,"text":"tied to the skill."},{"start":228.73,"end":231.118,"text":"For the discussion board, name the weakest"},{"start":231.118,"end":233.348,"text":"ARCS category in a lesson you know, and"},{"start":233.348,"end":235.312,"text":"one Malone feature that could fix it."}]},"GTUT49cgqQE":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.033,"text":"A design works beautifully in one"},{"start":2.033,"end":2.599,"text":"classroom."},{"start":2.939,"end":5.145,"text":"Then it goes to ten, and the results"},{"start":5.145,"end":5.598,"text":"scatter."},{"start":5.937,"end":8.426,"text":"This video explains why that happens, and"},{"start":8.426,"end":10.633,"text":"how implementation research studies it"},{"start":10.633,"end":11.821,"text":"instead of hiding it."},{"start":13.773,"end":14.988,"text":"Here is a toy example."},{"start":15.32,"end":17.639,"text":"Recipe Remix, a fractions activity with"},{"start":17.639,"end":20.18,"text":"Chef and Auditor roles, began in class A,"},{"start":20.18,"end":22.555,"text":"with research support, and the mean gain"},{"start":22.555,"end":24.322,"text":"there was two point four points."},{"start":25.323,"end":27.145,"text":"Now nine more classes try it."},{"start":27.522,"end":29.909,"text":"The gains range from point two to two"},{"start":29.909,"end":32.61,"text":"point six, and the average of all ten is"},{"start":32.61,"end":35.06,"text":"one point four three, well below the"},{"start":35.06,"end":35.436,"text":"pilot."},{"start":37.393,"end":40.176,"text":"Color the classes by one thing: did the"},{"start":40.176,"end":42.093,"text":"Auditor really ask for reasons?"},{"start":42.464,"end":45.184,"text":"Where the core was enacted, the mean gain"},{"start":45.184,"end":46.545,"text":"was two point one two."},{"start":46.916,"end":48.832,"text":"Where it was not, point four."},{"start":49.753,"end":51.664,"text":"This is an association, not proof."},{"start":51.983,"end":54.159,"text":"Teachers who kept the core may differ in"},{"start":54.159,"end":55.115,"text":"other ways, too."},{"start":57.043,"end":58.846,"text":"This is not a strange accident."},{"start":59.194,"end":61.52,"text":"William Penuel and colleagues note that"},{"start":61.52,"end":63.845,"text":"the effects of nearly all programs vary"},{"start":63.845,"end":66.055,"text":"significantly from setting to setting."},{"start":66.953,"end":69.125,"text":"They also recall an older finding:"},{"start":69.125,"end":71.405,"text":"teachers' adaptations in the classroom,"},{"start":71.405,"end":73.359,"text":"not policy makers' plans, largely"},{"start":73.359,"end":75.368,"text":"determine how effective a program is."},{"start":77.31,"end":79.263,"text":"Not all adaptation is the same."},{"start":79.64099999999999,"end":81.90899999999999,"text":"Class F swapped the strips for real"},{"start":81.90899999999999,"end":84.304,"text":"measuring cups, and still asked for"},{"start":84.304,"end":84.80799999999999,"text":"reasons."},{"start":85.186,"end":87.202,"text":"That is a productive adaptation."},{"start":88.08,"end":90.58500000000001,"text":"In class G, the teacher became the Auditor"},{"start":90.58500000000001,"end":92.755,"text":"and just marked answers right or wrong."},{"start":93.089,"end":95.42699999999999,"text":"The activity survived on paper, but the"},{"start":95.42699999999999,"end":96.206,"text":"core was gone."},{"start":97.16,"end":99.44800000000001,"text":"Ann Brown and Joseph Campione brought a"},{"start":99.44800000000001,"end":101.793,"text":"name for this into educational design,"},{"start":101.793,"end":104.36699999999999,"text":"crediting Ed Haertel: a lethal mutation."},{"start":105.21000000000001,"end":107.22399999999999,"text":"So the real question is not fidelity"},{"start":107.22399999999999,"end":108.20400000000001,"text":"versus adaptation."},{"start":108.531,"end":110.81700000000001,"text":"It is knowing which parts of a design are"},{"start":110.81700000000001,"end":112.613,"text":"core, and which parts can flex."},{"start":114.56700000000001,"end":116.82,"text":"Capacity is part of the design, too."},{"start":117.175,"end":119.487,"text":"When California reduced class sizes,"},{"start":119.487,"end":121.977,"text":"smaller classes raised achievement, but"},{"start":121.977,"end":124.29,"text":"hiring many inexperienced, not fully"},{"start":124.29,"end":126.661,"text":"certified teachers dampened the benefit."},{"start":128.587,"end":130.407,"text":"This is why Cynthia Coburn argued that"},{"start":130.407,"end":132.133,"text":"scale should mean more than counting"},{"start":132.133,"end":132.507,"text":"schools."},{"start":134.297,"end":136.34199999999998,"text":"She proposed four dimensions."},{"start":136.766,"end":139.869,"text":"Depth, change in beliefs and norms, not"},{"start":139.869,"end":140.927,"text":"just materials."},{"start":141.351,"end":144.313,"text":"Sustainability, change that lasts after"},{"start":144.313,"end":145.653,"text":"extra support ends."},{"start":146.677,"end":148.688,"text":"Spread, of the principles, including"},{"start":148.688,"end":149.816,"text":"within a single school."},{"start":150.11,"end":152.17000000000002,"text":"And a shift in ownership, so the reform"},{"start":152.17000000000002,"end":154.18099999999998,"text":"belongs to the teachers and schools that"},{"start":154.18099999999998,"end":154.622,"text":"carry it."},{"start":158.11,"end":160.372,"text":"Two research approaches were built for"},{"start":160.372,"end":160.662,"text":"this."},{"start":161.00900000000001,"end":163.155,"text":"Design based implementation research"},{"start":163.155,"end":165.591,"text":"treats implementation itself as something"},{"start":165.591,"end":167.736,"text":"to design and theorize, and builds"},{"start":167.736,"end":169.302,"text":"capacity to sustain change."},{"start":170.14,"end":172.737,"text":"Improvement science asks us to attend to"},{"start":172.737,"end":175.903,"text":"variability: not just what works, but what"},{"start":175.903,"end":178.183,"text":"works, for whom, and under what"},{"start":178.183,"end":178.88,"text":"conditions."},{"start":180.887,"end":183.077,"text":"So when you scale a design, study the"},{"start":183.077,"end":185.376,"text":"variation instead of averaging it away,"},{"start":185.376,"end":187.676,"text":"name your core components, redesign the"},{"start":187.676,"end":189.975,"text":"supports where the core broke, and plan"},{"start":189.975,"end":192.439,"text":"for depth, sustainability, spread, and"},{"start":192.439,"end":193.698,"text":"ownership from day one."},{"start":195.54,"end":197.593,"text":"For the discussion board, pick a design"},{"start":197.593,"end":198.912,"text":"you know and name its core."},{"start":199.206,"end":201.307,"text":"Then describe what a lethal mutation of it"},{"start":201.307,"end":203.067,"text":"would look like in a real classroom."}]},"Navj1yDN5-Q":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":5.762,"end":7.453,"text":"Put on a headset, and your room"},{"start":7.453,"end":8,"text":"disappears."},{"start":8.298,"end":9.989,"text":"You are standing inside a glowing"},{"start":9.989,"end":11.878,"text":"chemistry lab, and it feels amazing."},{"start":12.177,"end":14.265,"text":"But does feeling amazing mean you learned"},{"start":14.265,"end":14.514,"text":"more?"},{"start":16.775,"end":19.018,"text":"Meet two friends who study the same"},{"start":19.018,"end":20.389,"text":"virtual chemistry lab."},{"start":20.763,"end":22.32,"text":"Jordan works on a laptop."},{"start":22.694,"end":24.252,"text":"Riley wears a VR headset."},{"start":30.519,"end":32.268,"text":"Most people would bet on Riley."},{"start":32.607,"end":34.75,"text":"A real experiment tested exactly this"},{"start":34.75,"end":35.371,"text":"comparison."},{"start":37.289,"end":39.833,"text":"In twenty nineteen, Guido Makransky,"},{"start":39.833,"end":42.378,"text":"Thomas Terkildsen and Richard Mayer gave"},{"start":42.378,"end":44.798,"text":"fifty two university students the same"},{"start":44.798,"end":47.156,"text":"science lab simulation, either on a"},{"start":47.156,"end":49.266,"text":"desktop screen or in a VR headset."},{"start":51.375,"end":53.699,"text":"Here are the results, as effect sizes."},{"start":54.048,"end":56.604,"text":"Arrows to the right mean higher in VR;"},{"start":56.604,"end":58.696,"text":"arrows to the left mean lower in VR."},{"start":59.979,"end":61.104,"text":"First, presence."},{"start":61.479,"end":63.918,"text":"Students in VR felt far more like they"},{"start":63.918,"end":66.67,"text":"were really there, with an effect size of"},{"start":66.67,"end":67.67,"text":"one point three."},{"start":68.045,"end":69.233,"text":"That is very large."},{"start":72.57300000000001,"end":75.288,"text":"Presence is the felt sense of being inside"},{"start":75.288,"end":76.425,"text":"the virtual place."},{"start":76.803,"end":77.814,"text":"VR delivered it."},{"start":79.941,"end":81.445,"text":"Second, the learning test."},{"start":81.767,"end":84.13,"text":"The VR group scored lower, with an effect"},{"start":84.13,"end":86.17099999999999,"text":"size of zero point eight in the wrong"},{"start":86.17099999999999,"end":86.708,"text":"direction."},{"start":87.975,"end":89.451,"text":"Third, a brain measure."},{"start":89.805,"end":92.286,"text":"An E E G headband showed higher cognitive"},{"start":92.286,"end":94.707,"text":"load in VR, meaning working memory was"},{"start":94.707,"end":95.12,"text":"busier."},{"start":97.425,"end":100.158,"text":"The paper's title says it plainly: more"},{"start":100.158,"end":101.97999999999999,"text":"presence, but less learning."},{"start":105.509,"end":106.57300000000001,"text":"Why would this happen?"},{"start":106.863,"end":108.94200000000001,"text":"Picture working memory as a small backpack"},{"start":108.94200000000001,"end":110.344,"text":"you carry through the lesson."},{"start":110.63499999999999,"end":111.699,"text":"It only holds so much."},{"start":112.535,"end":114.53999999999999,"text":"On a desktop, the virtual world takes a"},{"start":114.53999999999999,"end":116.642,"text":"little space, which leaves plenty of room"},{"start":116.642,"end":117.358,"text":"for the lesson."},{"start":118.607,"end":121.201,"text":"In VR, the sights, the sounds and the new"},{"start":121.201,"end":122.555,"text":"controls take much more."},{"start":122.893,"end":125.036,"text":"The lesson gets squeezed into what is"},{"start":125.036,"end":125.318,"text":"left."},{"start":128.495,"end":130.275,"text":"It is a bit like trying to study for an"},{"start":130.275,"end":132.055,"text":"exam while you stand in the middle of a"},{"start":132.055,"end":132.768,"text":"busy theme park."},{"start":140.47899999999998,"end":141.236,"text":"Not at all."},{"start":141.648,"end":144.332,"text":"A meta analysis of forty eight studies"},{"start":144.332,"end":147.566,"text":"found that, on average, immersive VR has a"},{"start":147.566,"end":149.906,"text":"small positive effect on learning."},{"start":151.027,"end":153.258,"text":"But an average hides both wins and losses,"},{"start":153.258,"end":154.498,"text":"like the one we just saw."},{"start":154.796,"end":156.829,"text":"What decides which one you get is design."},{"start":159.589,"end":161.824,"text":"So how do we design for learning?"},{"start":162.231,"end":165.008,"text":"First, use VR where being there really"},{"start":165.008,"end":168.328,"text":"matters, such as space, scale, the body,"},{"start":168.328,"end":170.292,"text":"or places too risky to visit."},{"start":173.301,"end":175.734,"text":"Second, keep the virtual world calm when"},{"start":175.734,"end":178.167,"text":"the content is hard, so the scenery does"},{"start":178.167,"end":179.751,"text":"not compete with the lesson."},{"start":182.589,"end":184.285,"text":"Third, add a thinking task."},{"start":184.636,"end":186.917,"text":"Jocelyn Parong and Richard Mayer found"},{"start":186.917,"end":189.257,"text":"that asking learners to summarize after"},{"start":189.257,"end":191.597,"text":"each segment of a VR lesson helped them"},{"start":191.597,"end":191.948,"text":"learn."},{"start":194.852,"end":196.511,"text":"Back to our two friends."},{"start":196.926,"end":198.032,"text":"Riley felt more."},{"start":198.447,"end":199.82999999999998,"text":"Jordan learned more."},{"start":200.245,"end":202.457,"text":"Both things can be true at once."},{"start":203.48,"end":206.05,"text":"So remember: wow is a feeling, and"},{"start":206.05,"end":207.763,"text":"learning is a design result."},{"start":210.692,"end":212.39600000000002,"text":"These are the studies behind this video."}]},"LKY8wo6KoDw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.012,"text":"In part A, play became evidence."},{"start":2.345,"end":4.682,"text":"Part B shows how a Bayesian network turns"},{"start":4.682,"end":6.796,"text":"that evidence into beliefs about each"},{"start":6.796,"end":7.686,"text":"player's skills."},{"start":9.44,"end":11.441,"text":"Start with the Q matrix from part A."},{"start":11.774,"end":14.219,"text":"Each skill becomes a node at the top, and"},{"start":14.219,"end":16.109,"text":"each one in the matrix becomes an"},{"start":16.109,"end":18.554,"text":"observable node below, with an arrow from"},{"start":18.554,"end":19.777,"text":"the skill it measures."},{"start":20.82,"end":23.043,"text":"Skills can also depend on each other."},{"start":23.403,"end":25.866,"text":"Here, interpreting graphs makes causal"},{"start":25.866,"end":28.268,"text":"explanations more likely, so one more"},{"start":28.268,"end":29.29,"text":"arrow joins them."},{"start":30.08,"end":32.409,"text":"That picture, plus a probability table at"},{"start":32.409,"end":34.262,"text":"each node, is a Bayesian network."},{"start":36.243,"end":38.04,"text":"Each observable has a small table."},{"start":38.357,"end":40.629,"text":"A player who has mastered variable control"},{"start":40.629,"end":43.112,"text":"shows it eighty five percent of the time;"},{"start":43.112,"end":45.12,"text":"one who has not still shows it thirty"},{"start":45.12,"end":46.176,"text":"percent of the time."},{"start":46.983,"end":48.727,"text":"Those two errors have names."},{"start":49.101,"end":51.716,"text":"A slip is when a skilled player misses,"},{"start":51.716,"end":54.207,"text":"and a guess is when an unskilled player"},{"start":54.207,"end":56.76,"text":"gets lucky, like player B's lucky shot."},{"start":58.653,"end":60.172,"text":"Now watch one belief update."},{"start":60.498,"end":62.885,"text":"Before any play, we are fifty fifty about"},{"start":62.885,"end":64.838,"text":"whether player A controls variables."},{"start":65.703,"end":68.286,"text":"In level two, the evidence rule fires: one"},{"start":68.286,"end":69.164,"text":"slider at a time."},{"start":69.474,"end":71.695,"text":"Bayes' rule moves the belief to zero point"},{"start":71.695,"end":72.263,"text":"seven four."},{"start":77.383,"end":79.74,"text":"In level five it happens again, and the"},{"start":79.74,"end":81.929,"text":"belief rises to about zero point eight"},{"start":81.929,"end":82.21000000000001,"text":"nine."},{"start":82.547,"end":84.96000000000001,"text":"Evidence accumulates, like a detective's"},{"start":84.96000000000001,"end":85.297,"text":"notes."},{"start":87.07300000000001,"end":89.41,"text":"After all five levels, here is what the"},{"start":89.41,"end":90.355,"text":"network believes."},{"start":90.689,"end":92.97,"text":"Player A looks strong on all four skills."},{"start":93.923,"end":96.689,"text":"Player B is strong at reading graphs, but"},{"start":96.689,"end":99.518,"text":"weak at controlling variables, revising,"},{"start":99.518,"end":100.9,"text":"and explaining causes."},{"start":101.27799999999999,"end":103.60300000000001,"text":"Same three stars, a very different"},{"start":103.60300000000001,"end":104.106,"text":"profile."},{"start":106.02000000000001,"end":108.096,"text":"Where do numbers like zero point eight"},{"start":108.096,"end":110.012,"text":"five and zero point three come from?"},{"start":110.331,"end":112.513,"text":"With pilot data, a cognitive diagnosis"},{"start":112.513,"end":113.78999999999999,"text":"model can estimate them."},{"start":114.11,"end":116.345,"text":"Here we simulate two thousand players and"},{"start":116.345,"end":116.771,"text":"fit one."},{"start":117.67,"end":120.184,"text":"Most estimates land near the true values."},{"start":120.552,"end":122.944,"text":"But variable control and revision have"},{"start":122.944,"end":125.703,"text":"only two observables each in the Q matrix,"},{"start":125.703,"end":127.359,"text":"and their estimates wobble."},{"start":127.727,"end":129.812,"text":"Thin evidence gives shaky numbers."},{"start":130.77,"end":132.833,"text":"This also shows that cognitive diagnosis"},{"start":132.833,"end":134.795,"text":"models and Bayesian networks are close"},{"start":134.795,"end":135.298,"text":"relatives."},{"start":137.293,"end":139.125,"text":"Players also learn while they play."},{"start":139.44,"end":141.53300000000002,"text":"A dynamic Bayesian network carries each"},{"start":141.53300000000002,"end":143.889,"text":"belief from level to level, adding a small"},{"start":143.889,"end":145.459,"text":"chance of learning in between."},{"start":146.303,"end":148.602,"text":"Player A's belief climbs as the evidence"},{"start":148.602,"end":149.106,"text":"comes in."},{"start":149.442,"end":151.853,"text":"Player B's sinks, because each chance to"},{"start":151.853,"end":153.927,"text":"control variables goes by without it."},{"start":158.41,"end":160.667,"text":"The beliefs then drive the game."},{"start":161.09,"end":164.264,"text":"In a four process loop, the system selects"},{"start":164.264,"end":167.367,"text":"the next level, presents it, identifies"},{"start":167.367,"end":169.977,"text":"evidence, and accumulates it again."},{"start":170.94,"end":172.918,"text":"For player B, the weakest skill is causal"},{"start":172.918,"end":174.895,"text":"explanation, so the next level could be a"},{"start":174.895,"end":175.929,"text":"surprise that asks why."},{"start":176.199,"end":178.132,"text":"This is stealth assessment: measuring"},{"start":178.132,"end":179.3,"text":"without stopping the game."},{"start":182.167,"end":184.551,"text":"Before trusting these numbers, validate"},{"start":184.551,"end":186.992,"text":"the Q matrix, learn the tables from real"},{"start":186.992,"end":189.149,"text":"pilot data, compare with an outside"},{"start":189.149,"end":191.64600000000002,"text":"measure, and check fairness across groups."},{"start":193.597,"end":196.445,"text":"Here is the whole pipeline: claims shape"},{"start":196.445,"end":199.356,"text":"levels, the Q matrix links them to skills,"},{"start":199.356,"end":202.143,"text":"evidence rules turn logs into observables,"},{"start":202.143,"end":204.93,"text":"the network updates beliefs, and decisions"},{"start":204.93,"end":207.345,"text":"feed back into the game and its design."},{"start":208.177,"end":209.245,"text":"And our two players?"},{"start":209.566,"end":211.65,"text":"Same three stars, but very different"},{"start":211.65,"end":213.253,"text":"evidence about how they think."},{"start":213.573,"end":215.871,"text":"That is what a game can tell us, when it"},{"start":215.871,"end":217.046,"text":"is designed to listen."}]},"XC_5YE2YYoY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.04,"end":2.168,"text":"How can a game tell us what a learner"},{"start":2.168,"end":4.688,"text":"knows, without stopping the game to give a"},{"start":4.688,"end":4.968,"text":"test?"},{"start":5.304,"end":7.712,"text":"This is part one of a two part story about"},{"start":7.712,"end":8.944,"text":"game based assessment."},{"start":10.873,"end":13.084,"text":"Meet Launch Lab, a small physics game."},{"start":13.416,"end":16.125,"text":"Players set the angle, speed, and gravity,"},{"start":16.125,"end":17.562,"text":"and try to hit the target."},{"start":18.443,"end":20.749,"text":"Player A changes only the angle, misses"},{"start":20.749,"end":23.22,"text":"short, changes the angle again, and hits"},{"start":23.22,"end":23.824,"text":"the target."},{"start":26.753,"end":29.03,"text":"Player B changes all three sliders at"},{"start":29.03,"end":31.486,"text":"once, overshoots, changes everything"},{"start":31.486,"end":32.984,"text":"again, and hits it too."},{"start":39.143,"end":40.66,"text":"Same stars, same score."},{"start":41.025,"end":43.634,"text":"But only player A tested one variable at a"},{"start":43.634,"end":43.937,"text":"time."},{"start":44.302,"end":46.668,"text":"Game based assessment is about reading"},{"start":46.668,"end":47.639,"text":"that difference."},{"start":49.653,"end":52.191,"text":"The design idea behind this is evidence"},{"start":52.191,"end":54.919,"text":"centered design, or E C D, from Robert"},{"start":54.919,"end":56.378,"text":"Mislevy and colleagues."},{"start":56.759,"end":59.614,"text":"It starts with a claim, asks what evidence"},{"start":59.614,"end":62.405,"text":"would support it, and only then designs a"},{"start":62.405,"end":62.723,"text":"task."},{"start":63.723,"end":65.394,"text":"A road test works the same way."},{"start":65.717,"end":67.98,"text":"To claim someone drives safely, we look"},{"start":67.98,"end":70.35,"text":"for mirror checks before lane changes, so"},{"start":70.35,"end":72.28999999999999,"text":"the route must include lane changes."},{"start":73.253,"end":75.627,"text":"So an assessment is an argument, from what"},{"start":75.627,"end":77.737,"text":"learners do to what we claim about them."},{"start":79.687,"end":82.212,"text":"E C D organizes this into three linked"},{"start":82.212,"end":85.255,"text":"models: a competency model, an evidence"},{"start":85.255,"end":86.938,"text":"model, and a task model."},{"start":87.81700000000001,"end":90.481,"text":"In Launch Lab, the competency model is"},{"start":90.481,"end":93.729,"text":"causal reasoning, broken into four skills:"},{"start":93.729,"end":96.523,"text":"controlling variables, revising ideas,"},{"start":96.523,"end":98.99199999999999,"text":"interpreting graphs, and explaining"},{"start":98.99199999999999,"end":99.447,"text":"causes."},{"start":100.34700000000001,"end":102.672,"text":"These are latent skills: we cannot see"},{"start":102.672,"end":104.89099999999999,"text":"them, only infer them from what players"},{"start":104.89099999999999,"end":105.05,"text":"do."},{"start":106.94,"end":109.055,"text":"The task model shapes the levels."},{"start":109.44,"end":112.068,"text":"Each level has features chosen to make a"},{"start":112.068,"end":114.375,"text":"particular kind of thinking visible."},{"start":115.39,"end":118.017,"text":"For example, level four deliberately"},{"start":118.017,"end":120.712,"text":"produces a surprising result, because"},{"start":120.712,"end":123.339,"text":"revising an idea only shows up after a"},{"start":123.339,"end":123.946,"text":"surprise."},{"start":125.997,"end":128.181,"text":"The bridge between levels and skills is"},{"start":128.181,"end":128.891,"text":"the Q matrix."},{"start":129.219,"end":131.731,"text":"Each row is a level, each column a skill,"},{"start":131.731,"end":133.971,"text":"and a one means the level gives evidence"},{"start":133.971,"end":134.899,"text":"about that skill."},{"start":135.827,"end":138.406,"text":"Level four, for instance, informs three"},{"start":138.406,"end":140.692,"text":"skills at once: revision, graph"},{"start":140.692,"end":143.095,"text":"interpretation, and causal explanation."},{"start":148.267,"end":148.423,"text":"No."},{"start":148.736,"end":150.821,"text":"Its variable control cell is zero, so"},{"start":150.821,"end":152.803,"text":"nothing a player does there counts as"},{"start":152.803,"end":154.054,"text":"evidence for that skill."},{"start":154.857,"end":157.091,"text":"A Q matrix is a claim in itself, so it"},{"start":157.091,"end":158.017,"text":"must be defended."},{"start":158.344,"end":160.633,"text":"Turning on cells without a reason makes a"},{"start":160.633,"end":162.976,"text":"diagnosis look more precise than it really"},{"start":162.976,"end":163.14,"text":"is."},{"start":165.083,"end":166.53,"text":"Now the evidence model."},{"start":166.90699999999998,"end":169.674,"text":"Underneath the game, every action becomes"},{"start":169.674,"end":172.379,"text":"a row in a log: predictions, slider"},{"start":172.379,"end":174.768,"text":"changes, runs, graph views, and"},{"start":174.768,"end":175.586,"text":"explanations."},{"start":176.383,"end":178.623,"text":"Evidence rules turn those rows into a few"},{"start":178.623,"end":179.903,"text":"meaningful observations."},{"start":180.223,"end":182.41,"text":"Changing only one slider before each run"},{"start":182.41,"end":184.383,"text":"becomes evidence of variable control."},{"start":186.323,"end":188.464,"text":"Each one in the Q matrix becomes one such"},{"start":188.464,"end":189.024,"text":"observable."},{"start":189.33,"end":191.47,"text":"Recording clicks without rules like these"},{"start":191.47,"end":193.814,"text":"is just logging; the rules are what make"},{"start":193.814,"end":194.528,"text":"it assessment."},{"start":196.53,"end":199.61599999999999,"text":"So far we have claims, tasks, a Q matrix,"},{"start":199.61599999999999,"end":200.837,"text":"and evidence rules."},{"start":201.223,"end":204.051,"text":"In part B, a Bayesian network turns those"},{"start":204.051,"end":206.623,"text":"observations into updated beliefs about"},{"start":206.623,"end":207.394,"text":"each player."}]},"Cn2KU6ooubI":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.11,"end":2.055,"text":"Design based research almost always"},{"start":2.055,"end":3.027,"text":"involves partners."},{"start":3.351,"end":5.62,"text":"Two words describe that partnership, co"},{"start":5.62,"end":7.997,"text":"design and participatory design, and they"},{"start":7.997,"end":10.211,"text":"are often used as if they meant the same"},{"start":10.211,"end":12.156,"text":"thing, although they do not quite."},{"start":14.16,"end":16.484,"text":"Picture the team designing an A I feedback"},{"start":16.484,"end":17.889,"text":"tool for a writing course."},{"start":18.213,"end":20.644,"text":"Who sits at the design table, and who gets"},{"start":20.644,"end":22.536,"text":"to decide what the problem even is?"},{"start":24.56,"end":27.018,"text":"In one version, teachers join facilitated"},{"start":27.018,"end":29.196,"text":"sessions in defined roles to shape the"},{"start":29.196,"end":29.475,"text":"tool."},{"start":29.81,"end":32.324,"text":"In another, students and community members"},{"start":32.324,"end":34.446,"text":"help decide the problem itself, who"},{"start":34.446,"end":36.345,"text":"benefits, and who owns the data."},{"start":42.36,"end":44.694,"text":"Scenario A is typical of co design, and"},{"start":44.694,"end":46.639,"text":"scenario B of participatory design."},{"start":46.973,"end":49.418,"text":"The difference is less about who attends,"},{"start":49.418,"end":51.641,"text":"and more about who holds power over the"},{"start":51.641,"end":52.197,"text":"decisions."},{"start":54,"end":56.295,"text":"Participatory design began in Scandinavian"},{"start":56.295,"end":58.164,"text":"workplace projects of the nineteen"},{"start":58.164,"end":60.513,"text":"seventies and eighties, where workers and"},{"start":60.513,"end":62.595,"text":"their unions helped shape the computer"},{"start":62.595,"end":64.57,"text":"systems that would change their jobs."},{"start":65.56,"end":67.887,"text":"Its core commitment is political as well"},{"start":67.887,"end":70.554,"text":"as practical: people affected by a design"},{"start":70.554,"end":72.825,"text":"should have a real say in it, through"},{"start":72.825,"end":74.981,"text":"mutual learning and shared power over"},{"start":74.981,"end":76.059,"text":"goals and outcomes."},{"start":78.01,"end":80.202,"text":"Co design is a broader term from design"},{"start":80.202,"end":80.696,"text":"practice."},{"start":81.025,"end":83.327,"text":"Elizabeth Sanders and Pieter Jan Stappers"},{"start":83.327,"end":85.574,"text":"describe it as the collective creativity"},{"start":85.574,"end":87.711,"text":"of designers and people not trained in"},{"start":87.711,"end":89.191,"text":"design, working together."},{"start":90.11,"end":93.069,"text":"In education, Jeremy Roschelle, William"},{"start":93.069,"end":96.02799999999999,"text":"Penuel, and Nicole Shechtman described co"},{"start":96.02799999999999,"end":99.055,"text":"design as a highly facilitated, team based"},{"start":99.055,"end":102.283,"text":"process, where teachers, researchers, and"},{"start":102.283,"end":104.70400000000001,"text":"developers work in defined roles to"},{"start":104.70400000000001,"end":107.327,"text":"design, prototype, and evaluate an"},{"start":107.327,"end":108.066,"text":"innovation."},{"start":109.07,"end":111.294,"text":"The emphasis here is fit to real"},{"start":111.294,"end":113.652,"text":"classrooms, drawing on teachers'"},{"start":113.652,"end":116.41499999999999,"text":"expertise, rather than a commitment to"},{"start":116.41499999999999,"end":117.696,"text":"redistribute power."},{"start":119.61,"end":121.56,"text":"It helps to picture participation as a"},{"start":121.56,"end":123.26,"text":"ladder, rather than a yes or no."},{"start":125.05,"end":127.285,"text":"Allison Druin described four roles"},{"start":127.285,"end":130.351,"text":"children can play in designing technology:"},{"start":130.351,"end":133.033,"text":"user, tester, informant, and design"},{"start":133.033,"end":135.907,"text":"partner, each with more influence than the"},{"start":135.907,"end":136.227,"text":"last."},{"start":137.14,"end":139.394,"text":"Co design usually sits from tester to"},{"start":139.394,"end":140.284,"text":"design partner."},{"start":140.64,"end":143.309,"text":"Participatory design aims for the top, and"},{"start":143.309,"end":145.86,"text":"adds a real say over goals and outcomes,"},{"start":145.86,"end":147.224,"text":"not just over features."},{"start":149.207,"end":152.454,"text":"Side by side, co design grew from design"},{"start":152.454,"end":154.796,"text":"practice and research practice"},{"start":154.796,"end":158.04399999999998,"text":"partnerships, and values fit to practice."},{"start":158.497,"end":161.594,"text":"Participatory design grew from workplace"},{"start":161.594,"end":164.69,"text":"democracy, and values voice and shared"},{"start":164.69,"end":165.143,"text":"power."},{"start":166.117,"end":168.41,"text":"The sharpest difference is who sets the"},{"start":168.41,"end":168.754,"text":"goals."},{"start":169.098,"end":171.793,"text":"Each also has its own risk: co design can"},{"start":171.793,"end":174.144,"text":"become consultation that only looks like"},{"start":174.144,"end":176.667,"text":"partnership, and participatory design can"},{"start":176.667,"end":178.273,"text":"be slow and hard to sustain."},{"start":180.21,"end":182.493,"text":"Inside design based research, the"},{"start":182.493,"end":184.775,"text":"participatory tradition shows up as"},{"start":184.775,"end":187.629,"text":"participatory design research, which Megan"},{"start":187.629,"end":190.038,"text":"Bang and Shirin Vossoughi describe as"},{"start":190.038,"end":192.955,"text":"attending to power, history, and who gets"},{"start":192.955,"end":194.16,"text":"to define learning."},{"start":195.13,"end":197.464,"text":"Whichever label you use, report it"},{"start":197.464,"end":200.493,"text":"honestly by answering three questions: who"},{"start":200.493,"end":203.269,"text":"defined the problem, who could change the"},{"start":203.269,"end":206.108,"text":"design and the goals, and who benefits and"},{"start":206.108,"end":206.99099999999999,"text":"owns the data."},{"start":208.897,"end":211.101,"text":"For the discussion board, find a study"},{"start":211.101,"end":212.768,"text":"that says it used co design or"},{"start":212.768,"end":215.133,"text":"participatory design, and decide where on"},{"start":215.133,"end":217.552,"text":"the ladder its partners really were, based"},{"start":217.552,"end":219.004,"text":"on what the authors report."}]},"pR--9zWzm30":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.03,"text":"Learning sciences and the science of"},{"start":2.03,"end":4.249,"text":"learning sound almost the same, but they"},{"start":4.249,"end":6.313,"text":"grew from different communities and ask"},{"start":6.313,"end":7.81,"text":"different kinds of questions."},{"start":8.12,"end":10.287,"text":"This video traces how each one evolved,"},{"start":10.287,"end":11.99,"text":"and why one of them ends in an s."},{"start":13.913,"end":15.871,"text":"Imagine two researchers who both care"},{"start":15.871,"end":17.674,"text":"about how children learn fractions."},{"start":18.533,"end":20.658,"text":"One asks whether spacing out practice"},{"start":20.658,"end":22.28,"text":"improves recall a week later."},{"start":22.616,"end":24.965,"text":"The other asks how a redesigned classroom"},{"start":24.965,"end":27.146,"text":"activity changes the way a whole class"},{"start":27.146,"end":28.488,"text":"reasons over a semester."},{"start":33.633,"end":35.499,"text":"The first question is typical of the"},{"start":35.499,"end":37.769,"text":"science of learning, and the second of the"},{"start":37.769,"end":38.676,"text":"learning sciences."},{"start":38.979,"end":41.097,"text":"To see why, it helps to follow how each"},{"start":41.097,"end":41.551,"text":"one grew."},{"start":43.407,"end":45.399,"text":"The learning sciences took shape around"},{"start":45.399,"end":47.541,"text":"nineteen ninety one, when the Journal of"},{"start":47.541,"end":49.335,"text":"the Learning Sciences and the first"},{"start":49.335,"end":51.178,"text":"international conference appeared,"},{"start":51.178,"end":52.722,"text":"building on a new institute at"},{"start":52.722,"end":53.918,"text":"Northwestern University."},{"start":54.817,"end":56.821,"text":"Its founders came largely from cognitive"},{"start":56.821,"end":58.923,"text":"science and artificial intelligence, but"},{"start":58.923,"end":60.781,"text":"they wanted to study learning in real"},{"start":60.781,"end":62.932,"text":"settings, and to learn by designing tools"},{"start":62.932,"end":63.763,"text":"and environments."},{"start":64.687,"end":66.687,"text":"In two thousand two, the International"},{"start":66.687,"end":68.687,"text":"Society of the Learning Sciences brought"},{"start":68.687,"end":70.833,"text":"the conferences and the journal together,"},{"start":70.833,"end":72.589,"text":"and in two thousand six a Cambridge"},{"start":72.589,"end":74.394,"text":"handbook gave the field a shared map."},{"start":76.337,"end":77.15,"text":"So why the s?"},{"start":77.525,"end":80.02799999999999,"text":"The name is plural because the field is"},{"start":80.02799999999999,"end":82.906,"text":"plural: cognitive science, educational"},{"start":82.906,"end":85.033,"text":"psychology, computer science,"},{"start":85.033,"end":87.911,"text":"anthropology, and more, each bringing its"},{"start":87.911,"end":88.661,"text":"own methods."},{"start":89.517,"end":91.589,"text":"Read the plural as a statement about"},{"start":91.589,"end":93.99799999999999,"text":"method: no single discipline owns the"},{"start":93.99799999999999,"end":95.175,"text":"question of learning."},{"start":95.511,"end":97.807,"text":"That is also why you will often hear the"},{"start":97.807,"end":100.21600000000001,"text":"learning sciences is, a plural name used"},{"start":100.21600000000001,"end":101.001,"text":"for one field."},{"start":102.987,"end":105.18299999999999,"text":"The science of learning grew along a"},{"start":105.18299999999999,"end":106.074,"text":"different path."},{"start":106.43,"end":108.686,"text":"In two thousand three, the National"},{"start":108.686,"end":111.06,"text":"Science Foundation announced Science of"},{"start":111.06,"end":113.672,"text":"Learning Centers, large centers that were"},{"start":113.672,"end":115.69,"text":"first funded in two thousand four."},{"start":116.547,"end":119.025,"text":"In two thousand nine, Andrew Meltzoff,"},{"start":119.025,"end":121.331,"text":"Patricia Kuhl, Javier Movellan, and"},{"start":121.331,"end":123.809,"text":"Terrence Sejnowski described a new science"},{"start":123.809,"end":126.172,"text":"of learning in the journal Science:"},{"start":126.172,"end":128.535,"text":"learning is computational, learning is"},{"start":128.535,"end":130.783,"text":"social, and it is supported by brain"},{"start":130.783,"end":133.031,"text":"circuits linking perception and action."},{"start":133.987,"end":136.007,"text":"Here the singular signals a goal of"},{"start":136.007,"end":138.308,"text":"convergence: several fields, from"},{"start":138.308,"end":140.497,"text":"psychology to neuroscience and machine"},{"start":140.497,"end":142.85399999999998,"text":"learning, working toward one account of"},{"start":142.85399999999998,"end":143.92000000000002,"text":"how learning works."},{"start":144.777,"end":147.673,"text":"For teachers, this tradition often arrives"},{"start":147.673,"end":150.569,"text":"as principles, like retrieval practice and"},{"start":150.569,"end":153.401,"text":"spacing, summarized in guides such as the"},{"start":153.401,"end":156.105,"text":"Deans for Impact report, The Science of"},{"start":156.105,"end":158.55,"text":"Learning, from two thousand fifteen."},{"start":160.453,"end":162.548,"text":"Put side by side, the science of learning"},{"start":162.548,"end":164.547,"text":"asks how learning works, mostly through"},{"start":164.547,"end":166.689,"text":"controlled experiments, while the learning"},{"start":166.689,"end":168.641,"text":"sciences ask how to make learning happen"},{"start":168.641,"end":170.688,"text":"in a real setting, mostly through design"},{"start":170.688,"end":171.688,"text":"and study in context."},{"start":172.583,"end":174.945,"text":"The science of learning usually studies"},{"start":174.945,"end":177.13,"text":"the individual mind and brain, and"},{"start":177.13,"end":178.784,"text":"produces general principles."},{"start":179.138,"end":181.5,"text":"The learning sciences study people with"},{"start":181.5,"end":184.275,"text":"tools, in groups and settings, and produce"},{"start":184.275,"end":186.519,"text":"designs with theories tied to context."},{"start":187.473,"end":188.903,"text":"Each one has a blind spot."},{"start":189.232,"end":191.211,"text":"A lab principle can fail in a noisy"},{"start":191.211,"end":193.575,"text":"classroom, and a classroom design can be"},{"start":193.575,"end":195.664,"text":"hard to generalize beyond the setting"},{"start":195.664,"end":196.434,"text":"where it grew."},{"start":198.387,"end":200.309,"text":"In practice the two traditions meet more"},{"start":200.309,"end":202.325,"text":"and more, and some of the best work sits"},{"start":202.325,"end":203.215,"text":"right between them."},{"start":204.977,"end":207.475,"text":"The Pittsburgh Science of Learning Center,"},{"start":207.475,"end":209.862,"text":"led by Kenneth Koedinger, ran controlled"},{"start":209.862,"end":212.305,"text":"experiments inside real courses, which it"},{"start":212.305,"end":213.804,"text":"called in vivo experiments."},{"start":214.90699999999998,"end":217.535,"text":"Another center, LIFE, studied learning in"},{"start":217.535,"end":219.877,"text":"informal and formal environments, from"},{"start":219.877,"end":221.534,"text":"homes and museums to schools."},{"start":222.517,"end":224.418,"text":"So a principle from the lab can become a"},{"start":224.418,"end":226.36599999999999,"text":"design conjecture in a classroom, and a"},{"start":226.36599999999999,"end":228.314,"text":"pattern noticed in a classroom can become"},{"start":228.314,"end":229.798,"text":"a hypothesis to test in the lab."},{"start":230.667,"end":233.56,"text":"For our two fraction researchers, that"},{"start":233.56,"end":236.382,"text":"means the spacing study could shape the"},{"start":236.382,"end":239.275,"text":"pizza activity, and the pizza activity"},{"start":239.275,"end":241.533,"text":"could reveal when spacing helps."},{"start":243.53,"end":245.552,"text":"For the discussion board, pick one claim"},{"start":245.552,"end":246.728,"text":"from this week's reading."},{"start":247.01,"end":249.032,"text":"Decide whether its evidence comes from the"},{"start":249.032,"end":250.725,"text":"science of learning or the learning"},{"start":250.725,"end":252.841,"text":"sciences, and ask what the other tradition"},{"start":252.841,"end":254.628,"text":"would want to see before believing it."}]},"NdaVj7XmiEU":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.458,"text":"What does a design based research project"},{"start":2.458,"end":4.963,"text":"actually look like, from the first meeting"},{"start":4.963,"end":6.021,"text":"to the final paper?"},{"start":6.355,"end":8.582,"text":"This video walks through the journey,"},{"start":8.582,"end":10.976,"text":"stage by stage, with one running example."},{"start":12.86,"end":15.636,"text":"Most accounts share five broad stages:"},{"start":15.636,"end":17.781,"text":"ground the problem, prepare the"},{"start":17.781,"end":20.684,"text":"experiment, run design cycles, analyze in"},{"start":20.684,"end":23.081,"text":"retrospect, and report and redesign."},{"start":23.97,"end":26.671,"text":"The arrow back matters: each report feeds"},{"start":26.671,"end":27.533,"text":"the next cycle."},{"start":27.878,"end":30.291,"text":"Our example is an A I feedback tool for a"},{"start":30.291,"end":31.785,"text":"first year writing course."},{"start":35.893,"end":37.544,"text":"Stage one grounds the problem."},{"start":37.874,"end":40.571,"text":"You meet partners, observe, and interview,"},{"start":40.571,"end":42.717,"text":"and read the research, to learn what"},{"start":42.717,"end":44.643,"text":"actually happens to feedback today."},{"start":45.543,"end":47.489,"text":"You leave with a problem of practice"},{"start":47.489,"end":49.803,"text":"stated together with partners: here,"},{"start":49.803,"end":51.96,"text":"students read feedback but rarely revise"},{"start":51.96,"end":52.328,"text":"deeply."},{"start":54.207,"end":56.031,"text":"Stage two prepares the experiment."},{"start":56.353,"end":58.768,"text":"You set learning goals, describe students'"},{"start":58.768,"end":61.021,"text":"starting points, and write a high level"},{"start":61.021,"end":63.704,"text":"conjecture: feedback that asks a question,"},{"start":63.704,"end":66.012,"text":"instead of giving a fix, leads to deeper"},{"start":66.012,"end":66.495,"text":"revision."},{"start":67.337,"end":69.248,"text":"William Sandoval's conjecture map makes"},{"start":69.248,"end":71.35,"text":"this testable: the design's embodiment"},{"start":71.35,"end":73.404,"text":"should produce mediating processes you can"},{"start":73.404,"end":75.553,"text":"observe, which should lead to the outcomes"},{"start":75.553,"end":76.27,"text":"you care about."},{"start":77.247,"end":79.906,"text":"You also plan the data that will show each"},{"start":79.906,"end":82.751,"text":"arrow, such as drafts, tool logs, class"},{"start":82.751,"end":84.236,"text":"video, and interviews."},{"start":86.32300000000001,"end":88.557,"text":"Stage three runs the design in a real"},{"start":88.557,"end":88.968,"text":"course."},{"start":89.321,"end":91.907,"text":"Each full enactment is a macro cycle, and"},{"start":91.907,"end":94.435,"text":"inside it run many mini cycles of debriefs"},{"start":94.435,"end":95.61099999999999,"text":"and small revisions."},{"start":96.60300000000001,"end":98.697,"text":"Keep a design log of every change and why"},{"start":98.697,"end":100.441,"text":"you made it, because the changes"},{"start":100.441,"end":102.485,"text":"themselves are data about how the design"},{"start":102.485,"end":102.78399999999999,"text":"works."},{"start":104.843,"end":105.965,"text":"Stage four steps back."},{"start":106.27199999999999,"end":108.51599999999999,"text":"After the enactment ends, you analyze the"},{"start":108.51599999999999,"end":110.607,"text":"whole body of data systematically, not"},{"start":110.607,"end":112.137,"text":"just the moments you remember."},{"start":114.063,"end":116.47399999999999,"text":"You test each arrow of the conjecture map."},{"start":116.818,"end":119.458,"text":"In our example, students did write plans,"},{"start":119.458,"end":121.811,"text":"but deeper revision followed only when a"},{"start":121.811,"end":124.05,"text":"plan named a specific change, so the"},{"start":124.05,"end":125.829,"text":"conjecture itself gets revised."},{"start":129.407,"end":132.13400000000001,"text":"Stage five reports what was learned: a"},{"start":132.13400000000001,"end":134.737,"text":"humble theory of how the design worked,"},{"start":134.737,"end":137.34,"text":"design principles others can try, and a"},{"start":137.34,"end":139.385,"text":"better design for the next cycle."},{"start":140.347,"end":142.60399999999998,"text":"To be trusted, the report needs a clear"},{"start":142.60399999999998,"end":144.538,"text":"design narrative and claims tied to"},{"start":144.538,"end":146.956,"text":"evidence, and it generalizes by explaining"},{"start":146.956,"end":149.375,"text":"why the design worked, so others can judge"},{"start":149.375,"end":150.664,"text":"where it might transfer."},{"start":152.587,"end":154.81799999999998,"text":"For the discussion board, write a high"},{"start":154.81799999999998,"end":156.941,"text":"level conjecture for a project of your"},{"start":156.941,"end":159.391,"text":"own, sketch its conjecture map, and name"},{"start":159.391,"end":161.35,"text":"the data that would show each arrow."}]},"XN29cK9FYMY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.12,"end":2.747,"text":"Design based research, educational design"},{"start":2.747,"end":5.075,"text":"research, and design and development"},{"start":5.075,"end":7.523,"text":"research all study learning by designing"},{"start":7.523,"end":8.12,"text":"something."},{"start":8.478,"end":10.866,"text":"This video compares where each one came"},{"start":10.866,"end":13.254,"text":"from, what it aims for, and what it"},{"start":13.254,"end":13.792,"text":"produces."},{"start":15.583,"end":17.607,"text":"Imagine a team building an A I feedback"},{"start":17.607,"end":19.48,"text":"tool for a first year writing course."},{"start":20.523,"end":22.746,"text":"They could ask how feedback timing shapes"},{"start":22.746,"end":24.809,"text":"revision, what design works in these"},{"start":24.809,"end":26.979,"text":"courses, or whether their design model"},{"start":26.979,"end":28.196,"text":"produced a usable tool."},{"start":33.333,"end":35.586,"text":"Roughly, the first leans toward design"},{"start":35.586,"end":37.563,"text":"based research, the second toward"},{"start":37.563,"end":40.036,"text":"educational design research, and the third"},{"start":40.036,"end":42.178,"text":"toward design and development research."},{"start":42.508,"end":44.925,"text":"All three share a core, but their centers"},{"start":44.925,"end":45.914,"text":"of gravity differ."},{"start":47.743,"end":50.018,"text":"Design based research grew in the learning"},{"start":50.018,"end":51.923,"text":"sciences, from Ann Brown's design"},{"start":51.923,"end":54.198,"text":"experiments and Allan Collins's call for a"},{"start":54.198,"end":56.261,"text":"design science of education, and was"},{"start":56.261,"end":58.43,"text":"popularized by the Design Based Research"},{"start":58.43,"end":60.176,"text":"Collective in two thousand three."},{"start":60.943,"end":62.746,"text":"Its hallmark is iteration in real"},{"start":62.746,"end":65.132,"text":"classrooms, where each version of a design"},{"start":65.132,"end":67.517,"text":"tests a conjecture about learning, and the"},{"start":67.517,"end":69.691,"text":"main contribution is a theory of how and"},{"start":69.691,"end":71.175,"text":"why learning happened there."},{"start":72.053,"end":73.878,"text":"Paul Cobb and colleagues called these"},{"start":73.878,"end":75.99,"text":"humble theories, because they are tied to"},{"start":75.99,"end":77.67099999999999,"text":"a domain and a setting rather than"},{"start":77.67099999999999,"end":79.015,"text":"claiming to hold everywhere."},{"start":80.953,"end":83,"text":"Educational design research is often used"},{"start":83,"end":85.04599999999999,"text":"as an umbrella term for this whole family."},{"start":85.339,"end":87.385,"text":"Susan McKenney and Thomas Reeves describe"},{"start":87.385,"end":89.383,"text":"it as solving a real problem in practice"},{"start":89.383,"end":91.381,"text":"while producing knowledge others can use."},{"start":92.283,"end":94.875,"text":"Its generic model has four phases, from"},{"start":94.875,"end":97.529,"text":"analysis and exploration to implementation"},{"start":97.529,"end":100.306,"text":"and spread, and it aims for two outputs at"},{"start":100.306,"end":103.083,"text":"once: an intervention that works, and"},{"start":103.083,"end":105.737,"text":"theoretical understanding, often written"},{"start":105.737,"end":107.033,"text":"as design principles."},{"start":110.55,"end":112.987,"text":"Design and development research comes from"},{"start":112.987,"end":115.02799999999999,"text":"instructional design and technology."},{"start":115.368,"end":117.805,"text":"Rita Richey and James Klein describe it as"},{"start":117.805,"end":119.733,"text":"the systematic study of design,"},{"start":119.733,"end":122,"text":"development, and evaluation processes."},{"start":122.95,"end":125.809,"text":"They distinguish two types: product and"},{"start":125.809,"end":128.731,"text":"tool research, which studies one product,"},{"start":128.731,"end":131.526,"text":"program, or tool, and model research,"},{"start":131.526,"end":134.13,"text":"which builds or validates a design model"},{"start":134.13,"end":134.829,"text":"or process."},{"start":135.92,"end":138.23,"text":"Here the knowledge produced is mainly"},{"start":138.23,"end":140.845,"text":"about designing and developing instruction"},{"start":140.845,"end":143.459,"text":"itself, so methods like expert review,"},{"start":143.459,"end":145.77,"text":"case studies, and Delphi panels are"},{"start":145.77,"end":146.195,"text":"common."},{"start":148.097,"end":150.769,"text":"Side by side, the differences are mostly"},{"start":150.769,"end":153.566,"text":"differences of emphasis: where each one"},{"start":153.566,"end":156.176,"text":"grew up, and what it treats as the main"},{"start":156.176,"end":156.984,"text":"contribution."},{"start":157.977,"end":160.21699999999998,"text":"Design based research puts a theory of"},{"start":160.21699999999998,"end":161.079,"text":"learning first."},{"start":161.424,"end":163.895,"text":"Educational design research puts a working"},{"start":163.895,"end":166.078,"text":"solution plus design principles first."},{"start":166.423,"end":168.779,"text":"Design and development research puts the"},{"start":168.779,"end":170.962,"text":"design process and its products first."},{"start":171.827,"end":174.482,"text":"What they share matters just as much:"},{"start":174.482,"end":177.26,"text":"iteration, real settings, design treated"},{"start":177.26,"end":179.236,"text":"as inquiry, and mixed methods."},{"start":181.397,"end":182.538,"text":"So how do you choose?"},{"start":182.864,"end":185.2,"text":"Ask what your main contribution will be,"},{"start":185.2,"end":186.831,"text":"and let that decide the frame."},{"start":188.777,"end":191.307,"text":"If it is a claim about how people learn,"},{"start":191.307,"end":192.897,"text":"design based research fits."},{"start":193.25,"end":195.722,"text":"If it is a solution to a practice problem"},{"start":195.722,"end":198.135,"text":"and its principles, educational design"},{"start":198.135,"end":198.959,"text":"research fits."},{"start":199.312,"end":202.196,"text":"If it is a design model, process, or tool,"},{"start":202.196,"end":204.374,"text":"design and development research fits."},{"start":205.387,"end":207.615,"text":"Whichever you choose, avoid the common"},{"start":207.615,"end":209.626,"text":"trap of only reporting that a design"},{"start":209.626,"end":210.006,"text":"worked."},{"start":210.332,"end":212.234,"text":"Design research also says what was"},{"start":212.234,"end":213.811,"text":"learned, and why it worked."},{"start":215.773,"end":218.129,"text":"For the discussion board, take one project"},{"start":218.129,"end":220.222,"text":"idea of your own and write its research"},{"start":220.222,"end":221.269,"text":"question three ways."},{"start":221.583,"end":223.46699999999998,"text":"Then decide which version you would"},{"start":223.46699999999998,"end":225.299,"text":"actually defend, and explain why."}]},"A0xi0-qjIMA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.456,"text":"The final part of this series is network"},{"start":2.456,"end":4.618,"text":"meta analysis, which compares many"},{"start":4.618,"end":7.13,"text":"treatments at once, even pairs that were"},{"start":7.13,"end":8.649,"text":"never tested head to head."},{"start":10.46,"end":13.005,"text":"Our example has 24 trials of four ways to"},{"start":13.005,"end":16.034,"text":"help people quit smoking: no contact, self"},{"start":16.034,"end":18.64,"text":"help, individual counseling, and group"},{"start":18.64,"end":19.306,"text":"counseling."},{"start":20.148,"end":22.984,"text":"Each line is a direct comparison, thicker"},{"start":22.984,"end":24.659,"text":"when more studies made it."},{"start":25.046,"end":27.624,"text":"Individual counseling versus no contact"},{"start":27.624,"end":30.073,"text":"was tested fifteen times, but group"},{"start":30.073,"end":32.651,"text":"counseling versus no contact only twice."},{"start":33.515,"end":35.826,"text":"Results are odds ratios, where a value"},{"start":35.826,"end":37.687,"text":"above one means more people quit."},{"start":39.493,"end":41.585,"text":"The key idea is indirect evidence."},{"start":41.954,"end":44.476,"text":"If we know how group counseling compares"},{"start":44.476,"end":46.814,"text":"with individual counseling, and how"},{"start":46.814,"end":49.213,"text":"individual counseling compares with no"},{"start":49.213,"end":51.674,"text":"contact, we can chain them to compare"},{"start":51.674,"end":53.704,"text":"group counseling with no contact."},{"start":54.55,"end":56.852,"text":"This rests on two assumptions:"},{"start":56.852,"end":59.218,"text":"transitivity, that the studies are"},{"start":59.218,"end":62.096000000000004,"text":"comparable, and consistency, that direct"},{"start":62.096000000000004,"end":63.887,"text":"and indirect evidence agree."},{"start":65.717,"end":68.322,"text":"Combining direct and indirect evidence,"},{"start":68.322,"end":70.989,"text":"every active treatment beats no contact on"},{"start":70.989,"end":71.485,"text":"average."},{"start":71.857,"end":74.09,"text":"Group counseling roughly doubles to"},{"start":74.09,"end":76.324,"text":"triples the odds of quitting, and"},{"start":76.324,"end":78.494,"text":"individual counseling doubles them."},{"start":79.324,"end":81.701,"text":"For self help, though, the interval"},{"start":81.701,"end":84.257,"text":"crosses one, so its benefit is uncertain."},{"start":85.1,"end":87.481,"text":"Heterogeneity is large, with I squared"},{"start":87.481,"end":89.979,"text":"near 89 percent, which is one reason the"},{"start":89.979,"end":91.082,"text":"intervals are wide."},{"start":97.12700000000001,"end":99.307,"text":"Take group versus individual counseling."},{"start":99.63499999999999,"end":101.924,"text":"Studies that compared them directly found"},{"start":101.924,"end":104.16,"text":"almost no difference, but the indirect"},{"start":104.16,"end":106.45,"text":"route suggests group counseling is better."},{"start":107.214,"end":110.15,"text":"That gap is not statistically clear on its"},{"start":110.15,"end":112.745,"text":"own, with p of zero point two eight."},{"start":113.155,"end":115.818,"text":"But across the whole network, a test"},{"start":115.818,"end":118.071,"text":"between study designs flags some"},{"start":118.071,"end":121.008,"text":"inconsistency, with p of zero point zero"},{"start":121.008,"end":124.081,"text":"three three, a warning to read the results"},{"start":124.081,"end":124.764,"text":"with care."},{"start":126.637,"end":128.808,"text":"Network meta analyses often rank the"},{"start":128.808,"end":129.454,"text":"treatments."},{"start":129.806,"end":132.388,"text":"Here group counseling ranks first, with a"},{"start":132.388,"end":134.325,"text":"P score of zero point eight four."},{"start":135.115,"end":137.103,"text":"But rankings hide uncertainty."},{"start":137.5,"end":139.952,"text":"Group and individual counseling have"},{"start":139.952,"end":142.736,"text":"heavily overlapping intervals, so first"},{"start":142.736,"end":144.857,"text":"and second place are not really"},{"start":144.857,"end":145.917,"text":"distinguishable."},{"start":147.827,"end":150.628,"text":"Report the shape of the network, how you"},{"start":150.628,"end":152.712,"text":"judged transitivity and checked"},{"start":152.712,"end":155.188,"text":"consistency, and effects with their"},{"start":155.188,"end":157.207,"text":"uncertainty before any ranking."},{"start":157.598,"end":160.334,"text":"That completes our step by step series on"},{"start":160.334,"end":161.246,"text":"meta analysis."}]},"xrfvYZc6XIY":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.241,"text":"Part four repeats the random effects"},{"start":2.241,"end":4.894,"text":"analysis the Bayesian way, which answers a"},{"start":4.894,"end":6.426,"text":"question a p value cannot."},{"start":8.303,"end":11.295,"text":"In part two, the average effect was zero"},{"start":11.295,"end":14.148,"text":"point zero eight, with p of zero point"},{"start":14.148,"end":14.427,"text":"one."},{"start":14.844,"end":17.767,"text":"That tells us the data are not unusual if"},{"start":17.767,"end":19.576,"text":"the true effect were zero."},{"start":20.55,"end":22.922,"text":"It does not tell us how likely it is that"},{"start":22.922,"end":24.22,"text":"the effect is positive."},{"start":24.559,"end":25.801,"text":"Bayesian analysis can."},{"start":27.65,"end":29.612,"text":"Bayes' rule says the posterior is"},{"start":29.612,"end":31.69,"text":"proportional to the prior times the"},{"start":31.69,"end":34.229,"text":"likelihood: what we believed before,"},{"start":34.229,"end":36.134,"text":"updated by what the studies show."},{"start":36.947,"end":39.681,"text":"A prior is belief before the data, and a"},{"start":39.681,"end":41.525,"text":"posterior is belief after it."},{"start":43.427,"end":45.397,"text":"We need priors for two things."},{"start":45.791,"end":48.681,"text":"For tau, the spread of true effects, we"},{"start":48.681,"end":51.505,"text":"use a gentle half normal prior that allows"},{"start":51.505,"end":53.673,"text":"values from zero up to about one."},{"start":54.555,"end":56.967,"text":"After seeing the nineteen studies, the"},{"start":56.967,"end":59.497,"text":"posterior for tau concentrates around zero"},{"start":59.497,"end":62.145,"text":"point one four, very close to the estimate"},{"start":62.145,"end":62.852,"text":"in part two."},{"start":64.68299999999999,"end":67.673,"text":"For mu, the average effect, we use a very"},{"start":67.673,"end":70.403,"text":"wide prior, so the studies speak almost"},{"start":70.403,"end":71.963,"text":"entirely for themselves."},{"start":76.97,"end":80.078,"text":"The shaded area is the answer: about 94"},{"start":80.078,"end":82.90899999999999,"text":"percent of the posterior lies above zero."},{"start":83.32300000000001,"end":86.01599999999999,"text":"The effect is probably positive, but"},{"start":86.01599999999999,"end":88.986,"text":"small, and the data cannot rule out zero."},{"start":89.877,"end":92.432,"text":"The ninety five percent credible interval,"},{"start":92.432,"end":94.759,"text":"from minus zero point zero three to zero"},{"start":94.759,"end":97.2,"text":"point two one, can be read directly as a"},{"start":97.2,"end":99.69800000000001,"text":"probability statement, which a confidence"},{"start":99.69800000000001,"end":100.606,"text":"interval cannot."},{"start":102.42699999999999,"end":105.237,"text":"For a new, similar study, the Bayesian"},{"start":105.237,"end":107.982,"text":"predictive interval runs from about minus"},{"start":107.982,"end":110.596,"text":"zero point two eight to zero point four"},{"start":110.596,"end":113.47200000000001,"text":"seven, a little wider than in part two,"},{"start":113.47200000000001,"end":116.152,"text":"because uncertainty about tau is carried"},{"start":116.152,"end":116.675,"text":"through."},{"start":117.564,"end":120.137,"text":"With only nineteen studies, the prior for"},{"start":120.137,"end":122.419,"text":"tau can shift the results, so a good"},{"start":122.419,"end":124.759,"text":"Bayesian meta analysis reruns the model"},{"start":124.759,"end":127.157,"text":"with other reasonable priors and reports"},{"start":127.157,"end":128.503,"text":"how much things change."},{"start":130.327,"end":132.996,"text":"Report your priors and why, the posterior"},{"start":132.996,"end":135.362,"text":"summaries and probabilities, and how"},{"start":135.362,"end":137.364,"text":"sensitive they are to the priors."},{"start":137.728,"end":139.912,"text":"In the last part, we compare many"},{"start":139.912,"end":142.157,"text":"treatments at once with network meta"},{"start":142.157,"end":142.703,"text":"analysis."}]},"r_tqNkORPeo":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.544,"text":"This is the final part of our series on"},{"start":2.544,"end":5.09,"text":"sequential analytics: hidden Markov"},{"start":5.09,"end":5.524,"text":"models."},{"start":5.897,"end":8.443,"text":"The idea is that the codes we see may be"},{"start":8.443,"end":10.367,"text":"driven by states we cannot see."},{"start":12.193,"end":15.106,"text":"In session P001, we observe one code per"},{"start":15.106,"end":15.445,"text":"turn."},{"start":15.851,"end":18.764,"text":"A hidden Markov model assumes that beneath"},{"start":18.764,"end":21.609,"text":"each code sits a hidden state, which we"},{"start":21.609,"end":23.167,"text":"never observe directly."},{"start":24.041,"end":26.667,"text":"For a beginner, think of a hidden state as"},{"start":26.667,"end":29.06,"text":"a mode the conversation is in, such as"},{"start":29.06,"end":31.394,"text":"questioning or explaining, that shows"},{"start":31.394,"end":33.844,"text":"itself only through the codes it tends to"},{"start":33.844,"end":34.311,"text":"produce."},{"start":36.093,"end":38.046,"text":"The model describes those unseen"},{"start":38.046,"end":39.82,"text":"influences with three sets of"},{"start":39.82,"end":40.648,"text":"probabilities."},{"start":41.461,"end":43.767,"text":"Initial probabilities say how sessions"},{"start":43.767,"end":44.122,"text":"start."},{"start":44.477,"end":46.664,"text":"Transition probabilities say how one"},{"start":46.664,"end":48.497,"text":"hidden state leads to the next."},{"start":48.852,"end":51.157,"text":"Emission probabilities say which codes"},{"start":51.157,"end":53.227,"text":"each hidden state tends to produce."},{"start":54.029,"end":56.366,"text":"The word emission simply means the code a"},{"start":56.366,"end":57.256,"text":"state gives off."},{"start":59.06,"end":61.391,"text":"The probabilities are estimated with the E"},{"start":61.391,"end":63.559,"text":"M algorithm, which alternates between"},{"start":63.559,"end":65.727,"text":"guessing the hidden states and updating"},{"start":65.727,"end":67.895,"text":"the probabilities until nothing changes."},{"start":68.67699999999999,"end":71.289,"text":"E M can stop at a local peak, so we start"},{"start":71.289,"end":73.01,"text":"it from twenty random places."},{"start":73.366,"end":76.037,"text":"For the 6 state model, every start reached"},{"start":76.037,"end":78.293,"text":"the same log likelihood, a sign the"},{"start":78.293,"end":79.42099999999999,"text":"solution is stable."},{"start":81.275,"end":83.754,"text":"How many hidden states should there be?"},{"start":84.135,"end":86.742,"text":"We fit models with two to ten states and"},{"start":86.742,"end":89.475,"text":"compare them with the Bayesian information"},{"start":89.475,"end":90.873,"text":"criterion, or B I C."},{"start":98.893,"end":100.614,"text":"B I C is lowest at 6 states."},{"start":100.983,"end":103.565,"text":"More states keep improving the raw fit,"},{"start":103.565,"end":106.148,"text":"but the penalty for extra parameters wins"},{"start":106.148,"end":106.824,"text":"after that."},{"start":108.693,"end":111.15100000000001,"text":"Here are the emissions of the 6 states."},{"start":111.529,"end":114.113,"text":"Each row is a state, and its strongest"},{"start":114.113,"end":116.445,"text":"cells tell us what that state mostly"},{"start":116.445,"end":119.09100000000001,"text":"produces: one state is almost always"},{"start":119.09100000000001,"end":121.675,"text":"explain, another almost always example."},{"start":122.55,"end":125.7,"text":"The transitions reveal something striking."},{"start":126.15,"end":129.075,"text":"The states fall into two closed groups"},{"start":129.075,"end":132.075,"text":"that never pass into each other: a"},{"start":132.075,"end":135.45,"text":"question and answer loop, and a chain from"},{"start":135.45,"end":137.85,"text":"explain to example to elaborate."},{"start":139.793,"end":142.836,"text":"For any session, the model can recover the"},{"start":142.836,"end":145.81,"text":"single most likely path of hidden states,"},{"start":145.81,"end":147.433,"text":"called the Viterbi path."},{"start":147.838,"end":150.678,"text":"Here it is for P001, one turn at a time."},{"start":156.06,"end":158.883,"text":"This session never leaves the chain group:"},{"start":158.883,"end":161.412,"text":"explain leads to example, and example to"},{"start":161.412,"end":163.117,"text":"elaborate, turn after turn."},{"start":164.927,"end":167.361,"text":"The model was never told which group each"},{"start":167.361,"end":168.404,"text":"session came from."},{"start":168.751,"end":171.011,"text":"Yet every control session stays in the"},{"start":171.011,"end":173.561,"text":"question and answer loop, while 38 of the"},{"start":173.561,"end":175.879,"text":"50 treatment sessions stay in the chain."},{"start":176.684,"end":179.034,"text":"So the hidden states sort the sessions in"},{"start":179.034,"end":181.385,"text":"a way that matches the real groups eighty"},{"start":181.385,"end":183.008,"text":"eight times out of a hundred."},{"start":184.81,"end":185.99,"text":"A word of caution."},{"start":186.383,"end":188.677,"text":"These data were simulated from two"},{"start":188.677,"end":191.233,"text":"ordinary Markov chains, one for each"},{"start":191.233,"end":193.658,"text":"group, with no hidden minds inside."},{"start":194.052,"end":196.214,"text":"The six states recover those two"},{"start":196.214,"end":199.29500000000002,"text":"processes, which is useful, but a state is"},{"start":199.29500000000002,"end":202.113,"text":"a modeling choice, not a discovery about"},{"start":202.113,"end":203.227,"text":"how people think."},{"start":205.127,"end":207.4,"text":"When you report a hidden Markov model,"},{"start":207.4,"end":209.895,"text":"state how the number of states was chosen,"},{"start":209.895,"end":212.28,"text":"whether the restarts agreed, and how the"},{"start":212.28,"end":214.054,"text":"states were labeled and checked."},{"start":215.827,"end":218.405,"text":"That completes the series: five lenses on"},{"start":218.405,"end":220.654,"text":"one stream of events, each answering a"},{"start":220.654,"end":222.79399999999998,"text":"different question about the same data."},{"start":223.123,"end":225.591,"text":"Pick the lens by your question, not by the"},{"start":225.591,"end":227.018,"text":"method that is in fashion."}]},"s0HYoN8dfIM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.755,"text":"This series explains meta analysis step by"},{"start":2.755,"end":5.073,"text":"step, starting from the statistics."},{"start":5.449,"end":8.144,"text":"Part one covers effect sizes, the common"},{"start":8.144,"end":10.65,"text":"currency that lets different studies be"},{"start":10.65,"end":11.214,"text":"combined."},{"start":13.103,"end":15.928,"text":"Our running example is a classic: nineteen"},{"start":15.928,"end":18.399,"text":"studies of whether teachers' expectations"},{"start":18.399,"end":20.812,"text":"raise pupils' I Q scores, collected by"},{"start":20.812,"end":21.93,"text":"Stephen Raudenbush."},{"start":22.71,"end":24.99,"text":"A meta analysis is a study of studies."},{"start":25.35,"end":27.99,"text":"Before we can combine them, we need every"},{"start":27.99,"end":30.33,"text":"study to report its result on the same"},{"start":30.33,"end":30.69,"text":"scale."},{"start":32.527,"end":35.095,"text":"The studies used different tests, so raw"},{"start":35.095,"end":37.304,"text":"score differences cannot be compared"},{"start":37.304,"end":37.842,"text":"directly."},{"start":38.2,"end":40.888,"text":"Instead, we divide the difference in means"},{"start":40.888,"end":42.858,"text":"by the pooled standard deviation."},{"start":43.734,"end":46.993,"text":"The result, d, says how far apart the two"},{"start":46.993,"end":49.968,"text":"groups are, in standard deviation units."},{"start":50.86,"end":52.907,"text":"The standard deviation works here as a"},{"start":52.907,"end":54.796,"text":"common ruler that every test shares."},{"start":56.593,"end":58.972,"text":"Rosenthal and Jacobson's famous study"},{"start":58.972,"end":60.913,"text":"reported d of zero point three."},{"start":61.288,"end":63.166,"text":"Picture the two groups' score"},{"start":63.166,"end":65.42,"text":"distributions and slide one by that"},{"start":65.42,"end":65.858,"text":"amount."},{"start":73.38,"end":75.348,"text":"The curves still overlap heavily."},{"start":75.705,"end":78.03,"text":"Yet about 62 percent of the expectancy"},{"start":78.03,"end":80.355,"text":"group scores above the average control"},{"start":80.355,"end":82.383,"text":"pupil, instead of fifty percent."},{"start":83.237,"end":85.243,"text":"Cohen's rough labels would call this"},{"start":85.243,"end":85.568,"text":"small."},{"start":85.894,"end":88.44200000000001,"text":"In education, though, context matters more"},{"start":88.44200000000001,"end":90.882,"text":"than labels, because a cheap change with a"},{"start":90.882,"end":92.94200000000001,"text":"small effect can still be worth a lot."},{"start":94.737,"end":97.22,"text":"In small samples, d slightly overstates"},{"start":97.22,"end":98.402,"text":"the true difference."},{"start":98.757,"end":101.239,"text":"Hedges' correction shrinks it a little,"},{"start":101.239,"end":103.072,"text":"giving an effect size called g."},{"start":103.945,"end":107.44800000000001,"text":"The shrinkage is small: about two percent"},{"start":107.44800000000001,"end":110.35499999999999,"text":"for a study of 33 pupils, and almost"},{"start":110.35499999999999,"end":111.547,"text":"nothing for 457."},{"start":112.423,"end":114.80799999999999,"text":"This is a correction for bias, a tilt in"},{"start":114.80799999999999,"end":117.027,"text":"one direction, rather than for random"},{"start":117.027,"end":117.36,"text":"noise."},{"start":119.137,"end":121.17,"text":"Every effect size also comes with a"},{"start":121.17,"end":123.429,"text":"variance, which depends mostly on the"},{"start":123.429,"end":124.163,"text":"sample sizes."},{"start":124.502,"end":126.648,"text":"Bigger groups give a smaller variance."},{"start":127.454,"end":129.92,"text":"For Rosenthal and Jacobson, with sixty"},{"start":129.92,"end":132.446,"text":"five and two hundred fifty five pupils,"},{"start":132.446,"end":134.972,"text":"the variance is about zero point zero one"},{"start":134.972,"end":135.273,"text":"nine."},{"start":136.1,"end":138.906,"text":"Its square root is the standard error, and"},{"start":138.906,"end":141.088,"text":"the ninety five percent confidence"},{"start":141.088,"end":143.644,"text":"interval runs from about zero point zero"},{"start":143.644,"end":145.576,"text":"three to zero point five seven."},{"start":147.47,"end":149.958,"text":"Now every study becomes an estimate with"},{"start":149.958,"end":150.686,"text":"an interval."},{"start":151.05,"end":153.537,"text":"Big studies have short intervals and big"},{"start":153.537,"end":156.14600000000002,"text":"squares; small studies have long ones."},{"start":156.987,"end":159.992,"text":"Compare Fleming and Anttonen, with 457"},{"start":159.992,"end":163.436,"text":"pupils, to Pellegrini and Hicks, with only"},{"start":163.436,"end":166.80700000000002,"text":"33: the larger study is far more precise."},{"start":173.917,"end":176.551,"text":"So each study enters a meta analysis as"},{"start":176.551,"end":179.251,"text":"two numbers: an effect size and its"},{"start":179.251,"end":179.844,"text":"variance."},{"start":180.239,"end":182.807,"text":"In part two, we use the variances to"},{"start":182.807,"end":185.442,"text":"decide how much each study should count."}]},"spTunL0povM":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.653,"text":"In part one, each study became an effect"},{"start":2.653,"end":3.914,"text":"size with a variance."},{"start":4.275,"end":6.978,"text":"Part two asks how to combine them, and how"},{"start":6.978,"end":8.72,"text":"much each study should count."},{"start":10.583,"end":12.849,"text":"The standard answer is to weight each"},{"start":12.849,"end":15.412,"text":"study by the inverse of its variance, so"},{"start":15.412,"end":17.678,"text":"precise studies count more than noisy"},{"start":17.678,"end":17.976,"text":"ones."},{"start":19.77,"end":22.024,"text":"With these weights, the largest study"},{"start":22.024,"end":24.335,"text":"carries about 15 percent of the total,"},{"start":24.335,"end":26.701,"text":"while the smallest carries well under one"},{"start":26.701,"end":27.152,"text":"percent."},{"start":27.97,"end":30.674,"text":"If we assume every study estimates one and"},{"start":30.674,"end":33.504,"text":"the same true effect, the weighted average"},{"start":33.504,"end":36.208,"text":"is zero point zero six, with an interval"},{"start":36.208,"end":37.403,"text":"that includes zero."},{"start":42.407,"end":43.911,"text":"The Q test answers this."},{"start":44.287,"end":46.858,"text":"If only sampling noise were at work, Q"},{"start":46.858,"end":48.299,"text":"would be near eighteen."},{"start":48.676,"end":51.371,"text":"It is thirty five point eight, with p of"},{"start":51.371,"end":54.192,"text":"zero point zero zero seven: the studies"},{"start":54.192,"end":56.261,"text":"disagree more than chance allows."},{"start":59.07,"end":61.089,"text":"A random effects model drops that"},{"start":61.089,"end":61.742,"text":"assumption."},{"start":62.098,"end":64.354,"text":"Each study has its own true effect,"},{"start":64.354,"end":66.432,"text":"scattered around an average with a"},{"start":66.432,"end":68.985,"text":"standard deviation called tau, estimated"},{"start":68.985,"end":71.004,"text":"here at about zero point one four."},{"start":72.787,"end":75.488,"text":"Adding tau squared to every variance makes"},{"start":75.488,"end":78.439,"text":"the weights more equal: the largest study"},{"start":78.439,"end":80.952,"text":"now carries about 10 percent instead of"},{"start":80.952,"end":81.14,"text":"15."},{"start":83.017,"end":84.681,"text":"Here is the full forest plot."},{"start":85.025,"end":87.149,"text":"The blue diamond is the fixed effect"},{"start":87.149,"end":89.444,"text":"estimate, and the teal diamond is the"},{"start":89.444,"end":91.912,"text":"random effects estimate, zero point zero"},{"start":91.912,"end":94.265,"text":"eight four, with a wider interval that"},{"start":94.265,"end":95.412,"text":"still includes zero."},{"start":96.244,"end":98.11,"text":"The I squared statistic puts this"},{"start":98.11,"end":100.636,"text":"heterogeneity in proportion: about forty"},{"start":100.636,"end":102.997,"text":"two percent of the variation reflects real"},{"start":102.997,"end":104.53399999999999,"text":"differences between studies."},{"start":105.28,"end":107.646,"text":"The yellow line is the prediction"},{"start":107.646,"end":110.708,"text":"interval, from about minus zero point two"},{"start":110.708,"end":113.7,"text":"to plus zero point three seven: a new"},{"start":113.7,"end":116.761,"text":"study's true effect could be negative, or"},{"start":116.761,"end":118.15299999999999,"text":"moderately positive."},{"start":120.05,"end":122.077,"text":"Report the model and how tau was"},{"start":122.077,"end":124.658,"text":"estimated, the pooled estimate with its"},{"start":124.658,"end":127.545,"text":"interval, and the heterogeneity, including"},{"start":127.545,"end":129.02,"text":"the prediction interval."},{"start":129.388,"end":131.968,"text":"In part three, we ask why these studies"},{"start":131.968,"end":132.52100000000002,"text":"disagree."}]},"9gPGEZsnIPg":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.81,"text":"In part two, the studies disagreed more"},{"start":2.81,"end":4.05,"text":"than chance allows."},{"start":4.441,"end":7.116,"text":"Part three asks why they disagree, and"},{"start":7.116,"end":9.269,"text":"whether some results are missing."},{"start":11.16,"end":12.698,"text":"Raudenbush had a hypothesis."},{"start":13.028,"end":15.225,"text":"Telling teachers that some pupils would"},{"start":15.225,"end":17.587,"text":"bloom should matter most when the teachers"},{"start":17.587,"end":19.07,"text":"barely knew the pupils yet."},{"start":19.898,"end":22.521,"text":"Each bubble is a study, placed by how many"},{"start":22.521,"end":24.969,"text":"weeks the teachers had known the class,"},{"start":24.969,"end":26.368,"text":"and sized by its weight."},{"start":32.376,"end":34.545,"text":"The large positive effects all come from"},{"start":34.545,"end":36.503,"text":"studies where teachers had known the"},{"start":36.503,"end":37.878,"text":"pupils for a week or less."},{"start":38.633,"end":40.897,"text":"A study feature that changes the size of"},{"start":40.897,"end":43.217,"text":"an effect, like this one, is called a"},{"start":43.217,"end":45.591,"text":"moderator, and it can be tested formally."},{"start":47.383,"end":49.806,"text":"Splitting the studies tells a clear story."},{"start":50.152,"end":52.344,"text":"With a week or less of contact, the"},{"start":52.344,"end":54.709,"text":"average effect is about zero point three"},{"start":54.709,"end":55.055,"text":"seven."},{"start":55.401,"end":57.939,"text":"With two weeks or more, it is essentially"},{"start":57.939,"end":58.227,"text":"zero."},{"start":59.001,"end":61.176,"text":"A meta regression with this moderator"},{"start":61.176,"end":63.008,"text":"explains essentially all of the"},{"start":63.008,"end":65.583,"text":"heterogeneity: the leftover tau squared"},{"start":65.583,"end":66.728,"text":"drops to about zero."},{"start":67.489,"end":70.252,"text":"One caution: studies were not randomly"},{"start":70.252,"end":72.953,"text":"assigned to their moderator values, so a"},{"start":72.953,"end":75.653,"text":"moderator finding is an association across"},{"start":75.653,"end":77.662,"text":"studies, not proof of a cause."},{"start":79.56,"end":81.92699999999999,"text":"To check for missing results, we draw a"},{"start":81.92699999999999,"end":84.631,"text":"funnel plot: big, precise studies at the"},{"start":84.631,"end":86.773,"text":"top, small ones spreading out below."},{"start":87.111,"end":89.30799999999999,"text":"Without bias, the points should look"},{"start":89.30799999999999,"end":89.872,"text":"symmetric."},{"start":90.678,"end":93.493,"text":"Here the small studies lean to the right,"},{"start":93.493,"end":95.988,"text":"and Egger's regression test flags that"},{"start":95.988,"end":98.738,"text":"asymmetry, with p of zero point zero one"},{"start":98.738,"end":98.994,"text":"two."},{"start":99.805,"end":101.957,"text":"Trim and fill imagines the 3 missing"},{"start":101.957,"end":104.458,"text":"studies that would restore symmetry, and"},{"start":104.458,"end":106.726,"text":"the adjusted estimate shrinks to about"},{"start":106.726,"end":108.006,"text":"zero point zero three."},{"start":108.793,"end":110.45400000000001,"text":"Notice the colors, though."},{"start":110.81,"end":113.47999999999999,"text":"The small, positive studies are mostly the"},{"start":113.47999999999999,"end":116.031,"text":"early contact ones, so the asymmetry may"},{"start":116.031,"end":118.523,"text":"reflect the moderator rather than missing"},{"start":118.523,"end":118.99799999999999,"text":"studies."},{"start":119.354,"end":121.787,"text":"Funnel asymmetry has more than one cause."},{"start":123.66,"end":125.947,"text":"Report which moderators you planned to"},{"start":125.947,"end":128.704,"text":"test, how much heterogeneity they explain,"},{"start":128.704,"end":131.049,"text":"and how you checked for missing studies."},{"start":131.401,"end":133.806,"text":"In part four, we redo the analysis the"},{"start":133.806,"end":134.568,"text":"Bayesian way."}]},"k9izMqIyRXw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.315,"text":"Here is a question calculus was built to"},{"start":2.315,"end":2.7,"text":"answer."},{"start":3.158,"end":5.384,"text":"Take a pair of axes, and draw the curve x"},{"start":5.384,"end":6.244,"text":"squared over two."},{"start":6.665,"end":9.01,"text":"How much space lies under it, from zero to"},{"start":9.01,"end":9.322,"text":"three?"},{"start":9.753,"end":12.151,"text":"Curves are hard, but rectangles are easy."},{"start":12.486,"end":14.828,"text":"Fill the region with three of them, and"},{"start":14.828,"end":15.888,"text":"add up their areas."},{"start":16.37,"end":18.315,"text":"Make them thinner, and the gaps shrink."},{"start":19.043,"end":21.482,"text":"Thinner still, and the sum creeps closer."},{"start":21.901,"end":24.367,"text":"In the limit, the rectangles become the"},{"start":24.367,"end":26.658,"text":"curve itself, and the sum becomes an"},{"start":26.658,"end":28.948,"text":"integral: exactly four and a half."},{"start":29.398,"end":31.88,"text":"The area under a curve is just infinitely"},{"start":31.88,"end":33.593,"text":"many thin slices, added up."}]},"dqrWUnItTi4":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.411,"text":"This is part three of our series on"},{"start":2.411,"end":5.415,"text":"sequential analytics: transition network"},{"start":5.415,"end":8.354,"text":"analysis, or T N A, with a focus on what"},{"start":8.354,"end":10.966,"text":"each number means and how reliable each"},{"start":10.966,"end":11.488,"text":"edge is."},{"start":13.297,"end":15.58,"text":"Transition network analysis starts from"},{"start":15.58,"end":18.035,"text":"the same lag one transitions we counted in"},{"start":18.035,"end":20.319,"text":"part one, four thousand thirty six of"},{"start":20.319,"end":20.604,"text":"them."},{"start":21.404,"end":23.889,"text":"Instead of comparing counts with chance,"},{"start":23.889,"end":26.489,"text":"it divides each row by its total, so every"},{"start":26.489,"end":28.8,"text":"row becomes a set of probabilities that"},{"start":28.8,"end":29.667,"text":"adds up to one."},{"start":30.431,"end":32.919,"text":"So ask is followed by explain with a"},{"start":32.919,"end":35.879,"text":"probability of zero point five three, the"},{"start":35.879,"end":37.897,"text":"same value we saw in part one."},{"start":38.768,"end":41.407,"text":"This is a first order Markov model: the"},{"start":41.407,"end":43.928,"text":"next code is assumed to depend only on the"},{"start":43.928,"end":46.216,"text":"current one, not on anything earlier."},{"start":48.005,"end":50.614,"text":"Drawn as a network, each code is a node,"},{"start":50.614,"end":53.106,"text":"and each transition is an arrow, thicker"},{"start":53.106,"end":54.439,"text":"when it is more likely."},{"start":54.787,"end":57.048,"text":"The rings show a code following itself."},{"start":57.872,"end":60.783,"text":"The strongest path is ask to explain, at"},{"start":60.783,"end":63.829,"text":"zero point five three, followed by example"},{"start":63.829,"end":67.01,"text":"to elaborate, at zero point three six, and"},{"start":67.01,"end":69.92,"text":"explain back to ask, at zero point three"},{"start":69.92,"end":70.326,"text":"three."},{"start":71.229,"end":73.734,"text":"The model also records how sessions begin:"},{"start":73.734,"end":75.926,"text":"fifty four percent of them start with ask."},{"start":76.666,"end":79.072,"text":"Centrality measures summarize the role of"},{"start":79.072,"end":81.592,"text":"each node, and explain has the highest in"},{"start":81.592,"end":84.112,"text":"strength, one point two one, because it"},{"start":84.112,"end":86.345,"text":"receives the most probability from the"},{"start":86.345,"end":87.032,"text":"other codes."},{"start":88.804,"end":90.262,"text":"Is each edge reliable?"},{"start":90.66,"end":93.444,"text":"T N A resamples the sessions one thousand"},{"start":93.444,"end":96.295,"text":"times, refits the model each time, and"},{"start":96.295,"end":98.416,"text":"checks how much each edge moves."},{"start":99.301,"end":101.86099999999999,"text":"An edge is called stable when its weight"},{"start":101.86099999999999,"end":104.42099999999999,"text":"stays within seventy five to one hundred"},{"start":104.42099999999999,"end":106.669,"text":"twenty five percent of the original."},{"start":107.043,"end":109.479,"text":"Twenty three of twenty five edges pass."},{"start":109.85300000000001,"end":112.663,"text":"The two that do not are weak edges, ask to"},{"start":112.663,"end":114.536,"text":"example and example to itself."},{"start":115.378,"end":117.713,"text":"The bootstrap also gives intervals."},{"start":118.114,"end":120.65,"text":"For ask to explain, the ninety five"},{"start":120.65,"end":123.519,"text":"percent interval runs from zero point four"},{"start":123.519,"end":125.387,"text":"nine to zero point five six."},{"start":127.266,"end":130.359,"text":"To compare groups, T N A fits one network"},{"start":130.359,"end":133.24099999999999,"text":"per group, using the same nodes in the"},{"start":133.24099999999999,"end":134.084,"text":"same places."},{"start":134.953,"end":137.663,"text":"The largest difference is explain followed"},{"start":137.663,"end":140.69,"text":"by ask: zero point five zero in control,"},{"start":140.69,"end":143.274,"text":"but only zero point one one in treatment."},{"start":145.09,"end":147.672,"text":"A permutation test shuffles whole sessions"},{"start":147.672,"end":150.13400000000001,"text":"between the groups one thousand times,"},{"start":150.13400000000001,"end":152.837,"text":"refits both networks, and asks how often a"},{"start":152.837,"end":155.239,"text":"difference this large appears by chance."},{"start":156.036,"end":158.559,"text":"Seventeen of twenty five edges differ at p"},{"start":158.559,"end":160.788,"text":"below zero point zero five, and all"},{"start":160.788,"end":162.841,"text":"seventeen remain after a Benjamini"},{"start":162.841,"end":164.014,"text":"Hochberg correction."},{"start":164.863,"end":167.648,"text":"With one thousand shuffles, the smallest p"},{"start":167.648,"end":170.123,"text":"value the test can report is about zero"},{"start":170.123,"end":172.845,"text":"point zero zero one, so use more shuffles"},{"start":172.845,"end":174.392,"text":"if you need finer values."},{"start":176.261,"end":178.434,"text":"When you report a transition network"},{"start":178.434,"end":180.725,"text":"analysis, state how transitions were"},{"start":180.725,"end":183.309,"text":"counted, the probabilities and how stable"},{"start":183.309,"end":185.482,"text":"each edge was, and how groups were"},{"start":185.482,"end":187.773,"text":"compared, under a first order Markov"},{"start":187.773,"end":188.419,"text":"assumption."},{"start":189.238,"end":191.36599999999999,"text":"Next in the series is ordered network"},{"start":191.36599999999999,"end":193.718,"text":"analysis, which looks back over a wider"},{"start":193.718,"end":194.11,"text":"window."},{"start":194.446,"end":196.798,"text":"The companion guide has the code for this"},{"start":196.798,"end":197.582,"text":"analysis in R."}]},"0P0xOb9frbA":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.771,"text":"This is part one of a series on sequential"},{"start":2.771,"end":3.4,"text":"analytics."},{"start":3.777,"end":6.604,"text":"We begin with lag sequential analysis, the"},{"start":6.604,"end":9.242,"text":"approach popularized by Roger Bakeman and"},{"start":9.242,"end":12.006,"text":"his colleagues, with a focus on what each"},{"start":12.006,"end":12.823,"text":"number means."},{"start":14.667,"end":17.127,"text":"Lag sequential analysis asks a simple"},{"start":17.127,"end":20.365,"text":"question: given one code, how often does a"},{"start":20.365,"end":22.048,"text":"particular code come next?"},{"start":23.915,"end":25.818,"text":"The data points are transitions."},{"start":26.175,"end":28.673,"text":"Each pair of neighboring turns is one lag"},{"start":28.673,"end":31.052,"text":"one transition, counted only within a"},{"start":31.052,"end":31.528,"text":"session."},{"start":32.312,"end":34.925,"text":"So four thousand one hundred thirty six"},{"start":34.925,"end":37.538,"text":"turns in one hundred sessions give four"},{"start":37.538,"end":40.347,"text":"thousand thirty six transitions, because"},{"start":40.347,"end":42.895,"text":"no transition crosses from one session"},{"start":42.895,"end":43.81,"text":"into the next."},{"start":45.64,"end":48.124,"text":"Tallying them gives a five by five table:"},{"start":48.124,"end":50.186,"text":"the rows are the given code, and the"},{"start":50.186,"end":52.142,"text":"columns are the code that comes next."},{"start":52.938,"end":55.385,"text":"Ask was followed by explain four hundred"},{"start":55.385,"end":57.952,"text":"seventy eight times, out of nine hundred"},{"start":57.952,"end":60.22,"text":"six transitions that started with ask."},{"start":60.578,"end":63.145,"text":"That is a transitional probability of zero"},{"start":63.145,"end":64.159,"text":"point five three."},{"start":65.026,"end":67.205,"text":"But explain is common in general: it"},{"start":67.205,"end":69.281,"text":"follows about twenty six percent of all"},{"start":69.281,"end":69.592,"text":"turns."},{"start":69.904,"end":72.084,"text":"A high probability alone does not tell us"},{"start":72.084,"end":73.744,"text":"whether the sequence is special."},{"start":75.464,"end":78.021,"text":"So we ask what independence would predict."},{"start":78.386,"end":80.944,"text":"The expected count is the row total times"},{"start":80.944,"end":83.075,"text":"the column total, divided by all"},{"start":83.075,"end":85.693,"text":"transitions: about two hundred thirty"},{"start":85.693,"end":86.05799999999999,"text":"eight."},{"start":86.92,"end":89.592,"text":"Bakeman and Quera recommend the adjusted"},{"start":89.592,"end":92.26400000000001,"text":"residual, which scales the gap between"},{"start":92.26400000000001,"end":94.74000000000001,"text":"observed and expected by its standard"},{"start":94.74000000000001,"end":95.131,"text":"error."},{"start":95.52199999999999,"end":98.259,"text":"For ask then explain, z is twenty point"},{"start":98.259,"end":98.519,"text":"six."},{"start":99.337,"end":101.733,"text":"Doing this for every cell gives a map of"},{"start":101.733,"end":104.069,"text":"which transitions occur more often than"},{"start":104.069,"end":106.757,"text":"chance, in red, and less often, in blue."},{"start":108.58500000000001,"end":111.413,"text":"With twenty five cells, some will pass one"},{"start":111.413,"end":113.36099999999999,"text":"point nine six by chance alone."},{"start":113.738,"end":114.869,"text":"Eighteen cells do."},{"start":115.24600000000001,"end":117.949,"text":"With a Bonferroni criterion of three point"},{"start":117.949,"end":119.708,"text":"zero nine, sixteen remain."},{"start":121.582,"end":123.749,"text":"There is one important catch in this"},{"start":123.749,"end":124.1,"text":"table."},{"start":124.451,"end":126.793,"text":"It pools four thousand transitions from"},{"start":126.793,"end":128.901,"text":"one hundred sessions, as if every"},{"start":128.901,"end":131.536,"text":"transition were independent, and with that"},{"start":131.536,"end":133.468,"text":"many, almost any pattern looks"},{"start":133.468,"end":134.171,"text":"significant."},{"start":134.959,"end":137.531,"text":"Bakeman and colleagues therefore suggest"},{"start":137.531,"end":140.29,"text":"computing an index for each session, such"},{"start":140.29,"end":143.05,"text":"as Yule's Q, which runs from minus one to"},{"start":143.05,"end":145.12,"text":"plus one, with zero meaning no"},{"start":145.12,"end":145.873,"text":"association."},{"start":147.716,"end":150.034,"text":"Now each session contributes one number."},{"start":150.382,"end":152.75900000000001,"text":"Ask followed by explain is clearly above"},{"start":152.75900000000001,"end":153.918,"text":"zero in both groups."},{"start":154.774,"end":157.40699999999998,"text":"Comparing the groups tells a quieter"},{"start":157.40699999999998,"end":157.834,"text":"story."},{"start":158.261,"end":161.393,"text":"The control mean is zero point six three,"},{"start":161.393,"end":164.383,"text":"and the treatment mean is zero point five"},{"start":164.383,"end":167.514,"text":"three, a Welch t of one point nine two,"},{"start":167.514,"end":170.077,"text":"with p of zero point zero five nine."},{"start":170.942,"end":173.251,"text":"The pooled z scores, fifteen point nine"},{"start":173.251,"end":175.505,"text":"and eleven point four, would have made"},{"start":175.505,"end":177.869,"text":"this difference look far more certain than"},{"start":177.869,"end":178.199,"text":"it is."},{"start":178.528,"end":180.947,"text":"The session, not the transition, is the"},{"start":180.947,"end":181.992,"text":"unit for inference."},{"start":183.78,"end":186.431,"text":"When you report a lag sequential analysis,"},{"start":186.431,"end":188.72899999999998,"text":"state the lag and how transitions were"},{"start":188.72899999999998,"end":191.381,"text":"counted, the residuals and how you handled"},{"start":191.381,"end":193.855,"text":"many cells, and the session level index"},{"start":193.855,"end":195.446,"text":"you used to compare groups."},{"start":196.267,"end":198.721,"text":"Next in the series is sequential pattern"},{"start":198.721,"end":201.236,"text":"mining, which looks beyond a single lag."},{"start":201.595,"end":204.109,"text":"The companion guide has the code for this"},{"start":204.109,"end":204.947,"text":"analysis in R."}]},"V5HiWnlkp5E":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.07,"end":2.182,"text":"This video explains ordered network"},{"start":2.182,"end":4.822,"text":"analysis, or O N A, with a focus on what"},{"start":4.822,"end":7.169,"text":"each number means and which data points"},{"start":7.169,"end":8.108,"text":"stand behind it."},{"start":9.957,"end":12.674,"text":"O N A starts from an event log, with one"},{"start":12.674,"end":15.517,"text":"coded turn per row, ordered in time within"},{"start":15.517,"end":16.338,"text":"each session."},{"start":17.154,"end":19.607,"text":"Here we have four thousand one hundred"},{"start":19.607,"end":21.871,"text":"thirty six turns, but one hundred"},{"start":21.871,"end":22.437,"text":"sessions."},{"start":22.814,"end":25.582,"text":"Each session is one unit of analysis, and"},{"start":25.582,"end":27.972,"text":"it will become one point in the final"},{"start":27.972,"end":28.286,"text":"plot."},{"start":30.161,"end":33.054,"text":"The most important setting is the window:"},{"start":33.054,"end":35.639,"text":"each turn is treated as a response, and"},{"start":35.639,"end":38.101,"text":"the four turns before it are its ground."},{"start":38.889,"end":41.34,"text":"For every ground code, the model adds one"},{"start":41.34,"end":43.736,"text":"count to a directed connection, from the"},{"start":43.736,"end":45.574,"text":"ground code to the response code."},{"start":47.325,"end":49.394,"text":"Sliding the window across the whole"},{"start":49.394,"end":52.151,"text":"session fills a five by five table: twenty"},{"start":52.151,"end":54.507,"text":"five directed connections, including a"},{"start":54.507,"end":55.771,"text":"code following itself."},{"start":56.622,"end":59.099,"text":"Order is what makes the network ordered."},{"start":59.471,"end":62.071,"text":"Agree followed by elaborate and elaborate"},{"start":62.071,"end":64.858,"text":"followed by agree are separate cells, with"},{"start":64.858,"end":66.901,"text":"12 and 18 counts in this session."},{"start":68.75,"end":70.945,"text":"Longer sessions produce larger counts."},{"start":71.292,"end":73.66,"text":"So each session's twenty five counts are"},{"start":73.66,"end":75.855,"text":"divided by the length of that list of"},{"start":75.855,"end":78.282,"text":"counts, the square root of their summed"},{"start":78.282,"end":78.744,"text":"squares."},{"start":79.56700000000001,"end":81.828,"text":"The counts become weights, and every"},{"start":81.828,"end":84.379,"text":"session now has the same total length, so"},{"start":84.379,"end":86.582,"text":"sessions are compared by the shape of"},{"start":86.582,"end":89.017,"text":"their connections, not by how long they"},{"start":89.017,"end":89.249,"text":"ran."},{"start":91.044,"end":93.189,"text":"A singular value decomposition then"},{"start":93.189,"end":95.691,"text":"reduces the twenty five dimensions to two"},{"start":95.691,"end":95.989,"text":"axes."},{"start":96.34700000000001,"end":97.777,"text":"Each dot is one session."},{"start":98.582,"end":101.194,"text":"The first axis captures 52 percent of the"},{"start":101.194,"end":103.557,"text":"variance, and the second 11 percent."},{"start":103.93,"end":106.729,"text":"The codes are placed in the same space, so"},{"start":106.729,"end":109.27799999999999,"text":"a session's dot sits toward the codes it"},{"start":109.27799999999999,"end":110.149,"text":"connects most."},{"start":110.989,"end":113.239,"text":"The squares are the treatment mean and the"},{"start":113.239,"end":115.384,"text":"control mean, with ninety five percent"},{"start":115.384,"end":116.483,"text":"confidence intervals."},{"start":116.797,"end":118.89,"text":"The two groups sit on opposite sides of"},{"start":118.89,"end":119.675,"text":"the first axis."},{"start":120.437,"end":122.891,"text":"Averaging the weights within each group"},{"start":122.891,"end":124.18,"text":"gives a mean network."},{"start":124.548,"end":126.695,"text":"The subtracted network shows their"},{"start":126.695,"end":129.457,"text":"difference: teal arrows are stronger in"},{"start":129.457,"end":132.218,"text":"treatment, and gold arrows are stronger in"},{"start":132.218,"end":132.709,"text":"control."},{"start":133.554,"end":136.386,"text":"In treatment, example leads to elaborate"},{"start":136.386,"end":137.439,"text":"much more often."},{"start":137.834,"end":140.14,"text":"In control, explain leads to ask."},{"start":140.535,"end":143.301,"text":"These are differences in structure, not"},{"start":143.301,"end":144.289,"text":"just in volume."},{"start":146.162,"end":148.238,"text":"To test the separation, take each"},{"start":148.238,"end":150.372,"text":"session's position on the first axis."},{"start":150.718,"end":152.96699999999998,"text":"The treatment mean is minus zero point"},{"start":152.96699999999998,"end":155.447,"text":"three five, and the control mean is plus"},{"start":155.447,"end":156.716,"text":"zero point three five."},{"start":157.54,"end":160.347,"text":"A Welch t test on that axis gives t of"},{"start":160.347,"end":163.515,"text":"twenty point one, p well below zero point"},{"start":163.515,"end":166.46699999999998,"text":"zero zero one, and a Cohen's d of four"},{"start":166.46699999999998,"end":168.914,"text":"point zero, a very large effect."},{"start":169.346,"end":172.442,"text":"On the second axis, d is only zero point"},{"start":172.442,"end":175.538,"text":"two seven, with p of zero point one nine."},{"start":176.426,"end":178.139,"text":"A permutation test makes fewer"},{"start":178.139,"end":178.802,"text":"assumptions."},{"start":179.133,"end":181.509,"text":"Shuffle the condition labels five thousand"},{"start":181.509,"end":183.94,"text":"times, recompute the distance between the"},{"start":183.94,"end":186.094,"text":"two means each time, and compare the"},{"start":186.094,"end":187.807,"text":"observed distance to that null"},{"start":187.807,"end":188.525,"text":"distribution."},{"start":189.303,"end":191.855,"text":"The observed distance of zero point seven"},{"start":191.855,"end":194.224,"text":"is far beyond anything chance produced."},{"start":194.589,"end":197.07999999999998,"text":"Keep in mind that these synthetic groups"},{"start":197.07999999999998,"end":199.632,"text":"were built to differ, so real data will"},{"start":199.632,"end":201.029,"text":"rarely look this clean."},{"start":202.881,"end":205.242,"text":"When you report ordered network analysis,"},{"start":205.242,"end":207.442,"text":"state the unit and the window, how the"},{"start":207.442,"end":209.803,"text":"counts were normalized and projected, and"},{"start":209.803,"end":212.164,"text":"how the group difference was tested, with"},{"start":212.164,"end":212.969,"text":"an effect size."},{"start":213.75900000000001,"end":216.167,"text":"The companion guide runs the same model in"},{"start":216.167,"end":216.279,"text":"R."},{"start":216.614,"end":218.85399999999998,"text":"Try a smaller or a larger window, and"},{"start":218.85399999999998,"end":220.53300000000002,"text":"watch how the network changes."}]},"KHzwP0eMwTk":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.285,"text":"This video explains sequential pattern"},{"start":2.285,"end":4.738,"text":"mining, with a focus on what each number"},{"start":4.738,"end":7.077,"text":"means and which data points stand behind"},{"start":7.077,"end":7.248,"text":"it."},{"start":9.068,"end":11.295,"text":"Everything starts from an event log."},{"start":11.666,"end":14.635,"text":"Each row is one coded turn: a session, a"},{"start":14.635,"end":17.047,"text":"turn number, a speaker, and a code."},{"start":17.885,"end":19.93,"text":"Sorting the rows by turn turns each"},{"start":19.93,"end":22.033,"text":"session into one ordered sequence of"},{"start":22.033,"end":22.374,"text":"codes."},{"start":23.172,"end":25.531,"text":"In our synthetic example there are four"},{"start":25.531,"end":27.772,"text":"thousand one hundred thirty six coded"},{"start":27.772,"end":30.425,"text":"turns, but only one hundred sessions:"},{"start":30.425,"end":32.902,"text":"fifty in a treatment group and fifty in a"},{"start":32.902,"end":33.728,"text":"control group."},{"start":34.53,"end":36.053,"text":"That difference matters."},{"start":36.434,"end":39.227,"text":"In pattern mining, the session, not the"},{"start":39.227,"end":41.639,"text":"turn, is the unit that gets counted."},{"start":43.457,"end":46.692,"text":"To see how counting works, take five short"},{"start":46.692,"end":50.36,"text":"sessions, and one candidate pattern: ask,"},{"start":50.36,"end":52.445,"text":"then explain, then example."},{"start":53.394,"end":55.556,"text":"A session contains the pattern if the"},{"start":55.556,"end":57.889,"text":"three codes appear in that order, even"},{"start":57.889,"end":59.481,"text":"with other turns in between."},{"start":59.823,"end":62.098,"text":"Sessions one, two, and five qualify."},{"start":62.44,"end":64.203,"text":"Sessions three and four do not."},{"start":64.982,"end":67.492,"text":"Session two contains the pattern twice,"},{"start":67.492,"end":69.284,"text":"but it still counts only once."},{"start":70.11,"end":72.478,"text":"So the support of the pattern is three out"},{"start":72.478,"end":74.57,"text":"of five sessions, or zero point six."},{"start":76.31700000000001,"end":78.902,"text":"Support describes how common a pattern is."},{"start":79.271,"end":82.226,"text":"Confidence asks a conditional question: of"},{"start":82.226,"end":84.872,"text":"the sessions with ask then explain, what"},{"start":84.872,"end":86.47200000000001,"text":"share go on to an example?"},{"start":86.842,"end":88.688,"text":"Here, zero point seven five."},{"start":89.544,"end":91.73400000000001,"text":"But a high confidence can mislead."},{"start":92.12100000000001,"end":94.697,"text":"An example appears in eighty percent of"},{"start":94.697,"end":97.14500000000001,"text":"all sessions anyway, so the lift,"},{"start":97.14500000000001,"end":99.91499999999999,"text":"confidence divided by that base rate, is"},{"start":99.91499999999999,"end":101.654,"text":"about zero point nine four."},{"start":102.041,"end":104.811,"text":"Ask and explain do not make an example any"},{"start":104.811,"end":106.80799999999999,"text":"more likely than it already is."},{"start":108.632,"end":109.944,"text":"Back to the real data."},{"start":110.30199999999999,"end":112.806,"text":"When any number of turns may separate the"},{"start":112.806,"end":115.43,"text":"codes, almost every short pattern appears"},{"start":115.43,"end":116.86099999999999,"text":"in nearly every session."},{"start":117.219,"end":119.902,"text":"Support hits the ceiling, and it no longer"},{"start":119.902,"end":121.154,"text":"tells patterns apart."},{"start":121.989,"end":123.913,"text":"Requiring the codes to occur in"},{"start":123.913,"end":126.19800000000001,"text":"consecutive turns restores the spread."},{"start":126.559,"end":129.265,"text":"That gap rule is a modeling choice, and it"},{"start":129.265,"end":130.828,"text":"should always be reported."},{"start":132.677,"end":135.551,"text":"The minimum support threshold is a second"},{"start":135.551,"end":136.03,"text":"choice."},{"start":136.44,"end":139.383,"text":"At zero point one, one hundred forty two"},{"start":139.383,"end":140.34,"text":"patterns pass."},{"start":140.751,"end":143.556,"text":"At zero point five, only thirty two do."},{"start":145.444,"end":146.865,"text":"Now a group question."},{"start":147.27100000000002,"end":150.114,"text":"The pattern example, explain, example"},{"start":150.114,"end":152.753,"text":"appears in thirty percent of treatment"},{"start":152.753,"end":155.799,"text":"sessions, and in twelve percent of control"},{"start":155.799,"end":156.40800000000002,"text":"sessions."},{"start":157.302,"end":159.93099999999998,"text":"Is a gap of eighteen points larger than"},{"start":159.93099999999998,"end":160.392,"text":"chance?"},{"start":160.786,"end":162.824,"text":"Turns within a session are not"},{"start":162.824,"end":165.585,"text":"independent, so a standard test on turn"},{"start":165.585,"end":168.017,"text":"counts would overstate the certainty."},{"start":168.9,"end":171.339,"text":"A permutation test keeps every session"},{"start":171.339,"end":173.715,"text":"intact, and shuffles only the group"},{"start":173.715,"end":176.529,"text":"labels, five thousand times, recomputing"},{"start":176.529,"end":177.655,"text":"the gap each time."},{"start":178.507,"end":181.058,"text":"This is the resulting null distribution."},{"start":181.44,"end":184.183,"text":"Our observed gap sits in its tail, for a"},{"start":184.183,"end":186.861,"text":"two sided p value of zero point zero four"},{"start":186.861,"end":187.244,"text":"seven."},{"start":188.114,"end":190.75900000000001,"text":"But we tested ninety two patterns, not"},{"start":190.75900000000001,"end":191.017,"text":"one."},{"start":191.404,"end":194.308,"text":"After a Benjamini Hochberg correction, the"},{"start":194.308,"end":196.889,"text":"adjusted value is zero point zero seven"},{"start":196.889,"end":199.405,"text":"eight, so this pattern should not be"},{"start":199.405,"end":201.276,"text":"called a reliable difference."},{"start":203.121,"end":205.528,"text":"When you report sequential pattern mining,"},{"start":205.528,"end":207.828,"text":"state the unit of analysis, the gap rule"},{"start":207.828,"end":210.128,"text":"and the support threshold, and how group"},{"start":210.128,"end":212.161,"text":"differences were tested and corrected."},{"start":212.978,"end":214.913,"text":"And remember that frequent patterns"},{"start":214.913,"end":216.148,"text":"describe what happened."},{"start":216.471,"end":218.942,"text":"They do not, on their own, explain why it"},{"start":218.942,"end":219.426,"text":"happened."},{"start":220.175,"end":222.452,"text":"The companion guide walks through the same"},{"start":222.452,"end":222.981,"text":"data in R."},{"start":223.299,"end":225.099,"text":"Try changing the gap rule and the"},{"start":225.099,"end":227.21699999999998,"text":"threshold, and watch how the patterns"},{"start":227.21699999999998,"end":227.588,"text":"change."}]},"Poo-UGoTyhw":{"language":"en","provenance":"Provided timed English captions","cues":[{"start":0.06,"end":2.354,"text":"In this short video, we look at how people"},{"start":2.354,"end":4.597,"text":"learn from words and pictures, and at the"},{"start":4.597,"end":6.534,"text":"design principles that follow from it."},{"start":8.277,"end":10.263,"text":"Richard Mayer's cognitive theory of"},{"start":10.263,"end":12.194,"text":"multimedia learning rests on three"},{"start":12.194,"end":12.856,"text":"assumptions."},{"start":13.625,"end":15.448,"text":"First, we take in spoken words and"},{"start":15.448,"end":17.369,"text":"pictures through two separate channels."},{"start":18.112,"end":20.54,"text":"Second, each channel can hold only a"},{"start":20.54,"end":23.28,"text":"little at a time, so working memory fills"},{"start":23.28,"end":23.778,"text":"quickly."},{"start":24.609,"end":26.059,"text":"Third, learning is active."},{"start":26.37,"end":28.701,"text":"We connect the words and the pictures, and"},{"start":28.701,"end":30.618,"text":"we link them to what we already know."},{"start":32.417,"end":34.569,"text":"Because that capacity is limited, Mayer"},{"start":34.569,"end":36.67,"text":"describes three kinds of processing that"},{"start":36.67,"end":37.439,"text":"compete for it."},{"start":38.193,"end":40.704,"text":"Extraneous processing is effort wasted on"},{"start":40.704,"end":41.422,"text":"poor design."},{"start":41.781,"end":44.232,"text":"Essential processing represents the core"},{"start":44.232,"end":44.71,"text":"content."},{"start":45.069,"end":47.46,"text":"And generative processing is the deeper"},{"start":47.46,"end":49.075,"text":"work of making sense of it."},{"start":49.88,"end":51.791,"text":"In a cluttered lesson, extraneous"},{"start":51.791,"end":54.021,"text":"processing crowds out the generative work"},{"start":54.021,"end":55.242,"text":"that leads to learning."},{"start":56.047,"end":58.638,"text":"Good design reduces the extraneous load,"},{"start":58.638,"end":61.108,"text":"manages the essential load, and leaves"},{"start":61.108,"end":62.976,"text":"room for generative processing."},{"start":64.805,"end":66.805,"text":"Mayer's design principles can be grouped"},{"start":66.805,"end":68.122,"text":"by the demand they address."},{"start":68.892,"end":71.504,"text":"To reduce extraneous processing, cut what"},{"start":71.504,"end":74.116,"text":"is not needed, highlight what is, avoid"},{"start":74.116,"end":76.787,"text":"repeating the narration as on-screen text,"},{"start":76.787,"end":79.102,"text":"and place words near the pictures they"},{"start":79.102,"end":79.636,"text":"describe."},{"start":80.49,"end":83.106,"text":"To manage essential processing, break the"},{"start":83.106,"end":85.723,"text":"lesson into learner-paced segments, teach"},{"start":85.723,"end":88.339,"text":"the key terms first, and present words as"},{"start":88.339,"end":90.123,"text":"narration rather than as text."},{"start":90.908,"end":93.413,"text":"To foster generative processing, use a"},{"start":93.413,"end":96.28399999999999,"text":"conversational style, a natural voice, and"},{"start":96.28399999999999,"end":98.667,"text":"an on-screen guide who gestures toward"},{"start":98.667,"end":99.461,"text":"what matters."},{"start":101.285,"end":103.688,"text":"This video tries to follow its own advice."},{"start":104.031,"end":106.319,"text":"Most words are spoken, not printed,"},{"start":106.319,"end":108.72200000000001,"text":"highlights point to what matters, and a"},{"start":108.72200000000001,"end":110.782,"text":"guide gestures toward the key ideas."},{"start":111.602,"end":113.857,"text":"One principle deserves a closer look."},{"start":114.22200000000001,"end":116.904,"text":"The voice principle favors a human voice,"},{"start":116.904,"end":118.854,"text":"yet this narration is synthetic."},{"start":119.219,"end":121.84,"text":"Some studies suggest that modern synthetic"},{"start":121.84,"end":124.582,"text":"voices can work nearly as well, which is a"},{"start":124.582,"end":126.106,"text":"question worth examining."},{"start":127.899,"end":130.304,"text":"To put this into practice, pick a short"},{"start":130.304,"end":132.824,"text":"instructional video you have used, decide"},{"start":132.824,"end":135.114,"text":"which principle it follows and which it"},{"start":135.114,"end":137.405,"text":"breaks, and redesign one minute of it."},{"start":138.215,"end":140.192,"text":"Bring your example and your redesign to"},{"start":140.192,"end":142.36599999999999,"text":"the discussion board, and we will compare"},{"start":142.36599999999999,"end":142.959,"text":"notes there."}]},"es-10-question-frameworks":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.82,"text":"Meet Maya, our made up doctoral student."},{"start":3.06,"end":5.8,"text":"In Review Families, she matches her"},{"start":5.8,"end":9,"text":"purpose to a review family, but her topic,"},{"start":9,"end":11.64,"text":"AI chatbot feedback on undergraduate"},{"start":11.64,"end":14.1,"text":"writing, isn't a question yet."},{"start":14.64,"end":15.64,"text":"Today's idea?"},{"start":15.8,"end":18.04,"text":"Pick your framework by the kind of"},{"start":18.04,"end":18.38,"text":"question."},{"start":18.76,"end":21.46,"text":"Every element you keep gets checked at"},{"start":21.46,"end":23.8,"text":"screening, usually as an eligibility"},{"start":23.8,"end":26.54,"text":"clause, a rule for who gets in."},{"start":26.84,"end":30.16,"text":"Only some become search blocks, words you"},{"start":30.16,"end":31.28,"text":"type into a database."},{"start":32.133,"end":35.313,"text":"A question framework is a checklist of"},{"start":35.313,"end":37.233,"text":"what your question must pin down."},{"start":37.413,"end":41.753,"text":"The best known is PICO, from the well"},{"start":41.753,"end":44.373,"text":"built clinical question Richardson and"},{"start":44.373,"end":46.636,"text":"colleagues described in nineteen ninety"},{"start":46.636,"end":46.753,"text":"five."},{"start":48.143,"end":49.283,"text":"Let's fill it in for Maya."},{"start":49.503,"end":52.823,"text":"P is the population, undergraduates."},{"start":52.963,"end":56.523,"text":"I is the intervention, chatbot feedback on"},{"start":56.523,"end":57.063,"text":"drafts."},{"start":57.543,"end":61.263,"text":"C is the comparison, instructor, peer, or"},{"start":61.263,"end":61.903,"text":"no feedback."},{"start":62.643,"end":65.543,"text":"And O is the outcome, writing quality."},{"start":66.283,"end":68.823,"text":"Put together, it's an answerable question."},{"start":69.6,"end":72.1,"text":"Now watch what each element turns into."},{"start":72.86,"end":75.9,"text":"First, each of Maya's four becomes an"},{"start":75.9,"end":76.86,"text":"eligibility clause."},{"start":77.82,"end":79.88,"text":"Undergraduates becomes undergraduate"},{"start":79.88,"end":82.2,"text":"students in credit bearing courses."},{"start":82.96,"end":85.68,"text":"The chatbot becomes a chatbot giving"},{"start":85.68,"end":87.86,"text":"feedback on the student's own draft."},{"start":88.54,"end":90.76,"text":"The other two get clauses too."},{"start":91.59,"end":94.41,"text":"Second, only some become search blocks."},{"start":95.21,"end":97.87,"text":"Population and intervention do, since"},{"start":97.87,"end":99.21,"text":"authors name them up front."},{"start":99.99,"end":102.87,"text":"Comparison and outcome usually stay screen"},{"start":102.87,"end":105.51,"text":"only, checked by a person reading each"},{"start":105.51,"end":108.67,"text":"study, because, as Cochrane warns, they"},{"start":108.67,"end":110.81,"text":"may not be well described in an abstract."},{"start":111.72,"end":112.42,"text":"Here's the trap."},{"start":112.88,"end":114.58,"text":"Writing shows up twice."},{"start":114.86,"end":117.94,"text":"As the topic, every relevant study names"},{"start":117.94,"end":119.22,"text":"it, so it's searched."},{"start":119.56,"end":122.74,"text":"The outcome is what got measured, like"},{"start":122.74,"end":124.66,"text":"rubric scores, checked at screening."},{"start":125.38,"end":128.76,"text":"Outcomes are rarely eligibility rules, so"},{"start":128.76,"end":131.9,"text":"a study without the numbers stays in, but"},{"start":131.9,"end":134.26,"text":"one that never measured writing can go."},{"start":135.067,"end":137.887,"text":"PICO has a family, each adding or"},{"start":137.887,"end":139.127,"text":"swapping one letter."},{"start":139.567,"end":143.627,"text":"Add an S for study design, a T for time,"},{"start":143.627,"end":145.927,"text":"or a second C, for context."},{"start":146.627,"end":149.707,"text":"Time and context usually get screened."},{"start":149.907,"end":151.407,"text":"Design is different."},{"start":152.047,"end":154.447,"text":"Cochrane's typical search includes a"},{"start":154.447,"end":156.667,"text":"design block, but test it first."},{"start":157.517,"end":161.777,"text":"PECO swaps intervention for exposure,"},{"start":161.777,"end":164.557,"text":"something students already do that nobody"},{"start":164.557,"end":167.037,"text":"assigned, like using a chatbot often."},{"start":167.377,"end":170.297,"text":"It asks whether heavy use goes with"},{"start":170.297,"end":172.917,"text":"stronger writing confidence, not whether"},{"start":172.917,"end":173.877,"text":"it causes it."},{"start":174.257,"end":177.497,"text":"Drop the comparison, and you get PEO."},{"start":178.4,"end":180.94,"text":"Now Omar, Maya's made up screening"},{"start":180.94,"end":183.6,"text":"partner, looks at the same topic from"},{"start":183.6,"end":184.36,"text":"another angle."},{"start":184.86,"end":187.6,"text":"How do undergraduate writers experience"},{"start":187.6,"end":190.14,"text":"chatbot feedback on their drafts?"},{"start":190.68,"end":192.12,"text":"Does PICO fit?"},{"start":198.13,"end":198.69,"text":"Not really."},{"start":199.21,"end":202.47,"text":"Nothing's compared, and no outcome is"},{"start":202.47,"end":202.85,"text":"measured."},{"start":202.85,"end":206.19,"text":"Cochrane's handbook says PICO is"},{"start":206.19,"end":208.49,"text":"generally not suitable for questions"},{"start":208.49,"end":209.87,"text":"around qualitative data."},{"start":210.45,"end":214.11,"text":"So Omar reaches for SPIDER, from Cooke,"},{"start":214.11,"end":215.57,"text":"Smith, and Booth."},{"start":216.21,"end":219.31,"text":"S is the sample, undergraduate writers."},{"start":219.31,"end":222.97,"text":"PI, the phenomenon of interest, is their"},{"start":222.97,"end":224.85,"text":"experience of chatbot feedback."},{"start":225.55,"end":228.85,"text":"D is design, how the data were gathered,"},{"start":228.85,"end":229.67,"text":"like interviews."},{"start":230.25,"end":234.05,"text":"E is evaluation, like trust, or uptake,"},{"start":234.05,"end":235.13,"text":"whether they used it."},{"start":235.27,"end":238.83,"text":"And R is research type, qualitative or"},{"start":238.83,"end":239.49,"text":"mixed methods."},{"start":240.15,"end":241.27,"text":"Which would you search?"},{"start":247.21,"end":247.89,"text":"Here's the answer."},{"start":248.15,"end":251.59,"text":"Every letter still gets screened, but only"},{"start":251.59,"end":253.99,"text":"the sample and the phenomenon get"},{"start":253.99,"end":254.37,"text":"searched."},{"start":254.65,"end":257.49,"text":"The other three usually aren't searched."},{"start":257.79,"end":260.81,"text":"One team suspects requiring qualitative"},{"start":260.81,"end":263.83,"text":"plus a named method was too restrictive,"},{"start":263.83,"end":266.71,"text":"since some missed studies only said"},{"start":266.71,"end":267.15,"text":"interviews."},{"start":267.15,"end":271.89,"text":"JBI uses a close cousin, population,"},{"start":271.89,"end":274.73,"text":"phenomenon of interest, and context."},{"start":275.6,"end":277.98,"text":"So the question type picks the framework."},{"start":278.3,"end":281.62,"text":"Effects get the PICO family, exposures"},{"start":281.62,"end":285.1,"text":"get PECO, and experiences get SPIDER."},{"start":285.72,"end":288.4,"text":"Mapping a field is another kind, and for"},{"start":288.4,"end":292.04,"text":"scoping reviews JBI suggests PCC,"},{"start":292.04,"end":295.08,"text":"population, concept, and context."},{"start":295.2,"end":298.46,"text":"For a map of Maya's topic, the concept is"},{"start":298.46,"end":300.28,"text":"chatbot feedback on writing."},{"start":302.69,"end":305.83,"text":"Service questions can use SPICE, from"},{"start":305.83,"end":308.87,"text":"Booth, built for library work, not health."},{"start":309.61,"end":312.41,"text":"Picture a writing center adding a chatbot"},{"start":312.41,"end":313.09,"text":"first pass."},{"start":313.99,"end":316.83,"text":"Setting and intervention get searched, and"},{"start":316.83,"end":318.95,"text":"the rest is usually screened."},{"start":321.26,"end":324.54,"text":"Policy questions get ECLIPSE, built by"},{"start":324.54,"end":327.06,"text":"Wildridge and Bell for health policy and"},{"start":327.06,"end":327.46,"text":"management."},{"start":328.3,"end":330.9,"text":"Imagine a program director drafting a"},{"start":330.9,"end":331.8,"text":"chatbot policy."},{"start":332.4,"end":335.4,"text":"Its authors note not every element fits"},{"start":335.4,"end":338.02,"text":"every search, but each is worth"},{"start":338.02,"end":338.94,"text":"considering first."},{"start":341.51,"end":345.69,"text":"How and why questions can use CIMO,"},{"start":345.69,"end":347.23,"text":"from management research."},{"start":347.55,"end":350.97,"text":"In big first year sections, chatbot"},{"start":350.97,"end":354.15,"text":"feedback plus a reflection task might"},{"start":354.15,"end":357.63,"text":"prompt self regulated revision, leading to"},{"start":357.63,"end":359.01,"text":"more substantive revisions."},{"start":359.69,"end":363.03,"text":"That middle step is the mechanism, and it"},{"start":363.03,"end":365.75,"text":"often shows up only in the full text."},{"start":368.25,"end":370.77,"text":"Booth and colleagues counted thirty eight"},{"start":370.77,"end":371.41,"text":"frameworks."},{"start":372.17,"end":374.97,"text":"One called PerSPEcTiF suits qualitative"},{"start":374.97,"end":378.65,"text":"reviews of complex interventions, and one"},{"start":378.65,"end":380.81,"text":"called BeHEMoTh helps when you're"},{"start":380.81,"end":381.77,"text":"searching for theory."},{"start":382.53,"end":384.35,"text":"So don't collect acronyms."},{"start":384.75,"end":387.67,"text":"A framework's a scaffold, not a cage."},{"start":388.567,"end":390.847,"text":"So does the framework change what you"},{"start":390.847,"end":391.167,"text":"find?"},{"start":391.167,"end":394.687,"text":"Methley and colleagues ran one qualitative"},{"start":394.687,"end":397.667,"text":"review three ways, same search terms."},{"start":397.667,"end":400.187,"text":"PICO pulled in twenty three thousand,"},{"start":400.187,"end":402.527,"text":"seven hundred fifty eight records."},{"start":402.527,"end":406.887,"text":"PICOS found four hundred forty eight,"},{"start":406.887,"end":409.327,"text":"SPIDER only two hundred thirty nine."},{"start":410.107,"end":412.187,"text":"But look at the eighteen studies that"},{"start":412.187,"end":412.507,"text":"belonged."},{"start":412.507,"end":414.927,"text":"PICO found all eighteen."},{"start":415.287,"end":418.467,"text":"The other two found thirteen each, and no"},{"start":418.467,"end":419.007,"text":"new ones."},{"start":419.447,"end":422.707,"text":"Their precision was higher, so more of"},{"start":422.707,"end":424.367,"text":"what they found was relevant."},{"start":425.247,"end":428.307,"text":"Methley's team recommends PICO for a"},{"start":428.307,"end":429.827,"text":"fully comprehensive search."},{"start":430.447,"end":431.667,"text":"Two cautions, though."},{"start":432.207,"end":435.167,"text":"It's one health topic, and the tools used"},{"start":435.167,"end":436.847,"text":"different numbers of search blocks."},{"start":437.707,"end":441.567,"text":"Still, every block has to match, so each"},{"start":441.567,"end":443.607,"text":"one you add can lose studies."},{"start":444.187,"end":447.527,"text":"That's why Omar searches only two letters."},{"start":447.527,"end":451.367,"text":"And Eriksen and Frandsen found only three"},{"start":451.367,"end":454.027,"text":"studies testing PICO for searching."},{"start":456.467,"end":457.027,"text":"Let's recap."},{"start":457.887,"end":460.387,"text":"First, pick the framework by the kind of"},{"start":460.387,"end":463.407,"text":"question, effect, exposure, experience,"},{"start":463.407,"end":466.647,"text":"map, service, policy, or how something"},{"start":466.647,"end":467.047,"text":"works."},{"start":467.607,"end":470.447,"text":"Second, every element you keep gets"},{"start":470.447,"end":472.967,"text":"checked at screening, usually as an"},{"start":472.967,"end":473.927,"text":"eligibility clause."},{"start":474.707,"end":478.167,"text":"Third, only elements authors reliably name"},{"start":478.167,"end":480.787,"text":"become search blocks, tested against"},{"start":480.787,"end":482.327,"text":"studies you know belong."},{"start":483.267,"end":484.567,"text":"Where does this go next?"},{"start":485.007,"end":488.127,"text":"Review Families helps you pick the kind of"},{"start":488.127,"end":488.387,"text":"review."},{"start":489.167,"end":492.687,"text":"Criteria on Trial turns kept elements into"},{"start":492.687,"end":495.827,"text":"eligibility criteria, and Search Strings"},{"start":495.827,"end":498.467,"text":"turns your search elements into concept"},{"start":498.467,"end":498.847,"text":"blocks."},{"start":499.507,"end":500.427,"text":"Try it yourself."},{"start":500.927,"end":503.607,"text":"Write your question in a framework and"},{"start":503.607,"end":506.207,"text":"mark each element search or screen."},{"start":506.847,"end":509.087,"text":"Then pick a published review on your"},{"start":509.087,"end":509.387,"text":"topic."},{"start":509.387,"end":512.647,"text":"Which elements did it actually search?"}]},"es-01-review-families":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":0.54,"text":"Meet Maya."},{"start":0.96,"end":3.64,"text":"She's a made up doctoral student, and"},{"start":3.64,"end":5.54,"text":"she's found a review that changed her"},{"start":5.54,"end":8.26,"text":"mind, called A Systematic Review of"},{"start":8.26,"end":10.02,"text":"Chatbots in Writing Instruction."},{"start":10.42,"end":13,"text":"Before she leans on it, she wants to name"},{"start":13,"end":15.46,"text":"its review family, meaning its type."},{"start":15.88,"end":17.44,"text":"Should she trust the title?"},{"start":17.92,"end":18.82,"text":"Here's the move."},{"start":19.08,"end":22.28,"text":"The purpose gives a first guess, and the"},{"start":22.28,"end":24.08,"text":"methods get the final say."},{"start":24.9,"end":27.54,"text":"A review is a paper that pulls together"},{"start":27.54,"end":29.7,"text":"many studies on one topic."},{"start":30.32,"end":33.54,"text":"A review family is a type of review,"},{"start":33.54,"end":36.1,"text":"sorted by the job it does."},{"start":36.62,"end":40.16,"text":"Here we'll use five, and we'll meet them"},{"start":40.16,"end":41.44,"text":"on Maya's topic."},{"start":42.36,"end":44.98,"text":"A systematic review answers one focused"},{"start":44.98,"end":47.58,"text":"question, with steps planned ahead and"},{"start":47.58,"end":49.58,"text":"reported so others could repeat them."},{"start":49.8,"end":52.66,"text":"On Maya's topic, it would ask whether"},{"start":52.66,"end":55.64,"text":"chatbot feedback improves essay revisions,"},{"start":55.64,"end":57.9,"text":"versus teacher feedback alone."},{"start":58.77,"end":61.49,"text":"A scoping review maps what exists."},{"start":61.91,"end":64.87,"text":"It might ask which studies on chatbot"},{"start":64.87,"end":67.21,"text":"feedback exist and what they measure."},{"start":68.07,"end":71.09,"text":"Notice it doesn't ask whether chatbots"},{"start":71.09,"end":71.31,"text":"work."},{"start":72.15,"end":75.47,"text":"A narrative review argues a view, built"},{"start":75.47,"end":77.07,"text":"from the author's own reading."},{"start":77.49,"end":80.53,"text":"Picture an expert's overview that makes a"},{"start":80.53,"end":82.91,"text":"case for how classes should change."},{"start":83.76,"end":86.34,"text":"An integrative review combines different"},{"start":86.34,"end":87.42,"text":"kinds of evidence."},{"start":88.06,"end":90.5,"text":"Whittemore and Knafl describe mixing"},{"start":90.5,"end":93.7,"text":"experiments, non experimental studies like"},{"start":93.7,"end":95.9,"text":"surveys, and theory papers."},{"start":96.56,"end":98.96,"text":"It'd ask what all three say."},{"start":99.69,"end":101.49,"text":"And a qualitative meta synthesis"},{"start":101.49,"end":104.27,"text":"interprets findings across qualitative"},{"start":104.27,"end":106.45,"text":"studies, like interview studies."},{"start":106.79,"end":109.87,"text":"It's also called qualitative evidence"},{"start":109.87,"end":110.35,"text":"synthesis."},{"start":111.13,"end":113.47,"text":"Its question could be how students"},{"start":113.47,"end":115.61,"text":"experience chatbot feedback."},{"start":116.53,"end":117.63,"text":"Here's a handy trick."},{"start":118.42,"end":120.71,"text":"Ask what job the purpose sentence is"},{"start":120.71,"end":121.03,"text":"doing."},{"start":121.56,"end":124.43,"text":"Is it answering, mapping, arguing,"},{"start":124.43,"end":126.11,"text":"combining, or interpreting?"},{"start":126.55,"end":128.89,"text":"Real papers use other words, though."},{"start":129.66,"end":132.35,"text":"Setting out to examine an effect is an"},{"start":132.35,"end":132.93,"text":"answer job."},{"start":133.74,"end":136.4,"text":"Grant and Booth, who compared fourteen"},{"start":136.4,"end":140.14,"text":"review types, suggest judging a review by"},{"start":140.14,"end":143.54,"text":"its fitness for purpose, not one gold"},{"start":143.54,"end":144.04,"text":"standard."},{"start":144.64,"end":148.14,"text":"And families overlap, so if a review sits"},{"start":148.14,"end":150.72,"text":"between two, name the closest."},{"start":151.6,"end":152.64,"text":"What about the methods?"},{"start":153.42,"end":156.2,"text":"Titles can be wrong, which is why Grant"},{"start":156.2,"end":158.54,"text":"and Booth inspect four processes."},{"start":159.52,"end":162.4,"text":"Search means which databases they used,"},{"start":162.4,"end":165.26,"text":"and the exact words they typed in, called"},{"start":165.26,"end":166.18,"text":"search strings."},{"start":167.08,"end":169.76,"text":"Appraisal asks whether they judged each"},{"start":169.76,"end":170.58,"text":"study's quality."},{"start":171.26,"end":173.68,"text":"Synthesis is how they combined the"},{"start":173.68,"end":175.98,"text":"findings, like a table or themes."},{"start":175.98,"end":179.18,"text":"And analysis is what they conclude."},{"start":180.05,"end":181.81,"text":"Keep these four words handy."},{"start":182.27,"end":185.75,"text":"Check the purpose plus all four, since the"},{"start":185.75,"end":188.19,"text":"more you check, the stronger your case."},{"start":189,"end":192.08,"text":"Let's try one on Maya's card, using a made"},{"start":192.08,"end":193.04,"text":"up warm up review."},{"start":193.3,"end":196.06,"text":"Its purpose sentence, often found near the"},{"start":196.06,"end":198.62,"text":"end of the introduction, says it aims to"},{"start":198.62,"end":201.28,"text":"map chatbot feedback research and where"},{"start":201.28,"end":202.08,"text":"its gaps are."},{"start":202.8,"end":203.92,"text":"Start with the purpose."},{"start":204.3,"end":208.54,"text":"Its job is to map and find gaps, so our"},{"start":208.54,"end":210.26,"text":"first guess is scoping."},{"start":211.04,"end":211.84,"text":"Now the methods."},{"start":212.08,"end":215.6,"text":"The search used four databases, full"},{"start":215.6,"end":216.86,"text":"strings and all."},{"start":217,"end":219.82,"text":"A systematic review would do that too."},{"start":220.48,"end":223.14,"text":"Scoping reviews are rigorous, not"},{"start":223.14,"end":223.7,"text":"sloppier."},{"start":223.88,"end":227.3,"text":"There's no appraisal, which fits, since a"},{"start":227.3,"end":229.98,"text":"scoping review maps studies and rarely"},{"start":229.98,"end":230.68,"text":"judges them."},{"start":230.92,"end":233.78,"text":"The synthesis builds tables counting"},{"start":233.78,"end":237.16,"text":"studies by research design, like how many"},{"start":237.16,"end":239.24,"text":"experiments and how many surveys."},{"start":239.48,"end":242.5,"text":"And the analysis gives a list of gaps."},{"start":243.42,"end":246.24,"text":"All four fit, and the title agrees."},{"start":246.76,"end":248.34,"text":"It's a scoping review."},{"start":249.233,"end":251.893,"text":"Your turn now, with Maya's own review."},{"start":252.133,"end":255.613,"text":"Its purpose says this review aims to show"},{"start":255.613,"end":258.793,"text":"teachers why chatbots belong in every"},{"start":258.793,"end":259.473,"text":"writing class."},{"start":260.763,"end":263.363,"text":"From the purpose alone, which family would"},{"start":263.363,"end":263.723,"text":"you guess?"},{"start":264.383,"end":265.063,"text":"Pause here."},{"start":271.423,"end":272.483,"text":"Look at the verb."},{"start":272.823,"end":275.443,"text":"Show why chatbots belong."},{"start":276.003,"end":279.283,"text":"That's arguing a case, not answering a"},{"start":279.283,"end":280.103,"text":"focused question."},{"start":280.363,"end":284.423,"text":"So Maya's first guess is narrative, though"},{"start":284.423,"end":286.123,"text":"the title says systematic."},{"start":287.163,"end":288.123,"text":"Now for the methods."},{"start":288.543,"end":291.383,"text":"Let's test each row against Grant and"},{"start":291.383,"end":293.203,"text":"Booth's table entry for systematic"},{"start":293.203,"end":293.683,"text":"reviews."},{"start":294.103,"end":297.603,"text":"The search used Google Scholar plus papers"},{"start":297.603,"end":299.803,"text":"the author knew, with no strings."},{"start":300.183,"end":303.483,"text":"A systematic review tries to find every"},{"start":303.483,"end":306.863,"text":"relevant study, an exhaustive search, so"},{"start":306.863,"end":308.063,"text":"this one misses."},{"start":309.013,"end":310.453,"text":"What about appraisal?"},{"start":310.673,"end":313.673,"text":"None is reported, and in a systematic"},{"start":313.673,"end":317.113,"text":"review, appraisal can decide which studies"},{"start":317.113,"end":317.753,"text":"stay in."},{"start":318.193,"end":319.333,"text":"Another miss."},{"start":319.733,"end":323.613,"text":"The synthesis goes study by study, plus a"},{"start":323.613,"end":327.133,"text":"summary table, and systematic synthesis is"},{"start":327.133,"end":330.913,"text":"typically prose plus tables, so that fits."},{"start":331.943,"end":334.843,"text":"And the analysis argues for chatbots."},{"start":334.943,"end":338.163,"text":"A systematic review may recommend practice"},{"start":338.163,"end":341.463,"text":"too, but it also says what remains"},{"start":341.463,"end":343.843,"text":"unknown, and how certain it is."},{"start":344.493,"end":346.043,"text":"This one never does."},{"start":346.323,"end":348.683,"text":"That's one fit out of four."},{"start":349.423,"end":353.463,"text":"So which should win, the label or the"},{"start":353.463,"end":353.803,"text":"methods?"},{"start":354.403,"end":355.843,"text":"Pause and decide."},{"start":362.383,"end":363.363,"text":"The methods win."},{"start":363.923,"end":366.743,"text":"Grant and Booth call inspecting the four"},{"start":366.743,"end":369.743,"text":"processes the only pragmatic way to"},{"start":369.743,"end":370.783,"text":"classify a review."},{"start":371.143,"end":374.903,"text":"So the purpose gives a first guess, and"},{"start":374.903,"end":376.863,"text":"the methods get the final say."},{"start":377.463,"end":380.343,"text":"If they disagree, say so when you write it"},{"start":380.343,"end":380.503,"text":"up."},{"start":381.153,"end":383.193,"text":"Now compare a narrative review."},{"start":383.673,"end":386.633,"text":"Grant and Booth file it under literature"},{"start":386.633,"end":388.213,"text":"review, a looser entry."},{"start":388.573,"end":391.813,"text":"There, the search may or may not be"},{"start":391.813,"end":394.833,"text":"comprehensive, appraisal may or may not"},{"start":394.833,"end":397.593,"text":"happen, and the synthesis is typically"},{"start":397.593,"end":398.073,"text":"prose."},{"start":398.333,"end":401.833,"text":"And the analysis argues a view, which is"},{"start":401.833,"end":402.733,"text":"the narrative job."},{"start":402.993,"end":404.913,"text":"So nothing here conflicts."},{"start":405.953,"end":407.553,"text":"But be careful."},{"start":407.833,"end":411.453,"text":"An entry that loose fits almost anything."},{"start":412.093,"end":415.453,"text":"The evidence is the purpose plus three"},{"start":415.453,"end":416.733,"text":"systematic misses."},{"start":417.433,"end":420.533,"text":"So Maya's verdict is a narrative review,"},{"start":420.533,"end":422.253,"text":"labelled systematic."},{"start":423.443,"end":424.103,"text":"Was it convincing?"},{"start":424.403,"end":426.943,"text":"A narrative review isn't automatically"},{"start":426.943,"end":429.403,"text":"second rate, and Greenhalgh and colleagues"},{"start":429.403,"end":432.423,"text":"argue systematic is no synonym for high"},{"start":432.423,"end":432.823,"text":"quality."},{"start":433.063,"end":436.103,"text":"The trouble is, this one claims a method"},{"start":436.103,"end":439.043,"text":"it didn't use, and its thin search, with"},{"start":439.043,"end":441.343,"text":"no strings reported, may have missed"},{"start":441.343,"end":442.603,"text":"studies that disagree."},{"start":443.463,"end":446.163,"text":"So Maya writes her verdict, and ends her"},{"start":446.163,"end":447.963,"text":"notes with one method question."},{"start":448.683,"end":451.883,"text":"Why only Google Scholar, and how were"},{"start":451.883,"end":452.543,"text":"studies picked?"},{"start":453.367,"end":454.187,"text":"Let's pull it together."},{"start":454.827,"end":456.967,"text":"The purpose gives a first guess."},{"start":457.547,"end":460.927,"text":"The methods get the final say, so check"},{"start":460.927,"end":462.187,"text":"all four processes."},{"start":462.967,"end":465.007,"text":"And the label isn't the family."},{"start":465.587,"end":468.587,"text":"Families overlap, and none is"},{"start":468.587,"end":469.567,"text":"automatically best."},{"start":470.447,"end":471.667,"text":"Now try it yourself."},{"start":472.467,"end":474.767,"text":"Pick an influential review in your field"},{"start":474.767,"end":477.967,"text":"and do what Maya did, including whether it"},{"start":477.967,"end":480.327,"text":"convinced you, and one method question."},{"start":481.227,"end":484.127,"text":"Start by copying its purpose sentence,"},{"start":484.127,"end":486.567,"text":"then fill in all four method rows."},{"start":487.317,"end":490.647,"text":"And ask yourself, do its methods earn its"},{"start":490.647,"end":490.947,"text":"label?"},{"start":491.367,"end":492.387,"text":"You've got this."}]},"es-08-six-ways-to-synthesize":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":0.94,"text":"Meet Maya again."},{"start":1.36,"end":4.32,"text":"She's a made up doctoral student, studying"},{"start":4.32,"end":7.12,"text":"AI feedback on undergraduates' writing."},{"start":7.54,"end":10.84,"text":"Here's her pile, twelve made up studies,"},{"start":10.84,"end":13.74,"text":"with randomized trials, before and after"},{"start":13.74,"end":17.24,"text":"studies, a survey, interviews, and a"},{"start":17.24,"end":17.78,"text":"theory paper."},{"start":18.6,"end":21.74,"text":"In Review Families, you matched a review's"},{"start":21.74,"end":23.3,"text":"purpose to its family."},{"start":23.96,"end":27.4,"text":"Today we zoom in on the synthesis step,"},{"start":27.4,"end":29.64,"text":"where findings get combined."},{"start":30.32,"end":31.84,"text":"Here's the big idea."},{"start":32.5,"end":34.98,"text":"Each kind of synthesis does something"},{"start":34.98,"end":38.94,"text":"different to the same pile, so you pick by"},{"start":38.94,"end":41.2,"text":"what you need to combine, and how."},{"start":41.98,"end":45.72,"text":"We'll meet six, four review types and two"},{"start":45.72,"end":46.82,"text":"statistical methods."},{"start":47.733,"end":49.553,"text":"First, a narrative review."},{"start":50.323,"end":52.813,"text":"Maya hand picks the studies she thinks"},{"start":52.813,"end":56.213,"text":"matter most, say a big trial, an interview"},{"start":56.213,"end":57.873,"text":"study, and the theory paper."},{"start":58.563,"end":62.113,"text":"Then she argues a view, that AI feedback"},{"start":62.113,"end":65.433,"text":"should support teachers, not replace them."},{"start":66.063,"end":68.703,"text":"Greenhalgh and colleagues call that goal"},{"start":68.703,"end":70.483,"text":"an authoritative argument."},{"start":71.303,"end":72.663,"text":"But here's the risk."},{"start":73.463,"end":76.483,"text":"Grant and Booth warn that authors may only"},{"start":76.483,"end":78.843,"text":"pick literature that supports their view."},{"start":79.543,"end":81.123,"text":"See the nine she left out?"},{"start":81.833,"end":83.453,"text":"Now a scoping review."},{"start":83.833,"end":86.413,"text":"This time Maya doesn't argue."},{"start":86.693,"end":90.393,"text":"She charts every study by design and by"},{"start":90.393,"end":93.613,"text":"what it measured, and the whole pile lands"},{"start":93.613,"end":94.333,"text":"on the map."},{"start":95.103,"end":97.843,"text":"Six intervention studies measured writing"},{"start":97.843,"end":98.303,"text":"quality."},{"start":98.503,"end":101.463,"text":"But not one of them measured what students"},{"start":101.463,"end":102.443,"text":"think of the feedback."},{"start":102.843,"end":105.243,"text":"That empty cell's a gap."},{"start":105.723,"end":108.203,"text":"Munn and colleagues say mapping what"},{"start":108.203,"end":110.383,"text":"exists is what scoping is for."},{"start":110.883,"end":113.943,"text":"Notice she counted studies but never"},{"start":113.943,"end":115.623,"text":"formally appraised their quality."},{"start":116.333,"end":119.073,"text":"Number three, the systematic review."},{"start":119.313,"end":121.693,"text":"It answers one focused question."},{"start":122.013,"end":125.193,"text":"Does AI feedback improve writing quality,"},{"start":125.193,"end":127.193,"text":"compared with teacher feedback?"},{"start":127.493,"end":130.153,"text":"This time Maya doesn't pick."},{"start":130.693,"end":132.713,"text":"Criteria set in advance do."},{"start":132.893,"end":136.573,"text":"The first keeps studies comparing AI with"},{"start":136.573,"end":136.973,"text":"teachers."},{"start":137.213,"end":140.253,"text":"The second keeps those measuring writing"},{"start":140.253,"end":140.753,"text":"quality."},{"start":141.563,"end":142.823,"text":"Three trials pass."},{"start":143.423,"end":147.103,"text":"Next, she appraises each one, judging how"},{"start":147.103,"end":149.443,"text":"much its design or conduct could have"},{"start":149.443,"end":150.283,"text":"biased the result."},{"start":150.823,"end":154.003,"text":"Study one has some concerns, and studies"},{"start":154.003,"end":156.243,"text":"two and three have low concerns."},{"start":156.823,"end":160.023,"text":"Then she answers the question, in prose"},{"start":160.023,"end":163.243,"text":"with a table, and the appraisal shapes how"},{"start":163.243,"end":164.563,"text":"sure it can sound."},{"start":165.2,"end":167.2,"text":"Next, an integrative review."},{"start":167.98,"end":169.46,"text":"Now the question's bigger."},{"start":170.06,"end":172.94,"text":"How does AI feedback work for students?"},{"start":173.66,"end":177.16,"text":"Maya pieces together one picture, a made"},{"start":177.16,"end":177.64,"text":"up model."},{"start":178.52,"end":181.06,"text":"Students engage with the comments, they"},{"start":181.06,"end":183.46,"text":"revise, and their writing changes."},{"start":184.48,"end":187.1,"text":"The survey and an interview tell her how"},{"start":187.1,"end":188,"text":"students engage."},{"start":188.44,"end":191.1,"text":"The revision studies fill the middle."},{"start":191.22,"end":194.14,"text":"The writing quality studies sit at the"},{"start":194.14,"end":197.22,"text":"end, and the theory paper explains the"},{"start":197.22,"end":197.46,"text":"links."},{"start":198.1,"end":201.06,"text":"Whittemore and Knafl describe this kind of"},{"start":201.06,"end":204.2,"text":"mix, experimental and non experimental"},{"start":204.2,"end":207.06,"text":"research, plus empirical and theoretical"},{"start":207.06,"end":207.5,"text":"sources."},{"start":208.5,"end":210.38,"text":"Now meta analysis."},{"start":210.66,"end":212.92,"text":"Doing one needs statistical training"},{"start":212.92,"end":215.58,"text":"beyond this series, so concepts only."},{"start":216,"end":218.62,"text":"Back to her systematic review's three"},{"start":218.62,"end":219.12,"text":"trials."},{"start":219.52,"end":223.16,"text":"Each one reports an effect size, how far"},{"start":223.16,"end":225.64,"text":"apart the groups ended up, in standard"},{"start":225.64,"end":226.64,"text":"deviation units."},{"start":227.3,"end":229.04,"text":"That's where each block sits."},{"start":229.95,"end":232.77,"text":"A meta analysis pools them into one"},{"start":232.77,"end":233.67,"text":"weighted average."},{"start":234.05,"end":236.77,"text":"The Cochrane Handbook explains that"},{"start":236.77,"end":239.31,"text":"bigger, more precise studies get more"},{"start":239.31,"end":239.65,"text":"weight."},{"start":240.05,"end":242.897,"text":"Study two's the big one, at sixty three"},{"start":242.897,"end":243.27,"text":"percent."},{"start":243.93,"end":246.89,"text":"On this seesaw, the pooled answer is where"},{"start":246.89,"end":247.49,"text":"it balances."},{"start":247.99,"end":251.17,"text":"Try the plain average, zero point three,"},{"start":251.17,"end":253.59,"text":"where every study counts the same."},{"start":260.46,"end":262.96,"text":"See how it tips toward the big study?"},{"start":263.22,"end":266.16,"text":"The balance point lands at about zero"},{"start":266.16,"end":266.84,"text":"point two."},{"start":267.48,"end":268.74,"text":"That's pooling."},{"start":268.94,"end":272.04,"text":"But it only works when studies are similar"},{"start":272.04,"end":274.94,"text":"enough, in who took part, what was"},{"start":274.94,"end":276.8,"text":"compared, and what was measured."},{"start":277.08,"end":280.36,"text":"So trials four and five, which compared"},{"start":280.36,"end":283.44,"text":"teachers with peers, and trial twelve,"},{"start":283.44,"end":286.46,"text":"which measured revising, stay off this"},{"start":286.46,"end":286.72,"text":"beam."},{"start":287.433,"end":290.233,"text":"Last, network meta analysis."},{"start":290.953,"end":293.613,"text":"Now Maya wonders which feedback works"},{"start":293.613,"end":296.793,"text":"best, AI, teacher, or peer."},{"start":297.573,"end":300.713,"text":"In a network diagram, each circle is a"},{"start":300.713,"end":304.093,"text":"type of feedback, and each line, trials"},{"start":304.093,"end":306.313,"text":"that compared two of them head to head."},{"start":307.033,"end":310.213,"text":"Three trials compared AI with teachers,"},{"start":310.213,"end":313.693,"text":"pooled at zero point two in AI's favour."},{"start":313.693,"end":317.133,"text":"Two compared teachers with peers, zero"},{"start":317.133,"end":319.573,"text":"point one five in the teachers' favour."},{"start":319.573,"end":323.213,"text":"But no trial ever compared AI with peers."},{"start":323.453,"end":325.253,"text":"Can she still compare them?"},{"start":331.063,"end":334.583,"text":"Yes, indirectly, through the teacher, the"},{"start":334.583,"end":336.563,"text":"common comparator both sets share."},{"start":336.883,"end":339.923,"text":"Add the two steps, zero point two plus"},{"start":339.923,"end":343.263,"text":"zero point one five, so AI's about zero"},{"start":343.263,"end":345.663,"text":"point three five ahead of peers, though"},{"start":345.663,"end":347.883,"text":"that's usually weaker than a direct trial."},{"start":348.143,"end":351.383,"text":"A network meta analysis combines both"},{"start":351.383,"end":353.383,"text":"kinds of evidence in a single analysis."},{"start":354.493,"end":355.133,"text":"Here's the catch."},{"start":355.493,"end":358.453,"text":"That route only holds if both sets of"},{"start":358.453,"end":360.593,"text":"trials are similar, on average, in"},{"start":360.593,"end":363.053,"text":"everything important but the feedback."},{"start":363.773,"end":365.333,"text":"That's transitivity."},{"start":366.013,"end":368.693,"text":"Suppose teacher feedback meant one quick"},{"start":368.693,"end":370.933,"text":"comment in the first set, and a full"},{"start":370.933,"end":372.333,"text":"conference in the second."},{"start":372.993,"end":374.973,"text":"Then the route may not hold."},{"start":375.273,"end":378.173,"text":"And if a trial ever compares AI with"},{"start":378.173,"end":381.093,"text":"peers directly, it should land near zero"},{"start":381.093,"end":381.753,"text":"point three five."},{"start":382.693,"end":383.913,"text":"That's consistency."},{"start":384.8,"end":385.96,"text":"So how do you choose?"},{"start":386.48,"end":388.32,"text":"Ask what you need to combine."},{"start":389.06,"end":391.6,"text":"An argument from hand picked reading is"},{"start":391.6,"end":392.02,"text":"narrative."},{"start":392.34,"end":394.78,"text":"A map of everything is scoping."},{"start":395.16,"end":398.2,"text":"One answer from appraised studies is"},{"start":398.2,"end":398.66,"text":"systematic."},{"start":399.69,"end":402.43,"text":"One picture from mixed designs and theory"},{"start":402.43,"end":403.85,"text":"is integrative."},{"start":404.47,"end":407.67,"text":"One weighted estimate is meta analysis."},{"start":408.13,"end":411.07,"text":"Links among three or more options is"},{"start":411.07,"end":412.57,"text":"network meta analysis."},{"start":412.85,"end":415.69,"text":"Those last two build on a systematic"},{"start":415.69,"end":416.17,"text":"review."},{"start":416.45,"end":418.95,"text":"You'd only do them with methods training"},{"start":418.95,"end":422.21,"text":"and, often, a statistician, so they're"},{"start":422.21,"end":423.57,"text":"beyond this series."},{"start":424.42,"end":425.14,"text":"Your turn."},{"start":425.58,"end":428.56,"text":"Maya asks how students' views and the"},{"start":428.56,"end":430.34,"text":"trial results fit together."},{"start":430.74,"end":431.78,"text":"Which is it?"},{"start":437.7,"end":440.3,"text":"It's integrative, since she's bringing"},{"start":440.3,"end":442.86,"text":"different designs into one picture."},{"start":443.667,"end":444.207,"text":"Let's recap."},{"start":444.547,"end":447.467,"text":"First, the same pile can become an"},{"start":447.467,"end":451.447,"text":"argument, a map, an answer, a picture, an"},{"start":451.447,"end":453.207,"text":"estimate, or a network."},{"start":453.727,"end":456.707,"text":"Second, pick by what you need to combine,"},{"start":456.707,"end":457.767,"text":"and how."},{"start":458.267,"end":461.847,"text":"Third, pooling needs comparable studies,"},{"start":461.847,"end":465.127,"text":"and indirect routes need similar trial"},{"start":465.127,"end":465.447,"text":"sets."},{"start":466.297,"end":467.037,"text":"Try it yourself."},{"start":467.477,"end":470.537,"text":"Pick one published review in your area,"},{"start":470.537,"end":473.737,"text":"ask what it combined, and how, and which"},{"start":473.737,"end":475.017,"text":"of the six it is."},{"start":475.357,"end":478.317,"text":"Then check whether that synthesis fits its"},{"start":478.317,"end":480.917,"text":"question, its evidence, and its claim."},{"start":481.177,"end":482.897,"text":"So try one sentence."},{"start":482.897,"end":486.717,"text":"Maya's is, my review combines surveys,"},{"start":486.717,"end":489.397,"text":"interviews, and trials by building one"},{"start":489.397,"end":489.717,"text":"picture."},{"start":489.717,"end":490.017,"text":"Now write yours."}]},"es-03-criteria-on-trial":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.08,"text":"Meet Maya, a made up doctoral student"},{"start":3.08,"end":6.04,"text":"reviewing AI generated feedback on"},{"start":6.04,"end":8.68,"text":"undergraduates' writing, and her screening"},{"start":8.68,"end":9.7,"text":"partner, Omar."},{"start":10.28,"end":12.26,"text":"They've read the same abstract."},{"start":13.05,"end":14.38,"text":"Maya says include."},{"start":15.03,"end":16.56,"text":"Omar says exclude."},{"start":17.3,"end":18.38,"text":"Nobody's careless."},{"start":18.97,"end":22,"text":"Their criterion is just vague, and a"},{"start":22,"end":24.42,"text":"criterion is the rule for which studies"},{"start":24.42,"end":24.92,"text":"get in."},{"start":25.62,"end":29.22,"text":"Today you'll turn a vague criterion into"},{"start":29.22,"end":32.22,"text":"an operational one, and then put it on"},{"start":32.22,"end":32.52,"text":"trial."},{"start":33.333,"end":35.793,"text":"First, where does a criterion live?"},{"start":36.153,"end":39.353,"text":"In a protocol, the review's plan, written"},{"start":39.353,"end":40.473,"text":"before the search."},{"start":41.073,"end":44.633,"text":"PRISMA P, a protocol checklist, wants that"},{"start":44.633,"end":47.593,"text":"plan explicitly documented before you"},{"start":47.593,"end":47.853,"text":"begin."},{"start":48.213,"end":51.913,"text":"It has seventeen items, and today we'll"},{"start":51.913,"end":53.133,"text":"zoom in on eligibility."},{"start":54.203,"end":55.403,"text":"Here's why that matters."},{"start":55.863,"end":58.963,"text":"Say Maya glimpses a result, and the"},{"start":58.963,"end":60.863,"text":"platform comment studies look great."},{"start":61.303,"end":63.183,"text":"She's tempted to let them in."},{"start":63.183,"end":66.363,"text":"Cochrane's handbook says judgements like"},{"start":66.363,"end":69.183,"text":"that should not depend on the findings, as"},{"start":69.183,"end":69.983,"text":"far as possible."},{"start":70.733,"end":71.973,"text":"Now the key idea."},{"start":72.213,"end":75.673,"text":"An operational criterion is a rule you can"},{"start":75.673,"end":78.233,"text":"check against the abstract's own words."},{"start":78.593,"end":81.813,"text":"For example, a chatbot makes the feedback."},{"start":82.113,"end":84.933,"text":"An abstract either says that or it"},{"start":84.933,"end":85.333,"text":"doesn't."},{"start":85.713,"end":87.653,"text":"Technology enhanced fails."},{"start":88.473,"end":90.113,"text":"Enhanced how, exactly?"},{"start":90.653,"end":91.773,"text":"Here's the test."},{"start":92.053,"end":95.113,"text":"Would two strangers make the same call?"},{"start":95.867,"end":96.927,"text":"So let's test it."},{"start":97.427,"end":100.627,"text":"Maya and Omar each screen fourteen made up"},{"start":100.627,"end":104.147,"text":"records independently, deciding in or out."},{"start":104.647,"end":107.927,"text":"A record is one database entry, a title"},{"start":107.927,"end":110.827,"text":"and abstract, your first look at a study."},{"start":111.467,"end":114.427,"text":"This is a pilot, a small trial run."},{"start":114.687,"end":118.087,"text":"Maya reads broadly, so any technology"},{"start":118.087,"end":118.567,"text":"counts."},{"start":119.067,"end":122.727,"text":"Omar reads narrowly, so technology must"},{"start":122.727,"end":124.267,"text":"shape the feedback itself."},{"start":125.217,"end":127.517,"text":"Before I show you, take a guess."},{"start":127.917,"end":130.917,"text":"How many of the fourteen do they agree on?"},{"start":137.177,"end":138.277,"text":"Let's count the matches."},{"start":138.817,"end":141.704,"text":"That's nine of fourteen, or sixty four"},{"start":141.704,"end":142.057,"text":"percent."},{"start":142.057,"end":146.137,"text":"The five splits are boundary cases,"},{"start":146.137,"end":148.837,"text":"records near the edge of the rule, and"},{"start":148.837,"end":151.317,"text":"Maya writes them down in a decision log."},{"start":152.127,"end":155.387,"text":"But some of that agreement is luck, and"},{"start":155.387,"end":157.087,"text":"Cohen's kappa takes it out."},{"start":157.367,"end":160.647,"text":"Step one is to imagine them both guessing"},{"start":160.647,"end":162.367,"text":"blindly at their own rates."},{"start":162.927,"end":166.267,"text":"Maya says in twelve times out of fourteen,"},{"start":166.267,"end":167.887,"text":"and out twice."},{"start":168.367,"end":171.287,"text":"Omar, in seven and out seven."},{"start":171.567,"end":174.967,"text":"The chance both say in by luck is twelve"},{"start":174.967,"end":178.247,"text":"fourteenths times seven fourteenths, zero"},{"start":178.247,"end":179.067,"text":"point four three."},{"start":179.067,"end":183.087,"text":"Both out is two fourteenths times seven"},{"start":183.087,"end":185.547,"text":"fourteenths, zero point zero seven."},{"start":185.967,"end":189.487,"text":"Add them, and luck agrees half the time."},{"start":190.227,"end":191.467,"text":"Okay, step two."},{"start":191.807,"end":194.507,"text":"Picture a line from zero to one."},{"start":194.847,"end":198.407,"text":"Zero means no better than luck, and one"},{"start":198.407,"end":199.627,"text":"means perfect."},{"start":200.107,"end":203.687,"text":"Luck already gives zero point five, so the"},{"start":203.687,"end":205.927,"text":"room above luck is the other half."},{"start":206.327,"end":209.507,"text":"Their sixty four percent is zero point six"},{"start":209.507,"end":212.747,"text":"four three, just zero point one four three"},{"start":212.747,"end":213.887,"text":"into that room."},{"start":214.427,"end":217.387,"text":"Divide by zero point five, and you get"},{"start":217.387,"end":218.627,"text":"zero point two nine."},{"start":219.267,"end":220.407,"text":"That's kappa."},{"start":220.507,"end":223.047,"text":"It isn't twenty nine percent agreement."},{"start":223.327,"end":226.507,"text":"They used just under a third of the room,"},{"start":226.507,"end":227.847,"text":"and that's low."},{"start":228.633,"end":230.473,"text":"Retrain them, or rewrite?"},{"start":231.533,"end":234.953,"text":"Rewrite, because every split traces to one"},{"start":234.953,"end":235.793,"text":"vague phrase."},{"start":236.353,"end":237.373,"text":"Here's the trick."},{"start":237.773,"end":239.353,"text":"Ask three questions."},{"start":240.133,"end":241.353,"text":"Who makes the feedback?"},{"start":241.813,"end":243.673,"text":"AI, like a chatbot."},{"start":244.193,"end":245.153,"text":"What's it about?"},{"start":245.413,"end":247.133,"text":"The student's own draft."},{"start":247.533,"end":249.233,"text":"Who sees it, and when?"},{"start":249.513,"end":252.573,"text":"The student, directly, during the task."},{"start":253.233,"end":255.733,"text":"Feedback an instructor or peer wrote is"},{"start":255.733,"end":255.993,"text":"out."},{"start":256.673,"end":257.373,"text":"Your turn."},{"start":257.693,"end":260.193,"text":"Run record two through the clauses."},{"start":260.593,"end":264.213,"text":"Is it in or out, and which clause decides?"},{"start":270.853,"end":271.233,"text":"It's out."},{"start":271.453,"end":274.553,"text":"An instructor wrote it, so clause one"},{"start":274.553,"end":275.053,"text":"fails."},{"start":275.433,"end":278.793,"text":"They rescreen with version two, and four"},{"start":278.793,"end":279.913,"text":"splits vanish."},{"start":280.553,"end":282.713,"text":"Watch rows seven and thirteen."},{"start":283.313,"end":285.133,"text":"Both flip to out."},{"start":285.853,"end":287.193,"text":"Same arithmetic now."},{"start":287.393,"end":291.953,"text":"Maya says in six, Omar five, so luck gives"},{"start":291.953,"end":293.013,"text":"fifty two percent."},{"start":293.013,"end":296.493,"text":"They agree on thirteen of fourteen, so"},{"start":296.493,"end":298.413,"text":"kappa is zero point eight five."},{"start":298.913,"end":302.073,"text":"In this made up example only the words"},{"start":302.073,"end":302.493,"text":"changed."},{"start":302.793,"end":306.673,"text":"In a real pilot, try version two on fresh"},{"start":306.673,"end":306.953,"text":"records."},{"start":307.933,"end":310.613,"text":"Side by side, both numbers jump."},{"start":311.213,"end":311.953,"text":"So what?"},{"start":312.633,"end":315.513,"text":"Here, clearer words gave consistent"},{"start":315.513,"end":316.033,"text":"decisions."},{"start":316.833,"end":320.173,"text":"But agreement isn't correctness, and"},{"start":320.173,"end":320.833,"text":"here's why."},{"start":321.6,"end":323.66,"text":"Let's put version two on trial."},{"start":323.66,"end":325.52,"text":"Take record thirteen."},{"start":325.52,"end":328.54,"text":"An AI flags errors for the instructor,"},{"start":328.54,"end":330.42,"text":"who relays them to students."},{"start":330.42,"end":333.38,"text":"Clause three says the student sees it"},{"start":333.38,"end":335.4,"text":"directly, so both say out."},{"start":335.4,"end":338.94,"text":"But notice, under version one they both"},{"start":338.94,"end":339.5,"text":"said in."},{"start":339.5,"end":342.92,"text":"The sharper rule made them wrongly exclude"},{"start":342.92,"end":344.2,"text":"a plausible study."},{"start":344.93,"end":346.79,"text":"Record twelve still splits them."},{"start":347.17,"end":349.89,"text":"Does a simulated audience reacting to a"},{"start":349.89,"end":351.43,"text":"draft count as feedback?"},{"start":352.17,"end":354.57,"text":"That's the ambiguity to test with a"},{"start":354.57,"end":354.85,"text":"partner."},{"start":355.56,"end":357.7,"text":"So how should Maya settle thirteen?"},{"start":358.34,"end":361.52,"text":"She could edit clause three, or narrow her"},{"start":361.52,"end":364.1,"text":"question to on-screen feedback so the old"},{"start":364.1,"end":364.74,"text":"clause fits."},{"start":365.3,"end":366.96,"text":"Which fix is honest?"},{"start":373.36,"end":374.38,"text":"It's fix A."},{"start":375.16,"end":377.24,"text":"Narrowing a question just to ease"},{"start":377.24,"end":379.52,"text":"screening is redesigning it for"},{"start":379.52,"end":379.92,"text":"convenience."},{"start":379.92,"end":383.56,"text":"Cochrane makes a similar point about which"},{"start":383.56,"end":384.84,"text":"participants to include."},{"start":385.78,"end":388.06,"text":"Criteria should be broad enough for the"},{"start":388.06,"end":390.84,"text":"likely diversity of studies, yet narrow"},{"start":390.84,"end":392.66,"text":"enough for a meaningful answer."},{"start":393.14,"end":394.58,"text":"Same balance here."},{"start":395.06,"end":397.98,"text":"Fix A keeps Maya's question whole."},{"start":398.79,"end":401.59,"text":"Changing a criterion isn't cheating if you"},{"start":401.59,"end":403.05,"text":"log it and explain why."},{"start":403.81,"end":406.35,"text":"Clause three now says it reaches the"},{"start":406.35,"end":408.97,"text":"student during the task, directly or"},{"start":408.97,"end":409.91,"text":"through the instructor."},{"start":410.27,"end":413.51,"text":"It came from the pilot, not from peeking"},{"start":413.51,"end":415.97,"text":"at findings, so Maya puts it in her"},{"start":415.97,"end":418.35,"text":"amendment log, not her decision log."},{"start":418.59,"end":421.35,"text":"And record thirteen now passes."},{"start":422.167,"end":422.767,"text":"Let's recap."},{"start":423.107,"end":426.347,"text":"First, write criteria into the protocol"},{"start":426.347,"end":427.907,"text":"before any results."},{"start":428.507,"end":432.067,"text":"Second, make every clause checkable, and"},{"start":432.067,"end":433.167,"text":"test it with a partner."},{"start":433.507,"end":436.687,"text":"Third, agreement isn't correctness."},{"start":437.447,"end":440.227,"text":"Fix the criterion to fit your question,"},{"start":440.227,"end":441.407,"text":"not the reverse."},{"start":442.367,"end":443.207,"text":"Now try it yourself."},{"start":443.887,"end":446.467,"text":"Write a draft question and one criterion"},{"start":446.467,"end":448.007,"text":"in operational language."},{"start":448.547,"end":451.027,"text":"Defend why your claim needs it, and why"},{"start":451.027,"end":453.267,"text":"it's neither too broad nor too narrow."},{"start":453.927,"end":456.347,"text":"Name one study it might wrongly exclude,"},{"start":456.347,"end":459.167,"text":"and write down one ambiguity to test."},{"start":459.507,"end":461.807,"text":"Then have a colleague apply it to a"},{"start":461.807,"end":464.647,"text":"boundary case, and revise if the call is"},{"start":464.647,"end":464.867,"text":"unclear."},{"start":465.717,"end":467.217,"text":"Here's a good next step."},{"start":467.657,"end":470.517,"text":"Pilot your criterion with a real partner"},{"start":470.517,"end":474.037,"text":"on six to eight records, some clearly in,"},{"start":474.037,"end":477.157,"text":"some clearly out, some doubtful."},{"start":477.317,"end":480.917,"text":"With so few, watch the splits more than"},{"start":480.917,"end":481.317,"text":"kappa."},{"start":481.957,"end":484.897,"text":"Then ask yourself, would two strangers"},{"start":484.897,"end":486.497,"text":"make the same call?"}]},"es-04-search-strings":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.92,"text":"Searching is a method, not just a box you"},{"start":2.92,"end":3.44,"text":"type into."},{"start":3.86,"end":6.54,"text":"Today you'll test your string against"},{"start":6.54,"end":9.3,"text":"studies you already know, and revise it"},{"start":9.3,"end":9.94,"text":"with evidence."},{"start":10.8,"end":13.38,"text":"Search guides recommend exactly that"},{"start":13.38,"end":13.62,"text":"check."},{"start":14.467,"end":17.567,"text":"Meet Maya, a made up doctoral student."},{"start":18.167,"end":20.687,"text":"Her question is whether AI chatbot"},{"start":20.687,"end":23.547,"text":"feedback improves undergraduates' writing."},{"start":23.907,"end":28.047,"text":"Her first string is simple: chatbot, AND"},{"start":28.047,"end":29.767,"text":"writing, AND undergraduate."},{"start":30.927,"end":34.197,"text":"She runs it in a made up database of three"},{"start":34.197,"end":37.447,"text":"hundred records and gets twelve hits."},{"start":38.007,"end":39.207,"text":"Is twelve good?"},{"start":39.487,"end":42.467,"text":"The number alone can't tell you."},{"start":43.167,"end":45.587,"text":"Before searching, Maya gathered ten"},{"start":45.587,"end":48.307,"text":"studies she knows belong in her review,"},{"start":48.307,"end":49.907,"text":"say, from a recent one."},{"start":50.287,"end":52.327,"text":"We'll call them known studies."},{"start":53.027,"end":55.947,"text":"A good string should find them, so that's"},{"start":55.947,"end":57.047,"text":"the first thing we'll test."},{"start":57.867,"end":59.047,"text":"Let's run the test."},{"start":59.827,"end":63.047,"text":"Her string finds only four of the ten."},{"start":63.887,"end":66.827,"text":"That share is called recall, or"},{"start":66.827,"end":67.647,"text":"sensitivity."},{"start":67.647,"end":70.927,"text":"It's the share of all the relevant studies"},{"start":70.927,"end":72.627,"text":"that your search finds."},{"start":72.627,"end":76.347,"text":"Nobody knows them all, so we estimate it"},{"start":76.347,"end":77.507,"text":"on the ones we know."},{"start":77.507,"end":81.107,"text":"Here that's four out of ten, or point"},{"start":81.107,"end":81.347,"text":"four."},{"start":82.077,"end":83.677,"text":"Then there's the cost side."},{"start":84.097,"end":87.357,"text":"Every hit is a record someone has to read,"},{"start":87.357,"end":90.217,"text":"so we call them records to screen."},{"start":90.977,"end":94.357,"text":"There's also precision, the share of hits"},{"start":94.357,"end":97.517,"text":"that turn out relevant, but you only learn"},{"start":97.517,"end":99.117,"text":"that after screening."},{"start":99.907,"end":102.207,"text":"Let's chart it, with records to screen"},{"start":102.207,"end":105.067,"text":"across and known studies found going up."},{"start":105.467,"end":108.887,"text":"Version one is cheap, but it misses six."},{"start":109.767,"end":111.547,"text":"So why so many misses?"},{"start":112.047,"end":115.267,"text":"Each line of Maya's string is one concept,"},{"start":115.267,"end":116.527,"text":"a concept block."},{"start":116.987,"end":120.527,"text":"Right now each block holds one word, but"},{"start":120.527,"end":122.847,"text":"authors word the same idea differently."},{"start":123.777,"end":124.557,"text":"Here's the rule."},{"start":124.857,"end":128.357,"text":"Within a block, join the wordings with OR,"},{"start":128.357,"end":131.817,"text":"so either word counts and the block gets"},{"start":131.817,"end":132.157,"text":"wider."},{"start":132.917,"end":136.497,"text":"Across blocks, join with AND, so every"},{"start":136.497,"end":139.917,"text":"concept has to appear and the results get"},{"start":139.917,"end":140.317,"text":"narrower."},{"start":141.2,"end":143.64,"text":"Maya's first fix goes big."},{"start":143.86,"end":147.42,"text":"She adds conversational agent, plus broad"},{"start":147.42,"end":149.74,"text":"words like AI and technology."},{"start":150.06,"end":153.78,"text":"She adds essay and composition, and she"},{"start":153.78,"end":155.12,"text":"drops the who block."},{"start":155.82,"end":157.6,"text":"What do you think happens to the hits?"},{"start":158.3,"end":159.58,"text":"Pause and guess."},{"start":166.04,"end":168.6,"text":"They jump to two hundred thirty four hits,"},{"start":168.6,"end":171.42,"text":"and all ten known studies are in there."},{"start":171.9,"end":174.38,"text":"Version two lands far right."},{"start":174.8,"end":176.6,"text":"So is she done?"},{"start":182.89,"end":183.39,"text":"Not yet."},{"start":183.61,"end":185.15,"text":"Look at the cost."},{"start":185.47,"end":187.73,"text":"Many of those two hundred thirty four"},{"start":187.73,"end":191.39,"text":"records are noise, like AI essay scoring"},{"start":191.39,"end":192.27,"text":"in high schools."},{"start":192.59,"end":195.59,"text":"The Cochrane Handbook says to maximize"},{"start":195.59,"end":199.25,"text":"sensitivity, that's recall, while striving"},{"start":199.25,"end":200.73,"text":"for reasonable precision."},{"start":201.633,"end":204.313,"text":"So in version three, she trims."},{"start":204.313,"end":207.953,"text":"She drops AI and technology and puts the"},{"start":207.953,"end":208.813,"text":"who block back."},{"start":209.313,"end":212.233,"text":"That's forty one hits, and nine of ten"},{"start":212.233,"end":213.193,"text":"known studies."},{"start":214.033,"end":214.733,"text":"Much cheaper."},{"start":214.993,"end":218.133,"text":"But one known study is missing, number"},{"start":218.133,"end":218.493,"text":"ten."},{"start":218.893,"end":222.193,"text":"Here's its title: a conversational agent"},{"start":222.193,"end":224.693,"text":"for essay revision, with university"},{"start":224.693,"end":225.313,"text":"students."},{"start":225.693,"end":227.893,"text":"Which block let it slip?"},{"start":234.233,"end":236.793,"text":"Bramer and colleagues suggest testing the"},{"start":236.793,"end":238.753,"text":"missed record against each block."},{"start":239.413,"end":242.813,"text":"Block A, the tool: conversational agent is"},{"start":242.813,"end":244.313,"text":"there, so that's a match."},{"start":244.633,"end":248.053,"text":"Block B, the outcome: essay, another"},{"start":248.053,"end":248.433,"text":"match."},{"start":249.073,"end":253.113,"text":"Now block C, who: undergraduate, college,"},{"start":253.113,"end":254.173,"text":"or higher education."},{"start":254.513,"end":258.093,"text":"But the record says university, so no"},{"start":258.093,"end":258.353,"text":"match."},{"start":259.073,"end":261.253,"text":"Block C is the one that failed."},{"start":262.033,"end":264.693,"text":"Notice that every block is one more place"},{"start":264.693,"end":266.153,"text":"a study can slip through."},{"start":266.803,"end":269.533,"text":"Keep only the blocks your question needs."},{"start":270.383,"end":273.643,"text":"Block C still matters, so here's the fix."},{"start":274.023,"end":277.503,"text":"Maya shortens university to its stem and"},{"start":277.503,"end":278.703,"text":"adds an asterisk."},{"start":279.003,"end":282.803,"text":"That asterisk is truncation, so it matches"},{"start":282.803,"end":285.843,"text":"university, universities, and similar"},{"start":285.843,"end":286.183,"text":"endings."},{"start":287.1,"end":288.24,"text":"She reruns it."},{"start":288.34,"end":292.48,"text":"Version four gets forty nine hits, and ten"},{"start":292.48,"end":294.12,"text":"out of ten known studies."},{"start":294.99,"end":297.05,"text":"So what did that change buy her?"},{"start":297.31,"end":300.81,"text":"It gained one known study, and it cost"},{"start":300.81,"end":302.21,"text":"eight more records."},{"start":302.99,"end":305.49,"text":"The earlier trim changed two things at"},{"start":305.49,"end":307.98,"text":"once, and together they removed one"},{"start":307.98,"end":309.35,"text":"hundred ninety three records."},{"start":310.07,"end":312.69,"text":"On its own, dropping the broad words"},{"start":312.69,"end":315.75,"text":"removes one hundred fifty five, and"},{"start":315.75,"end":318.36,"text":"restoring block C removes one hundred"},{"start":318.36,"end":319.05,"text":"thirty three."},{"start":319.37,"end":322.95,"text":"They overlap, so only one change at a time"},{"start":322.95,"end":324.73,"text":"shows which did what."},{"start":325.53,"end":329.19,"text":"Ten out of ten known is a check, not"},{"start":329.19,"end":329.57,"text":"proof."},{"start":330.52,"end":332.57,"text":"Other relevant studies may still be"},{"start":332.57,"end":335.21,"text":"missing, and the Cochrane Handbook calls"},{"start":335.21,"end":337.61,"text":"it one simple test."},{"start":338.533,"end":340.573,"text":"Now, translate, don't paste."},{"start":340.573,"end":344.253,"text":"ERIC is a database, a collection of"},{"start":344.253,"end":344.633,"text":"records."},{"start":345.493,"end":348.913,"text":"EBSCOhost and ProQuest are platforms, the"},{"start":348.913,"end":351.613,"text":"websites you search it on, and each has"},{"start":351.613,"end":352.513,"text":"its own syntax."},{"start":353.493,"end":356.273,"text":"A field code tells the platform where to"},{"start":356.273,"end":359.993,"text":"look, TI for title and AB for abstract."},{"start":360.753,"end":364.473,"text":"On EBSCOhost, Maya types block C twice."},{"start":365.153,"end":368.473,"text":"On ProQuest, one combined code covers"},{"start":368.473,"end":368.853,"text":"both."},{"start":369.673,"end":372.633,"text":"So far, everything Maya typed is free"},{"start":372.633,"end":372.993,"text":"text."},{"start":372.993,"end":376.773,"text":"But each database also tags records with"},{"start":376.773,"end":379.273,"text":"its own subject terms, called controlled"},{"start":379.273,"end":382.333,"text":"vocabulary, and the Cochrane Handbook says"},{"start":382.333,"end":384.273,"text":"to search with both."},{"start":385.053,"end":387.293,"text":"And watch out for a missing OR."},{"start":388.013,"end":391.113,"text":"In many interfaces, two words with nothing"},{"start":391.113,"end":393.593,"text":"between them get joined with AND."},{"start":393.933,"end":396.993,"text":"If an AI tool translates your string,"},{"start":396.993,"end":400.133,"text":"test it anyway, just like one you wrote."},{"start":400.693,"end":403.253,"text":"Bramer and colleagues advise checking"},{"start":403.253,"end":405.013,"text":"searches for their recall."},{"start":405.833,"end":407.813,"text":"Finally, she logs it."},{"start":408.273,"end":411.273,"text":"PRISMA S, an extension of the PRISMA"},{"start":411.273,"end":414.473,"text":"reporting guideline, lists sixteen items"},{"start":414.473,"end":415.813,"text":"for reporting a search."},{"start":416.543,"end":418.893,"text":"Here are four in Maya's made up log."},{"start":419.693,"end":422.213,"text":"She notes the database and platform, the"},{"start":422.213,"end":425.053,"text":"date, and the full string exactly as she"},{"start":425.053,"end":427.903,"text":"ran it, then the records identified, forty"},{"start":427.903,"end":428.193,"text":"nine."},{"start":428.733,"end":431.473,"text":"In your own log, add a revision note"},{"start":431.473,"end":434.733,"text":"giving forty one before, forty nine after,"},{"start":434.733,"end":435.433,"text":"and why."},{"start":436.267,"end":437.087,"text":"Let's pull it together."},{"start":437.567,"end":442.087,"text":"First, build concept blocks, OR within and"},{"start":442.087,"end":442.907,"text":"AND across."},{"start":443.607,"end":446.927,"text":"Second, test on known studies, weighing"},{"start":446.927,"end":449.647,"text":"known study recall against records to"},{"start":449.647,"end":449.927,"text":"screen."},{"start":450.387,"end":453.987,"text":"Third, change one thing at a time, and log"},{"start":453.987,"end":454.527,"text":"the counts."},{"start":455.397,"end":456.537,"text":"Now try it yourself."},{"start":457.437,"end":459.857,"text":"Pick a published review on your topic."},{"start":460.117,"end":463.217,"text":"Its included studies give you ready made"},{"start":463.217,"end":464.197,"text":"known studies."},{"start":464.917,"end":467.937,"text":"When your string misses one, test it block"},{"start":467.937,"end":470.437,"text":"by block and change one thing."},{"start":470.877,"end":473.777,"text":"Then write down the counts before and"},{"start":473.777,"end":476.937,"text":"after, and what the change gained and may"},{"start":476.937,"end":477.437,"text":"have lost."},{"start":478.227,"end":480.007,"text":"Here's a question to sit with."},{"start":480.427,"end":482.967,"text":"Pick three or more studies you know are"},{"start":482.967,"end":485.047,"text":"relevant and run your string."},{"start":485.467,"end":488.447,"text":"How many does it find, and if it misses"},{"start":488.447,"end":490.947,"text":"one, which block let it slip?"}]},"es-05-screening-calibration":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.04,"text":"Two people read the same abstract and make"},{"start":3.04,"end":3.84,"text":"different calls."},{"start":4.5,"end":8.04,"text":"Today's one core idea: calibrate before"},{"start":8.04,"end":8.76,"text":"you count."},{"start":9.43,"end":12.04,"text":"You fix your screening rules on a small"},{"start":12.04,"end":15.2,"text":"pilot first, then measure agreement."},{"start":16.19,"end":19.95,"text":"It's a habit worth building whenever two"},{"start":19.95,"end":20.75,"text":"people screen."},{"start":21.7,"end":25.26,"text":"Earlier, Maya sharpened her criterion, and"},{"start":25.26,"end":28.3,"text":"before seeing any findings she amended her"},{"start":28.3,"end":28.66,"text":"question."},{"start":29.32,"end":31.94,"text":"Do chatbot or language model comments"},{"start":31.94,"end":34.16,"text":"improve undergraduate writing?"},{"start":34.58,"end":37.36,"text":"Now she and Omar put it to work."},{"start":38.08,"end":40.22,"text":"Screening happens in two stages."},{"start":40.42,"end":43.86,"text":"In stage one you judge a record, just"},{"start":43.86,"end":45.14,"text":"title and abstract."},{"start":45.8,"end":49.26,"text":"In stage two you read the full text report"},{"start":49.26,"end":51.12,"text":"against every criterion."},{"start":52.07,"end":55.25,"text":"Here's one of Maya's records, an automated"},{"start":55.25,"end":57.67,"text":"grammar checker in a first year writing"},{"start":57.67,"end":58.11,"text":"course."},{"start":58.72,"end":60.15,"text":"Is that AI feedback?"},{"start":60.59,"end":63.07,"text":"From two lines, she can't tell."},{"start":63.79,"end":65.07,"text":"Pause and guess."},{"start":65.71,"end":68.11,"text":"Does she keep it, or drop it?"},{"start":74.03,"end":75.91,"text":"She keeps it, and here's why."},{"start":76.19,"end":79.09,"text":"The Cochrane Handbook advises being over"},{"start":79.09,"end":80.03,"text":"inclusive here."},{"start":80.53,"end":83.77,"text":"A wrong drop at stage one never gets a"},{"start":83.77,"end":87.21,"text":"second look, while a wrong keep costs one"},{"start":87.21,"end":88.73,"text":"extra full text check."},{"start":89.5,"end":92.96,"text":"Now the pilot, a small practice batch"},{"start":92.96,"end":94.74,"text":"before the real screen."},{"start":95.66,"end":99.48,"text":"Maya and Omar each screen the same forty"},{"start":99.48,"end":101.62,"text":"made up records, independently."},{"start":102.93,"end":105.87,"text":"They both kept eight and both excluded"},{"start":105.87,"end":106.71,"text":"twenty two."},{"start":107.43,"end":111.59,"text":"Maya alone kept six, and Omar alone kept"},{"start":111.59,"end":111.97,"text":"four."},{"start":112.8,"end":114.22,"text":"How often did they agree?"},{"start":114.93,"end":118.36,"text":"Eight plus twenty two out of forty, which"},{"start":118.36,"end":119.7,"text":"is seventy five percent."},{"start":119.7,"end":121.92,"text":"That's percent agreement."},{"start":122.86,"end":125.78,"text":"Now, some of that agreement is just luck."},{"start":126.48,"end":129.313,"text":"Maya keeps fourteen of forty, thirty five"},{"start":129.313,"end":132.6,"text":"percent, and Omar keeps twelve, thirty"},{"start":132.6,"end":133.1,"text":"percent."},{"start":133.1,"end":136.92,"text":"At random, both keep by luck is point"},{"start":136.92,"end":139.92,"text":"three five times point three, and both"},{"start":139.92,"end":143.11,"text":"exclude is point six five times point"},{"start":143.11,"end":145.32,"text":"seven, so fifty six percent."},{"start":145.32,"end":147.66,"text":"That's chance agreement."},{"start":148.58,"end":150.6,"text":"Next, Cohen's kappa."},{"start":150.92,"end":153.94,"text":"Picture agreement from zero to one, with"},{"start":153.94,"end":155.64,"text":"grey as luck's free share."},{"start":156.1,"end":159.3,"text":"Kappa asks how much room above luck they"},{"start":159.3,"end":159.7,"text":"reached."},{"start":160.02,"end":163.22,"text":"That's seventy five minus fifty six, over"},{"start":163.22,"end":166.22,"text":"one minus fifty six, or zero point four"},{"start":166.22,"end":168.3,"text":"three, a bit under half."},{"start":169.1,"end":170.54,"text":"Should Maya report it?"},{"start":170.92,"end":171.84,"text":"Not yet."},{"start":172.18,"end":175.12,"text":"The Cochrane Handbook says a pilot helps"},{"start":175.12,"end":178.6,"text":"refine and clarify the criteria, so treat"},{"start":178.6,"end":180.94,"text":"this first number as a diagnosis."},{"start":182.11,"end":184.39,"text":"It's tempting to think every split is"},{"start":184.39,"end":185.05,"text":"about a word."},{"start":185.29,"end":187.39,"text":"Real pilots are messier."},{"start":188.07,"end":191.43,"text":"Six are criterion ambiguity, an unclear"},{"start":191.43,"end":193.03,"text":"rule, like R07."},{"start":193.55,"end":196.93,"text":"Three are implementation slips, a clear"},{"start":196.93,"end":200.59,"text":"rule someone missed, like R22, outside the"},{"start":200.59,"end":201.05,"text":"year limit."},{"start":201.23,"end":204.45,"text":"And one is genuine judgement."},{"start":204.45,"end":208.39,"text":"In R31 the rule's clear, but they weighed"},{"start":208.39,"end":209.49,"text":"the evidence differently."},{"start":210.3,"end":213.16,"text":"Ambiguity means you revise the criterion."},{"start":213.52,"end":217.24,"text":"A slip gets an implementation note, like"},{"start":217.24,"end":218.86,"text":"check the year first."},{"start":219.22,"end":222.4,"text":"With judgement, a third reviewer decides."},{"start":223,"end":226.32,"text":"That's adjudication, and the rule stays."},{"start":226.7,"end":230.02,"text":"So each kind of split gets its own fix."},{"start":230.9,"end":233.52,"text":"Version one said feedback is made by"},{"start":233.52,"end":233.92,"text":"software."},{"start":234.7,"end":237.56,"text":"Version two says a chatbot or language"},{"start":237.56,"end":239.82,"text":"model comments on the student's own draft."},{"start":240.2,"end":243.76,"text":"It adds a boundary, so spelling or grammar"},{"start":243.76,"end":247.46,"text":"flaggers are out at full text, and keeps"},{"start":247.46,"end":250.92,"text":"the default: unsure at stage one, keep."},{"start":251.66,"end":254.3,"text":"Every disagreement goes in a decision log,"},{"start":254.3,"end":256.68,"text":"so anyone can trace each call."},{"start":257.2,"end":259.86,"text":"Here's the slip, and here's the judgement"},{"start":259.86,"end":262.38,"text":"call, which the third reviewer kept,"},{"start":262.38,"end":263.72,"text":"applying the default."},{"start":264.567,"end":267.747,"text":"Then they re-pilot on forty fresh made up"},{"start":267.747,"end":271.047,"text":"records with a similar mix, so nobody's"},{"start":271.047,"end":271.907,"text":"remembering answers."},{"start":272.547,"end":273.687,"text":"Here's the new table."},{"start":274.797,"end":275.397,"text":"Your turn."},{"start":275.757,"end":278.857,"text":"Use the same three steps, agreement,"},{"start":278.857,"end":280.537,"text":"chance, then kappa."},{"start":280.837,"end":282.257,"text":"Pause and try."},{"start":290.277,"end":292.537,"text":"Agreement's ninety two and a half percent,"},{"start":292.537,"end":296.717,"text":"chance sixty one percent, and kappa zero"},{"start":296.717,"end":297.517,"text":"point eight one."},{"start":298.697,"end":301.537,"text":"Disagreements fell from ten to three on a"},{"start":301.537,"end":305.037,"text":"similar mix, so the clearer rule is ready"},{"start":305.037,"end":305.997,"text":"for the real screen."},{"start":306.9,"end":308.38,"text":"Here's the normal case."},{"start":308.92,"end":311.52,"text":"Most records a search finds are usually"},{"start":311.52,"end":313.98,"text":"off topic, like in this made up set."},{"start":314.38,"end":317.22,"text":"They both exclude thirty six of forty,"},{"start":317.22,"end":320.1,"text":"both keep one, and split on three."},{"start":320.87,"end":323.69,"text":"Agreement is ninety two and a half percent"},{"start":323.69,"end":324.05,"text":"again."},{"start":324.41,"end":325.91,"text":"Pause and predict."},{"start":326.17,"end":328.01,"text":"Is kappa the same?"},{"start":333.94,"end":334.44,"text":"It isn't."},{"start":334.6,"end":338.24,"text":"Imagine Omar excluded all forty unread."},{"start":338.4,"end":341.66,"text":"He'd still match Maya on thirty seven, the"},{"start":341.66,"end":342.24,"text":"same score."},{"start":342.78,"end":345.74,"text":"Luck's grey bar eats almost the whole"},{"start":345.74,"end":349.14,"text":"ruler, so kappa drops to zero point three"},{"start":349.14,"end":349.38,"text":"six."},{"start":350.46,"end":353.12,"text":"Feinstein and Cicchetti called this high"},{"start":353.12,"end":355.16,"text":"agreement but low kappa."},{"start":355.56,"end":358.84,"text":"It's the prevalence trap, where prevalence"},{"start":358.84,"end":362.32,"text":"means how common keeps are, and here"},{"start":362.32,"end":363.24,"text":"they're rare."},{"start":364.01,"end":364.83,"text":"Is kappa broken?"},{"start":365.37,"end":368.03,"text":"No, it's warning you about the keeps."},{"start":368.39,"end":370.93,"text":"When one says keep, does the other agree?"},{"start":371.53,"end":375.09,"text":"Maya kept three and Omar two, five keep"},{"start":375.09,"end":378.19,"text":"votes, and only two match, on the one"},{"start":378.19,"end":379.17,"text":"record both kept."},{"start":379.61,"end":382.19,"text":"Two out of five is zero point four."},{"start":382.93,"end":385.91,"text":"The excludes look great, with seventy two"},{"start":385.91,"end":388.917,"text":"of seventy five votes matching, zero point"},{"start":388.917,"end":389.41,"text":"nine six."},{"start":390.05,"end":392.83,"text":"So report both, with kappa."},{"start":393.51,"end":396.17,"text":"Your own pilot will likely look like this,"},{"start":396.17,"end":398.29,"text":"so kappa may run modest."},{"start":398.53,"end":400.53,"text":"The keeps show where to work."},{"start":400.65,"end":403.73,"text":"And don't lean on labels like substantial,"},{"start":403.73,"end":406.29,"text":"since sources set cut offs differently."},{"start":407.167,"end":409.707,"text":"Version two becomes a field in Maya's"},{"start":409.707,"end":412.607,"text":"extraction form for included studies, and"},{"start":412.607,"end":415.187,"text":"those field definitions form her codebook."},{"start":415.407,"end":418.467,"text":"It's an executable interpretation, so"},{"start":418.467,"end":420.787,"text":"anyone following it should get the same"},{"start":420.787,"end":421.307,"text":"answer."},{"start":421.687,"end":425.747,"text":"Maya runs it on study S14, Omar runs it"},{"start":425.747,"end":427.327,"text":"too, and they agree."},{"start":428.167,"end":431.127,"text":"A screening app records independent votes"},{"start":431.127,"end":435.547,"text":"and flags conflicts, but a safe default is"},{"start":435.547,"end":438.987,"text":"that tools support the workflow and don't"},{"start":438.987,"end":439.647,"text":"own the decision."},{"start":440.467,"end":441.067,"text":"To recap."},{"start":441.307,"end":445.267,"text":"First, screen in two stages, and when"},{"start":445.267,"end":447.907,"text":"you're unsure at stage one, keep."},{"start":448.567,"end":452.667,"text":"Second, pilot, sort the disagreements, fix"},{"start":452.667,"end":455.527,"text":"the rule, and re-measure on fresh records."},{"start":456.047,"end":460.347,"text":"Third, report the table, agreement, kappa,"},{"start":460.347,"end":462.007,"text":"and agreement on keeps."},{"start":462.887,"end":465.587,"text":"Before screening, write your plan down,"},{"start":465.587,"end":468.627,"text":"with two stage screening, who screens,"},{"start":468.627,"end":471.767,"text":"calibration, adjudication, and an"},{"start":471.767,"end":474.647,"text":"exclusion reason hierarchy, meaning you"},{"start":474.647,"end":477.747,"text":"rank your criteria and log the first one a"},{"start":477.747,"end":478.367,"text":"study fails."},{"start":478.367,"end":481.647,"text":"Cochrane also asks you to define how"},{"start":481.647,"end":483.927,"text":"you'll resolve disagreements in advance."},{"start":484.857,"end":485.957,"text":"Now try it yourself."},{"start":486.677,"end":489.017,"text":"With a colleague or study partner, screen"},{"start":489.017,"end":490.657,"text":"twenty records from your search,"},{"start":490.657,"end":493.657,"text":"independently, and fill the table before"},{"start":493.657,"end":494.197,"text":"you talk."},{"start":494.917,"end":498.157,"text":"Then work out agreement, chance, kappa,"},{"start":498.157,"end":499.797,"text":"and agreement on keeps."},{"start":500.517,"end":502.537,"text":"Finally, pick one split."},{"start":503.177,"end":506.937,"text":"Is it ambiguity, a slip, or judgement, and"},{"start":506.937,"end":508.437,"text":"which fix does it need?"}]},"es-06-table-to-claim":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":0.78,"text":"Meet Maya."},{"start":1.36,"end":4.28,"text":"She's a made up doctoral student, asking"},{"start":4.28,"end":6.88,"text":"whether AI chatbot feedback improves"},{"start":6.88,"end":8.34,"text":"undergraduates' writing."},{"start":8.7,"end":11.24,"text":"She's found nine studies in an extraction"},{"start":11.24,"end":13.84,"text":"table, and now she needs a claim."},{"start":14.28,"end":17.48,"text":"Here's the one idea: build the claim from"},{"start":17.48,"end":20.7,"text":"the table, question by question, not study"},{"start":20.7,"end":21.24,"text":"by study."},{"start":21.6,"end":22.96,"text":"One boundary first."},{"start":23.56,"end":26.28,"text":"Meta-analysis averages every study's"},{"start":26.28,"end":28.56,"text":"effect size, meaning how big its result"},{"start":28.56,"end":31.52,"text":"is, into one number, and that's outside"},{"start":31.52,"end":32.48,"text":"this video's scope."},{"start":33.3,"end":35.6,"text":"Maya's first draft goes like this."},{"start":36.06,"end":38.16,"text":"Study one found a gain."},{"start":38.48,"end":40.92,"text":"Study two favoured the comparison."},{"start":41.78,"end":44.58,"text":"That's a summary, arranged study by study."},{"start":44.8,"end":47.68,"text":"A synthesis is arranged by question."},{"start":48.14,"end":50.04,"text":"Which way do the results point?"},{"start":50.28,"end":51.24,"text":"For whom?"},{"start":51.5,"end":53.46,"text":"And how sure are we?"},{"start":54.133,"end":56.133,"text":"Here's her table, all made up."},{"start":56.673,"end":58.653,"text":"The setting is either first year"},{"start":58.653,"end":61.653,"text":"composition or an upper level course, like"},{"start":61.653,"end":62.073,"text":"biology."},{"start":62.933,"end":64.173,"text":"Next is design."},{"start":64.753,"end":68.093,"text":"In a randomized trial, chance decides who"},{"start":68.093,"end":69.153,"text":"gets AI feedback."},{"start":69.773,"end":72.933,"text":"A quasi experiment compares groups that"},{"start":72.933,"end":73.733,"text":"weren't randomized."},{"start":74.413,"end":77.133,"text":"A pre post study measures one group,"},{"start":77.133,"end":78.893,"text":"before and after."},{"start":79.543,"end":82.443,"text":"Then there's size, n, the number of"},{"start":82.443,"end":82.803,"text":"students."},{"start":83.243,"end":85.823,"text":"Then the direction of the effect."},{"start":86.603,"end":89.523,"text":"Up means students wrote better with AI"},{"start":89.523,"end":93.003,"text":"feedback than a comparison group, or, in a"},{"start":93.003,"end":94.883,"text":"pre post study, than before."},{"start":95.803,"end":98.343,"text":"Down means the comparison group did"},{"start":98.343,"end":98.643,"text":"better."},{"start":99.253,"end":100.473,"text":"Then significance."},{"start":101.013,"end":104.373,"text":"A result is statistically significant when"},{"start":104.373,"end":106.473,"text":"it would be rare if there were no real"},{"start":106.473,"end":109.293,"text":"effect, p below point oh five."},{"start":109.913,"end":113.073,"text":"Last come appraisal concerns from her"},{"start":113.073,"end":116.153,"text":"critical appraisal, meaning how much the"},{"start":116.153,"end":118.573,"text":"design or conduct could have biased the"},{"start":118.573,"end":118.833,"text":"result."},{"start":119.233,"end":120.453,"text":"Take study five."},{"start":120.833,"end":123.773,"text":"It measured thirty students before and"},{"start":123.773,"end":126.373,"text":"after, and plenty else could explain that"},{"start":126.373,"end":128.333,"text":"gain, so it's high concern."},{"start":128.993,"end":131.273,"text":"Study three randomized two hundred twenty"},{"start":131.273,"end":133.413,"text":"students, so it's low."},{"start":134.167,"end":136.427,"text":"Now here's a tempting, conventional"},{"start":136.427,"end":138.787,"text":"shortcut called vote counting."},{"start":139.487,"end":142.847,"text":"Each study casts one vote, and you tally"},{"start":142.847,"end":143.007,"text":"them."},{"start":143.627,"end":145.707,"text":"Here, the vote is whether it was"},{"start":145.707,"end":146.147,"text":"significant."},{"start":147.027,"end":148.727,"text":"Only two of nine are."},{"start":149.127,"end":152.187,"text":"So does AI feedback mostly fail?"},{"start":158.137,"end":158.477,"text":"No."},{"start":158.777,"end":160.057,"text":"Look at the sizes."},{"start":160.397,"end":163.257,"text":"Five studies had thirty to sixty students,"},{"start":163.257,"end":165.057,"text":"and all five point up."},{"start":165.577,"end":168.377,"text":"Studies that small often can't reach"},{"start":168.377,"end":171.197,"text":"significance, because a real gain can look"},{"start":171.197,"end":171.777,"text":"like chance."},{"start":172.257,"end":175.877,"text":"So not significant doesn't mean no effect."},{"start":176.397,"end":179.297,"text":"The Cochrane Handbook, a standard guide"},{"start":179.297,"end":182.197,"text":"for systematic reviews, warns that this"},{"start":182.197,"end":184.477,"text":"kind of vote counting can lead to the"},{"start":184.477,"end":185.257,"text":"wrong conclusion."},{"start":186.247,"end":186.927,"text":"Here's the fix."},{"start":187.327,"end":190.687,"text":"Keep vote counting, but change the vote to"},{"start":190.687,"end":191.167,"text":"direction."},{"start":191.707,"end":194.947,"text":"Seven of nine point up, and two point"},{"start":194.947,"end":195.427,"text":"down."},{"start":195.787,"end":199.007,"text":"That answers our first question, which way"},{"start":199.007,"end":199.767,"text":"they point."},{"start":200.547,"end":204.767,"text":"SW i M, the reporting checklist for"},{"start":204.767,"end":207.707,"text":"synthesis without meta-analysis, names"},{"start":207.707,"end":208.347,"text":"this method."},{"start":208.727,"end":211.487,"text":"The Cochrane Handbook accepts it when"},{"start":211.487,"end":214.787,"text":"effect sizes can't be combined, but warns"},{"start":214.787,"end":218.027,"text":"that it ignores how big effects are, and"},{"start":218.027,"end":220.947,"text":"with few studies, uncertainty is large."},{"start":221.8,"end":223.02,"text":"Now the worked example."},{"start":223.44,"end":227.04,"text":"Step one, group the studies, meaning sort"},{"start":227.04,"end":228.94,"text":"them into sets that share a feature."},{"start":228.94,"end":233.04,"text":"SW i M's first item asks you to justify"},{"start":233.04,"end":233.7,"text":"that choice."},{"start":234.28,"end":237.24,"text":"Maya groups by setting, since a general"},{"start":237.24,"end":239.68,"text":"chatbot may handle disciplinary writing"},{"start":239.68,"end":240.46,"text":"less well."},{"start":240.88,"end":242,"text":"Watch the rows."},{"start":243.63,"end":246.37,"text":"No number changed, only the arrangement."},{"start":246.91,"end":248.77,"text":"Maya marks the groups."},{"start":249.58,"end":252.3,"text":"In first year composition, all five point"},{"start":252.3,"end":252.58,"text":"up."},{"start":252.99,"end":255.82,"text":"In upper level courses, only two of four"},{"start":255.82,"end":256.04,"text":"do."},{"start":256.56,"end":258.98,"text":"That's our second question, for whom."},{"start":259.36,"end":260.84,"text":"So is it the setting?"},{"start":261.04,"end":261.7,"text":"Maybe."},{"start":262.02,"end":264.52,"text":"But a pattern in one grouping can be"},{"start":264.52,"end":267.38,"text":"another in disguise, and non randomized"},{"start":267.38,"end":269.24,"text":"studies can overstate effects."},{"start":269.62,"end":272.84,"text":"So step two is to regroup by design."},{"start":273.26,"end":275.34,"text":"What do you think the randomized trials"},{"start":275.34,"end":275.88,"text":"will show?"},{"start":282.21,"end":283.27,"text":"Watch them regroup."},{"start":283.59,"end":287.25,"text":"The randomized trials split, two of four"},{"start":287.25,"end":287.53,"text":"up."},{"start":287.69,"end":290.97,"text":"The rest all point up, five of five."},{"start":291.27,"end":294.21,"text":"If you predicted a split, you were right."},{"start":294.63,"end":297.63,"text":"Those two down arrows are the same studies"},{"start":297.63,"end":300.27,"text":"both times, the upper level trials."},{"start":300.83,"end":303.53,"text":"So, setting or design?"},{"start":304.4,"end":304.96,"text":"Step three."},{"start":305.42,"end":307.9,"text":"Let's explain it with if, then statements."},{"start":308.4,"end":311.12,"text":"First, if it's the setting, the trials"},{"start":311.12,"end":313.44,"text":"show AI feedback helping first year"},{"start":313.44,"end":315.52,"text":"writers but not upper level ones."},{"start":316.02,"end":318.92,"text":"Second, if it's the design, the trials"},{"start":318.92,"end":320.72,"text":"shouldn't point up in either setting."},{"start":321.08,"end":323.78,"text":"Here's the trick: look where they predict"},{"start":323.78,"end":324.68,"text":"different things."},{"start":324.94,"end":328.06,"text":"The first year trials point up, so design"},{"start":328.06,"end":329.78,"text":"alone can't explain it."},{"start":330.45,"end":332.65,"text":"But in upper level courses, both"},{"start":332.65,"end":334.95,"text":"explanations predict the trials won't"},{"start":334.95,"end":336.63,"text":"point up, and they don't."},{"start":336.87,"end":339.83,"text":"So the table can't separate setting from"},{"start":339.83,"end":340.17,"text":"design."},{"start":340.94,"end":341.49,"text":"What would?"},{"start":341.93,"end":345.17,"text":"More upper level trials with low concerns."},{"start":345.69,"end":348.59,"text":"If they point down too, it's likely the"},{"start":348.59,"end":348.87,"text":"setting."},{"start":349.13,"end":352.07,"text":"If they point up, studies two and eight"},{"start":352.07,"end":353.21,"text":"may have been chance."},{"start":354.1,"end":357.22,"text":"Step four is writing the claim, and it has"},{"start":357.22,"end":358.02,"text":"three parts."},{"start":358.28,"end":360.86,"text":"The claim says what you conclude."},{"start":361.54,"end":364.3,"text":"The evidence names the cells behind it."},{"start":364.8,"end":368.16,"text":"The boundary says where it stops, and why."},{"start":369.06,"end":371.64,"text":"Maya re-sorts by setting first."},{"start":373.03,"end":374.15,"text":"Here's her claim."},{"start":374.35,"end":377.55,"text":"In first year composition, AI feedback"},{"start":377.55,"end":379.81,"text":"was associated with better writing."},{"start":380.37,"end":383.95,"text":"Causation is unproven, since three of five"},{"start":383.95,"end":386.73,"text":"weren't randomized, and she claims no"},{"start":386.73,"end":387.11,"text":"size."},{"start":387.53,"end":390.91,"text":"Her evidence is five of five pointing up,"},{"start":390.91,"end":394.09,"text":"including two randomized trials with low"},{"start":394.09,"end":394.55,"text":"concerns."},{"start":395.4,"end":398.17,"text":"That answers question three, how sure."},{"start":398.61,"end":401.95,"text":"Maya lets the low concern trials carry the"},{"start":401.95,"end":402.23,"text":"claim."},{"start":403.03,"end":405.67,"text":"The other three point the same way, but"},{"start":405.67,"end":406.97,"text":"couldn't carry it alone."},{"start":407.85,"end":408.95,"text":"Then the boundary."},{"start":409.21,"end":413.45,"text":"In upper level courses, results split, and"},{"start":413.45,"end":416.19,"text":"both low concern trials point down."},{"start":416.69,"end":418.19,"text":"Setting or design?"},{"start":418.61,"end":420.57,"text":"That needs more trials."},{"start":420.99,"end":422.49,"text":"Notice what that does."},{"start":422.69,"end":425.99,"text":"The disagreement stays in the paragraph,"},{"start":425.99,"end":429.63,"text":"named and still open, and nothing is"},{"start":429.63,"end":429.93,"text":"vague."},{"start":430.667,"end":431.187,"text":"Let's recap."},{"start":431.527,"end":434.987,"text":"First, answer three questions: which way,"},{"start":434.987,"end":436.507,"text":"for whom, how sure."},{"start":437.067,"end":439.687,"text":"Second, vote by direction, not"},{"start":439.687,"end":442.007,"text":"significance, and justify your grouping."},{"start":442.487,"end":445.487,"text":"Third, write the claim, evidence, and"},{"start":445.487,"end":446.807,"text":"boundary from the cells."},{"start":447.667,"end":448.547,"text":"Now try it yourself."},{"start":449.317,"end":451.487,"text":"Pick a published review, or your own"},{"start":451.487,"end":453.867,"text":"studies, with findings that appear to"},{"start":453.867,"end":454.247,"text":"disagree."},{"start":454.957,"end":457.847,"text":"Put them in one table, with population,"},{"start":457.847,"end":461.347,"text":"setting, design, outcome or theme, and"},{"start":461.347,"end":461.927,"text":"appraisal."},{"start":462.477,"end":464.827,"text":"Try two groupings, and write two"},{"start":464.827,"end":467.687,"text":"explanations, plus the evidence that would"},{"start":467.687,"end":468.267,"text":"tell them apart."},{"start":469.077,"end":471.907,"text":"Then draft one paragraph, with a claim,"},{"start":471.907,"end":474.727,"text":"evidence, and a boundary, all from the"},{"start":474.727,"end":474.967,"text":"cells."},{"start":474.967,"end":477.367,"text":"And ask yourself one question."},{"start":477.987,"end":480.307,"text":"Does your boundary keep the disagreement"},{"start":480.307,"end":482.247,"text":"open, without becoming vague?"}]},"es-09-synthesis-writing":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.08,"text":"Meet Maya again."},{"start":1.72,"end":4.3,"text":"She's the made up doctoral student who's"},{"start":4.3,"end":6.58,"text":"reviewing AI chatbot feedback on"},{"start":6.58,"end":7.68,"text":"undergraduates' writing."},{"start":8.18,"end":10.88,"text":"Earlier, she turned her table into one"},{"start":10.88,"end":11.8,"text":"careful claim."},{"start":12.28,"end":14.38,"text":"Today she writes up the review."},{"start":14.88,"end":15.9,"text":"Here's the idea."},{"start":16.62,"end":19.42,"text":"Organize it by meaning, add an insight of"},{"start":19.42,"end":22.08,"text":"your own, and keep that insight in the"},{"start":22.08,"end":24.8,"text":"Discussion, clearly apart from the"},{"start":24.8,"end":25.06,"text":"Results."},{"start":26,"end":27.1,"text":"Here's her first draft."},{"start":27.32,"end":30.2,"text":"Study A found students revised more,"},{"start":30.2,"end":31.8,"text":"mostly surface edits."},{"start":32.22,"end":34.32,"text":"Study B found the same."},{"start":34.68,"end":38.24,"text":"Study C found deeper revisions after a"},{"start":38.24,"end":38.92,"text":"class discussion."},{"start":39.3,"end":42.22,"text":"And on it goes, study by study."},{"start":42.99,"end":45.95,"text":"Notice that every sentence starts with an"},{"start":45.95,"end":46.21,"text":"author."},{"start":46.67,"end":47.97,"text":"That's a summary."},{"start":48.15,"end":51.29,"text":"A synthesis says what the studies show"},{"start":51.29,"end":51.79,"text":"together."},{"start":52.39,"end":54.85,"text":"Webster and Watson call her approach"},{"start":54.85,"end":58.41,"text":"author centric, and they say bluntly that"},{"start":58.41,"end":60.73,"text":"this method fails to synthesize the"},{"start":60.73,"end":61.01,"text":"literature."},{"start":61.33,"end":64.85,"text":"The fix is to make it concept centric."},{"start":65.45,"end":68.57,"text":"Each paragraph is about an idea, and the"},{"start":68.57,"end":70.05,"text":"authors go in parentheses."},{"start":71.167,"end":73.187,"text":"Step one is a concept matrix."},{"start":73.927,"end":76.547,"text":"Webster and Watson suggest filling one in"},{"start":76.547,"end":78.087,"text":"as you read each article."},{"start":78.967,"end":82.007,"text":"Maya puts the ideas down the side, and the"},{"start":82.007,"end":83.567,"text":"studies across the top."},{"start":83.867,"end":87.407,"text":"A concept here is an idea that more than"},{"start":87.407,"end":88.827,"text":"one study speaks to."},{"start":89.527,"end":91.147,"text":"Watch her read study A."},{"start":91.467,"end":94.587,"text":"It found more revising and mostly surface"},{"start":94.587,"end":98.007,"text":"edits, but no deeper revision, and no"},{"start":98.007,"end":98.867,"text":"class discussion."},{"start":99.327,"end":102.147,"text":"Then B, which looks a lot like A."},{"start":102.487,"end":105.167,"text":"Then C, where the class talked the"},{"start":105.167,"end":107.387,"text":"feedback through, and the revisions went"},{"start":107.387,"end":107.767,"text":"deeper."},{"start":108.107,"end":110.607,"text":"D and E fill in the same way."},{"start":111.333,"end":113.893,"text":"Step two is where the synthesis happens."},{"start":114.673,"end":117.773,"text":"Read across a row, not down a column."},{"start":118.333,"end":121.213,"text":"Four of five studies found students"},{"start":121.213,"end":122.153,"text":"revised more."},{"start":122.753,"end":124.213,"text":"That's the common meaning."},{"start":124.413,"end":127.653,"text":"And all three studies that coded the kind"},{"start":127.653,"end":130.733,"text":"of edit found mostly surface edits."},{"start":131.563,"end":133.643,"text":"In the third row, it splits."},{"start":134.563,"end":137.723,"text":"Two studies found deeper revision, and two"},{"start":137.723,"end":138.443,"text":"didn't."},{"start":138.903,"end":141.563,"text":"That's a tension, and you don't hide it."},{"start":141.903,"end":145.663,"text":"Now look at C and E, the two that found"},{"start":145.663,"end":146.523,"text":"deeper revision."},{"start":147.003,"end":149.143,"text":"What else do they have in common?"},{"start":155.063,"end":156.363,"text":"Look at the last row."},{"start":156.603,"end":159.483,"text":"C and E are the only studies where"},{"start":159.483,"end":161.683,"text":"students discussed the feedback in class."},{"start":162.163,"end":165.703,"text":"A and B had no discussion, and no deeper"},{"start":165.703,"end":166.063,"text":"revision."},{"start":166.683,"end":169.623,"text":"That's a pattern across studies, and you"},{"start":169.623,"end":171.723,"text":"can point to every cell behind it."},{"start":172.4,"end":174.66,"text":"Now let's rewrite the draft, live."},{"start":175.1,"end":177.9,"text":"Instead of starting with Study A, the"},{"start":177.9,"end":180.02,"text":"first sentence starts with the idea."},{"start":180.64,"end":183.08,"text":"In most studies, students did more"},{"start":183.08,"end":185.96,"text":"revising with AI feedback, and the"},{"start":185.96,"end":188.12,"text":"studies behind it drop into the"},{"start":188.12,"end":188.4,"text":"parentheses."},{"start":189.45,"end":191.67,"text":"The second row becomes the second"},{"start":191.67,"end":193.77,"text":"sentence, about surface edits."},{"start":193.95,"end":197.29,"text":"And the third keeps the split in plain"},{"start":197.29,"end":197.73,"text":"sight."},{"start":198.15,"end":202.59,"text":"Same studies, same facts, now organized by"},{"start":202.59,"end":202.93,"text":"meaning."},{"start":203.733,"end":206.613,"text":"Step three is the part most drafts skip."},{"start":207.093,"end":209.893,"text":"Notice that no single study compared"},{"start":209.893,"end":211.973,"text":"discussion with no discussion."},{"start":212.693,"end":216.173,"text":"Each one either had it or didn't, so the"},{"start":216.173,"end":218.913,"text":"connection only shows up when you read the"},{"start":218.913,"end":219.513,"text":"rows together."},{"start":220.153,"end":221.773,"text":"So Maya writes it down."},{"start":222.133,"end":225.913,"text":"Maybe AI feedback gets students revising,"},{"start":225.913,"end":228.713,"text":"and talking it through may be what takes"},{"start":228.713,"end":229.313,"text":"them deeper."},{"start":230.053,"end":233.073,"text":"Thomas and Harden describe a similar move"},{"start":233.073,"end":236.393,"text":"in thematic synthesis, where reviewers go"},{"start":236.393,"end":239.253,"text":"beyond the primary studies, the ones being"},{"start":239.253,"end":242.913,"text":"reviewed, toward new themes, and report"},{"start":242.913,"end":244.713,"text":"those themes as findings."},{"start":244.993,"end":247.233,"text":"But notice Maya's label."},{"start":247.473,"end":252.053,"text":"Hers is an untested guess about why, so a"},{"start":252.053,"end":254.073,"text":"safe default is the Discussion."},{"start":255.033,"end":257.413,"text":"Now step four, the line."},{"start":257.863,"end":260.873,"text":"On the left is Results, what the evidence"},{"start":260.873,"end":261.253,"text":"shows."},{"start":261.433,"end":264.853,"text":"On the right is Discussion, what Maya"},{"start":264.853,"end":267.233,"text":"thinks it means, and her insight goes"},{"start":267.233,"end":268.033,"text":"straight there."},{"start":268.553,"end":272.633,"text":"PRISMA twenty twenty, the reporting"},{"start":272.633,"end":275.293,"text":"guideline for systematic reviews, keeps"},{"start":275.293,"end":277.933,"text":"them apart too, with interpretation,"},{"start":277.933,"end":280.813,"text":"limitations, and implications in the"},{"start":280.813,"end":281.133,"text":"Discussion."},{"start":281.953,"end":282.973,"text":"Here's a quick test."},{"start":283.733,"end":285.713,"text":"If you can point to the studies behind"},{"start":285.713,"end":287.773,"text":"every word, it's a result."},{"start":288.273,"end":289.313,"text":"Try this one."},{"start":289.833,"end":292.933,"text":"Four of five studies found more revising,"},{"start":292.933,"end":294.513,"text":"and D didn't."},{"start":295.013,"end":296.313,"text":"Which side does it go on?"},{"start":302.183,"end":302.903,"text":"It's a result."},{"start":303.223,"end":306.223,"text":"You can point to a study for every part of"},{"start":306.223,"end":306.363,"text":"it."},{"start":306.663,"end":309.303,"text":"The surface edit sentence goes there too,"},{"start":309.303,"end":312.223,"text":"and so does the split on deeper revision."},{"start":313.083,"end":315.583,"text":"Maya's insight is already on the right,"},{"start":315.583,"end":317.443,"text":"because it's her explanation."},{"start":318.043,"end":320.383,"text":"What it would mean for teaching goes there"},{"start":320.383,"end":320.603,"text":"too."},{"start":321.483,"end":324.143,"text":"Instructors might pair AI feedback with a"},{"start":324.143,"end":324.863,"text":"short conversation."},{"start":325.443,"end":326.903,"text":"So does a limitation."},{"start":327.443,"end":331.383,"text":"C and E may differ in other ways too, so"},{"start":331.383,"end":334.143,"text":"this is a hypothesis to test, not a"},{"start":334.143,"end":334.403,"text":"finding."},{"start":335.133,"end":335.693,"text":"Last one."},{"start":336.233,"end":338.353,"text":"Maya wrote this about the pattern."},{"start":338.753,"end":341.773,"text":"Both studies with deeper revision built in"},{"start":341.773,"end":345.153,"text":"discussion, which shows discussion makes A"},{"start":345.153,"end":346.233,"text":"I feedback work."},{"start":346.953,"end":348.793,"text":"Something's leaking across the line."},{"start":348.953,"end":350.313,"text":"Can you spot where?"},{"start":356.213,"end":357.693,"text":"The first half is fine."},{"start":357.893,"end":361.193,"text":"You can point to C and E, so it's a"},{"start":361.193,"end":361.493,"text":"result."},{"start":361.893,"end":365.453,"text":"But no study tested whether discussion is"},{"start":365.453,"end":366.333,"text":"what makes it work."},{"start":366.793,"end":369.533,"text":"None compared discussion with no"},{"start":369.533,"end":369.913,"text":"discussion."},{"start":370.433,"end":373.893,"text":"It's Maya's explanation, stated as if it"},{"start":373.893,"end":374.393,"text":"were proven."},{"start":374.773,"end":376.673,"text":"So she cuts it there."},{"start":377.403,"end":380.563,"text":"The first half joins the Results, and the"},{"start":380.563,"end":383.263,"text":"overclaim crosses the line, where her"},{"start":383.263,"end":386.203,"text":"insight already says it honestly, as a"},{"start":386.203,"end":386.463,"text":"maybe."},{"start":387.233,"end":387.773,"text":"Let's recap."},{"start":388.153,"end":391.613,"text":"First, build the matrix, then organize by"},{"start":391.613,"end":394.413,"text":"meaning, one idea per paragraph, with the"},{"start":394.413,"end":395.433,"text":"studies in parentheses."},{"start":396.173,"end":398.893,"text":"Second, read across the rows for"},{"start":398.893,"end":402.133,"text":"agreement, tension, and patterns, then add"},{"start":402.133,"end":404.253,"text":"your insight, labelled as yours."},{"start":404.793,"end":406.533,"text":"Third, draw the line."},{"start":406.673,"end":409.213,"text":"The common meaning you can point to goes"},{"start":409.213,"end":411.973,"text":"in Results, your insight goes in"},{"start":411.973,"end":413.953,"text":"Discussion, and you catch the leaks."},{"start":414.8,"end":416.8,"text":"Now try it on a published review."},{"start":417.6,"end":419.88,"text":"Pick one in your area and copy three"},{"start":419.88,"end":421.62,"text":"sentences from its Results."},{"start":422.28,"end":424.56,"text":"Can you point to the studies behind every"},{"start":424.56,"end":424.88,"text":"word?"},{"start":425.28,"end":428.5,"text":"Then read its Discussion, and check that"},{"start":428.5,"end":431.72,"text":"any untested why reads as interpretation,"},{"start":431.72,"end":432.84,"text":"not as a finding."},{"start":433.48,"end":434.54,"text":"That's the line."},{"start":435.1,"end":438.56,"text":"And hunt for leaks, a word like shows or"},{"start":438.56,"end":440.76,"text":"proves that no study tested."},{"start":441.6,"end":443.14,"text":"Here's something to try this week."},{"start":443.56,"end":446.38,"text":"Take one paragraph of your own that walks"},{"start":446.38,"end":447.4,"text":"author by author."},{"start":447.72,"end":450.98,"text":"Build a small matrix, rewrite it one idea"},{"start":450.98,"end":453.94,"text":"per sentence, then mark each sentence R"},{"start":453.94,"end":456.08,"text":"for Results or D for Discussion."},{"start":456.58,"end":459.06,"text":"If an R sentence says something you can't"},{"start":459.06,"end":461.68,"text":"point to, you've found a leak, and you"},{"start":461.68,"end":462.62,"text":"know where it goes."}]},"es-07-prisma-flow-and-tool-audit":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.88,"text":"PRISMA twenty twenty recommends a flow"},{"start":2.88,"end":3.32,"text":"diagram."},{"start":3.98,"end":6.54,"text":"That's a chart of boxes and arrows showing"},{"start":6.54,"end":8.18,"text":"where each one dropped out."},{"start":8.76,"end":10.18,"text":"Here's the one idea."},{"start":10.94,"end":14.06,"text":"Every box is a count you can rebuild from"},{"start":14.06,"end":16.34,"text":"your logs, the spreadsheets you keep."},{"start":16.54,"end":19.82,"text":"To reconcile means making those counts"},{"start":19.82,"end":21.52,"text":"agree before you draw."},{"start":22.3,"end":25.58,"text":"This is Maya, a made up doctoral student."},{"start":26.06,"end":28.88,"text":"Her review asks whether AI chatbot"},{"start":28.88,"end":31.66,"text":"feedback helps undergraduates revise their"},{"start":31.66,"end":31.96,"text":"essays."},{"start":32.38,"end":35.66,"text":"It's a systematic review, so she reports"},{"start":35.66,"end":38.62,"text":"it with PRISMA twenty twenty, a twenty"},{"start":38.62,"end":41.3,"text":"seven item checklist that includes the"},{"start":41.3,"end":41.84,"text":"flow diagram."},{"start":42.83,"end":45.89,"text":"It tells you what to report, not how good"},{"start":45.89,"end":46.79,"text":"your review is."},{"start":47.07,"end":50.677,"text":"For a scoping review, she'd add PRISMA SC"},{"start":50.677,"end":52.15,"text":"R alongside it."},{"start":52.833,"end":54.553,"text":"First, here's the trick."},{"start":54.993,"end":57.453,"text":"PRISMA counts three different things."},{"start":58.003,"end":61.513,"text":"A record is one title and abstract in one"},{"start":61.513,"end":61.913,"text":"database."},{"start":62.233,"end":65.593,"text":"A report is a document, like an article."},{"start":65.753,"end":68.613,"text":"And a study is the research project"},{"start":68.613,"end":71.533,"text":"itself, with a defined group, an"},{"start":71.533,"end":73.393,"text":"intervention, and its outcomes."},{"start":74.333,"end":77.113,"text":"Take one made up classroom trial in Maya's"},{"start":77.113,"end":77.373,"text":"search."},{"start":77.873,"end":80.793,"text":"It produced two reports, an article and a"},{"start":80.793,"end":82.793,"text":"conference paper, and the databases"},{"start":82.793,"end":84.233,"text":"returned three records."},{"start":84.533,"end":87.133,"text":"That's the article in ERIC, the same"},{"start":87.133,"end":89.313,"text":"article in Scopus, and the conference"},{"start":89.313,"end":90.633,"text":"paper in PsycINFO."},{"start":90.853,"end":93.633,"text":"How many get removed as duplicates?"},{"start":99.543,"end":100.243,"text":"Just one."},{"start":100.623,"end":103.643,"text":"ERIC and Scopus point to the same article,"},{"start":103.643,"end":106.463,"text":"so Maya keeps one and removes the other."},{"start":106.683,"end":108.963,"text":"The conference paper is a different"},{"start":108.963,"end":110.303,"text":"report, so it stays."},{"start":110.843,"end":114.023,"text":"That's three records, two reports, one"},{"start":114.023,"end":114.403,"text":"study."},{"start":115.167,"end":118.027,"text":"Now let's build Maya's diagram, box by"},{"start":118.027,"end":119.447,"text":"box, from her logs."},{"start":120.087,"end":121.987,"text":"Step one is her search log."},{"start":122.587,"end":125.267,"text":"She exported one hundred forty two records"},{"start":125.267,"end":129.567,"text":"from ERIC, one eighteen from PsycINFO, and"},{"start":129.567,"end":131.087,"text":"ninety six from Scopus."},{"start":131.707,"end":133.867,"text":"Add them up and you get three hundred"},{"start":133.867,"end":134.547,"text":"fifty six."},{"start":135.417,"end":138.817,"text":"Okay, step two, deduplication."},{"start":139.077,"end":141.077,"text":"Eighty eight duplicates came out."},{"start":141.417,"end":144.877,"text":"No automation tool removed anything, so"},{"start":144.877,"end":146.177,"text":"that line says zero."},{"start":146.597,"end":148.197,"text":"Keep an eye on that zero."},{"start":149.257,"end":152.057,"text":"Three fifty six minus eighty eight leaves"},{"start":152.057,"end":153.477,"text":"two sixty eight to screen."},{"start":154.317,"end":157.157,"text":"Step three is screening, which means"},{"start":157.157,"end":159.637,"text":"reading the title and abstract, then"},{"start":159.637,"end":161.277,"text":"keeping or dropping it."},{"start":161.637,"end":165.467,"text":"Maya dropped two forty one, and two sixty"},{"start":165.467,"end":168.017,"text":"eight minus two forty one leaves twenty"},{"start":168.017,"end":168.297,"text":"seven."},{"start":168.937,"end":170.937,"text":"Notice the label changes here."},{"start":171.137,"end":174.817,"text":"These are reports now, documents she has"},{"start":174.817,"end":175.317,"text":"to find."},{"start":176.117,"end":179.137,"text":"In step four, retrieval, two couldn't be"},{"start":179.137,"end":181.957,"text":"found, so twenty five were read in full"},{"start":181.957,"end":183.057,"text":"against her criteria."},{"start":183.677,"end":185.857,"text":"That's what assessed for eligibility"},{"start":185.857,"end":186.477,"text":"means."},{"start":188.637,"end":191.797,"text":"Step five is the full text log, where"},{"start":191.797,"end":193.657,"text":"every exclusion gets a reason."},{"start":193.917,"end":197.557,"text":"Six had the wrong population, five had no"},{"start":197.557,"end":200.537,"text":"AI feedback, and four weren't empirical."},{"start":200.817,"end":203.117,"text":"That leaves ten reports included."},{"start":203.777,"end":204.997,"text":"How many studies is that?"},{"start":210.917,"end":211.477,"text":"It's eight."},{"start":211.877,"end":215.417,"text":"Step six, the linking table, matches each"},{"start":215.417,"end":216.757,"text":"report to its study."},{"start":217.057,"end":218.817,"text":"Remember our classroom trial?"},{"start":219.237,"end":222.777,"text":"It's S three, one study with two reports,"},{"start":222.777,"end":224.757,"text":"and S six is the same."},{"start":224.897,"end":228.557,"text":"Two extra reports, so ten minus two is"},{"start":228.557,"end":228.757,"text":"eight."},{"start":229.057,"end":230.537,"text":"Report both numbers."},{"start":231.3,"end":232.42,"text":"Rewind a week."},{"start":232.88,"end":235.9,"text":"Maya drew this draft before screening was"},{"start":235.9,"end":238.88,"text":"done, and it says two hundred thirty six"},{"start":238.88,"end":239.46,"text":"excluded."},{"start":240.14,"end":242.06,"text":"Let's audit it like a reader."},{"start":242.3,"end":245.7,"text":"At every subtraction, what comes in should"},{"start":245.7,"end":248.54,"text":"equal what goes out, or a note should"},{"start":248.54,"end":249.44,"text":"explain the gap."},{"start":249.94,"end":253.02,"text":"That's what reconcile means, making the"},{"start":253.02,"end":253.82,"text":"numbers agree."},{"start":254.18,"end":255.62,"text":"Which step fails?"},{"start":261.6,"end":264.6,"text":"Two sixty eight minus two thirty six is"},{"start":264.6,"end":267.59,"text":"thirty two, but the next box says twenty"},{"start":267.59,"end":267.82,"text":"seven."},{"start":268.2,"end":271.04,"text":"So one of these three boxes is wrong."},{"start":271.26,"end":274.52,"text":"To find out which, ask the screening log."},{"start":274.9,"end":277.86,"text":"Back then, five records were still marked"},{"start":277.86,"end":279.54,"text":"maybe, not yet decided."},{"start":279.86,"end":282.42,"text":"Later, all five were excluded."},{"start":283.27,"end":286.09,"text":"So the excluded box was just out of date."},{"start":286.59,"end":289.31,"text":"Two thirty six plus five is two forty one,"},{"start":289.31,"end":291.39,"text":"and every subtraction balances."},{"start":292.37,"end":294.61,"text":"Reconcile first, then draw."},{"start":295.4,"end":296.18,"text":"Here's the payoff."},{"start":296.72,"end":299.46,"text":"Every log you just saw can go into your"},{"start":299.46,"end":302.04,"text":"appendix, so a stranger could rebuild"},{"start":302.04,"end":302.82,"text":"every box."},{"start":303.54,"end":305.76,"text":"Add your search strings as you ran them,"},{"start":305.76,"end":308.6,"text":"your extraction and appraisal tables, and"},{"start":308.6,"end":311.76,"text":"a README saying which file rebuilds which"},{"start":311.76,"end":312.08,"text":"box."},{"start":313.933,"end":316.533,"text":"Remember that zero on the automation line?"},{"start":316.973,"end":318.633,"text":"Here's where it could change."},{"start":319.133,"end":321.913,"text":"Maya tries a made up AI screening"},{"start":321.913,"end":324.573,"text":"assistant that suggests include or"},{"start":324.573,"end":325.013,"text":"exclude."},{"start":325.673,"end":328.253,"text":"If you can't rebuild what it did, you"},{"start":328.253,"end":329.133,"text":"shouldn't trust it."},{"start":329.653,"end":332.113,"text":"So let's check it with five quick tests."},{"start":333.053,"end":335.653,"text":"Exportability is fine, since she can"},{"start":335.653,"end":336.693,"text":"export a spreadsheet."},{"start":337.733,"end":340.113,"text":"Auditability asks whether someone could"},{"start":340.113,"end":341.453,"text":"check later what it did."},{"start":341.853,"end":345.493,"text":"By itself, this tool fails, because it"},{"start":345.493,"end":348.353,"text":"doesn't record which AI version ran, or"},{"start":348.353,"end":348.693,"text":"when."},{"start":349.113,"end":352.993,"text":"So Maya keeps a use log, a diary of each"},{"start":352.993,"end":353.293,"text":"run."},{"start":353.753,"end":357.313,"text":"On privacy, she sends no confidential or"},{"start":357.313,"end":359.713,"text":"restricted content to an unapproved"},{"start":359.713,"end":359.933,"text":"service."},{"start":360.853,"end":363.613,"text":"Accessibility is still open, because she"},{"start":363.613,"end":365.173,"text":"hasn't tried a screen reader yet."},{"start":366.033,"end":366.953,"text":"Accuracy's next."},{"start":367.653,"end":369.873,"text":"On forty records Maya had already"},{"start":369.873,"end":373.093,"text":"screened, she kept six, and the tool"},{"start":373.093,"end":375.953,"text":"flagged five of them, plus four extras."},{"start":376.413,"end":379.513,"text":"But it missed one, and misses are"},{"start":379.513,"end":379.973,"text":"dangerous."},{"start":381.073,"end":384.493,"text":"If the tool had excluded on its own, that"},{"start":384.493,"end":386.533,"text":"eligible record would vanish."},{"start":387.133,"end":390.273,"text":"The automation box would show a count, but"},{"start":390.273,"end":391.673,"text":"not which one was lost."},{"start":392.393,"end":396.173,"text":"So, as a safe default, the tool may sort"},{"start":396.173,"end":399.633,"text":"but never exclude, and final eligibility"},{"start":399.633,"end":403.453,"text":"and interpretation stay human, so that"},{"start":403.453,"end":405.133,"text":"zero stays zero."},{"start":405.133,"end":408.953,"text":"If any tool does exclude, PRISMA's"},{"start":408.953,"end":411.813,"text":"explanation paper says to report how many."},{"start":412.543,"end":415.863,"text":"Review groups agree that AI needs human"},{"start":415.863,"end":416.363,"text":"oversight."},{"start":417.173,"end":419.983,"text":"When you write it up, name the tool, its"},{"start":419.983,"end":423.363,"text":"version, the date, the task, and how you"},{"start":423.363,"end":423.823,"text":"checked it."},{"start":424.533,"end":425.533,"text":"Let's pull it together."},{"start":425.993,"end":429.533,"text":"First, records, reports, and studies are"},{"start":429.533,"end":432.333,"text":"different units, so label every box."},{"start":432.773,"end":435.953,"text":"Second, every box is a count from a log,"},{"start":435.953,"end":438.913,"text":"so reconcile first and draw second."},{"start":439.433,"end":443.033,"text":"Third, a tool has to show its work, and"},{"start":443.033,"end":444.993,"text":"eligibility stays human."},{"start":445.733,"end":446.513,"text":"Try it yourself."},{"start":447.353,"end":449.893,"text":"Pick a published systematic review with a"},{"start":449.893,"end":450.933,"text":"PRISMA flow diagram."},{"start":451.753,"end":453.213,"text":"Check every subtraction."},{"start":453.753,"end":456.053,"text":"Does each arrow balance, or does a note"},{"start":456.053,"end":456.493,"text":"say why?"},{"start":456.933,"end":459.633,"text":"Then ask whether it reports both studies"},{"start":459.633,"end":463.853,"text":"and reports, and, if it used AI, how many"},{"start":463.853,"end":464.393,"text":"it excluded."},{"start":464.813,"end":467.713,"text":"Write down one gap, and the log that would"},{"start":467.713,"end":468.153,"text":"close it."},{"start":468.453,"end":470.333,"text":"Then turn to your own logs."},{"start":470.933,"end":473.133,"text":"Could a stranger rebuild every box from"},{"start":473.133,"end":473.293,"text":"them?"},{"start":473.693,"end":474.733,"text":"You've got this."}]},"es-02-review-autopsy":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.92,"text":"Let's do an autopsy on a review, which"},{"start":2.92,"end":5.1,"text":"means taking it apart to see what it"},{"start":5.1,"end":5.74,"text":"really did."},{"start":6.1,"end":8.72,"text":"Remember Maya, our made-up doctoral"},{"start":8.72,"end":9.22,"text":"student?"},{"start":9.54,"end":12.78,"text":"Her last review turned out narrative, but"},{"start":12.78,"end":15.4,"text":"this audit is built for systematic or"},{"start":15.4,"end":18.44,"text":"scoping reviews, so she's found a new one."},{"start":19.07,"end":20.57,"text":"Here's today's one idea."},{"start":21.37,"end":23.73,"text":"Every judgment in your audit needs"},{"start":23.73,"end":26.85,"text":"evidence from the review, a sentence you"},{"start":26.85,"end":29.63,"text":"can quote or a number you can recompute."},{"start":30.21,"end":33.37,"text":"Maya's sheet will hold one in every row."},{"start":34.13,"end":37.29,"text":"Here's an audit in five moves, each a row"},{"start":37.29,"end":38.33,"text":"on Maya's sheet."},{"start":38.99,"end":41.97,"text":"First, state the question or purpose and"},{"start":41.97,"end":43.77,"text":"identify its review family."},{"start":44.59,"end":47.53,"text":"Second, judge whether that family fits the"},{"start":47.53,"end":49.89,"text":"question, using evidence from the actual"},{"start":49.89,"end":50.27,"text":"methods."},{"start":50.73,"end":53.59,"text":"Third, audit transparency and"},{"start":53.59,"end":56.07,"text":"reproducibility across protocol or"},{"start":56.07,"end":58.53,"text":"registration, search documentation,"},{"start":58.53,"end":61.07,"text":"screening procedures, and flow reporting."},{"start":61.07,"end":65.25,"text":"Fourth, one consequential strength and one"},{"start":65.25,"end":66.49,"text":"consequential limitation."},{"start":67.29,"end":70.47,"text":"Fifth, one concrete improvement grounded"},{"start":70.47,"end":71.77,"text":"in published guidance."},{"start":73.77,"end":76.69,"text":"Think of this video as one worked audit."},{"start":77.07,"end":79.81,"text":"Yours will follow the same rows."},{"start":80.733,"end":83.233,"text":"Here's her new review, made up for this"},{"start":83.233,"end":86.493,"text":"video and called AI Chatbot Feedback on"},{"start":86.493,"end":88.973,"text":"Undergraduate Writing, A Scoping Review."},{"start":89.733,"end":92.313,"text":"Its purpose is to map which kinds of"},{"start":92.313,"end":94.553,"text":"chatbot feedback were studied, which"},{"start":94.553,"end":97.233,"text":"outcomes were measured, and where the gaps"},{"start":97.233,"end":97.513,"text":"are."},{"start":98.243,"end":98.843,"text":"First move."},{"start":99.103,"end":103.343,"text":"As a reminder, a review family is a type"},{"start":103.343,"end":106.143,"text":"of review defined by its purpose and"},{"start":106.143,"end":106.603,"text":"methods."},{"start":106.823,"end":110.323,"text":"A systematic review answers a focused"},{"start":110.323,"end":113.223,"text":"question, often, does this work?"},{"start":113.343,"end":116.923,"text":"A scoping review maps what's been studied,"},{"start":116.923,"end":118.103,"text":"and the gaps."},{"start":119.003,"end":122.763,"text":"Maya writes down the purpose, to map, and"},{"start":122.763,"end":125.083,"text":"the authors' own label, scoping."},{"start":125.9,"end":127.1,"text":"Now the second move."},{"start":127.52,"end":129.78,"text":"Does that family fit the question?"},{"start":130.3,"end":131.58,"text":"Open the methods."},{"start":132.28,"end":135,"text":"Studies were charted by feedback type,"},{"start":135,"end":136.72,"text":"outcome, and design."},{"start":137.52,"end":140.22,"text":"Charting just means sorting studies into a"},{"start":140.22,"end":142.86,"text":"table, which is what mapping looks like."},{"start":143.61,"end":145.15,"text":"But here's another sentence."},{"start":145.69,"end":148.27,"text":"Included studies were appraised with a"},{"start":148.27,"end":149.73,"text":"published quality checklist."},{"start":150.83,"end":153.55,"text":"Critical appraisal means judging how"},{"start":153.55,"end":155.45,"text":"trustworthy each study is."},{"start":156.15,"end":158.57,"text":"So is it systematic after all?"},{"start":159.29,"end":160.75,"text":"Pause and decide."},{"start":168.29,"end":168.61,"text":"No."},{"start":168.71,"end":171.51,"text":"In Munn and colleagues' guidance paper,"},{"start":171.51,"end":174.11,"text":"appraisal is mandatory in systematic"},{"start":174.11,"end":177.31,"text":"reviews, but optional in scoping reviews."},{"start":178.07,"end":181.37,"text":"Scoping authors may still appraise, so"},{"start":181.37,"end":183.49,"text":"appraisal alone can't decide."},{"start":184.35,"end":187.57,"text":"Charting suits a mapping question, and"},{"start":187.57,"end":190.15,"text":"Munn's scoping purposes include to"},{"start":190.15,"end":192.57,"text":"identify the types of available evidence"},{"start":192.57,"end":193.75,"text":"in a given field."},{"start":193.97,"end":197.65,"text":"So Maya writes that scoping fits the"},{"start":197.65,"end":197.93,"text":"question."},{"start":198.767,"end":200.707,"text":"The third move is the audit."},{"start":201.297,"end":204.627,"text":"A review is transparent when it tells you"},{"start":204.627,"end":208.067,"text":"what it did, and reproducible when someone"},{"start":208.067,"end":209.587,"text":"else could redo it."},{"start":210.067,"end":214.187,"text":"Maya checks four rows, marking each one"},{"start":214.187,"end":218.087,"text":"reported, partly, or not reported."},{"start":218.967,"end":222.787,"text":"Her yardstick is PRISMA twenty twenty, a"},{"start":222.787,"end":225.047,"text":"twenty-seven item reporting checklist."},{"start":226.007,"end":226.887,"text":"Here's the trick."},{"start":227.327,"end":231.267,"text":"It checks what was reported, not how well"},{"start":231.267,"end":232.007,"text":"it was done."},{"start":232.737,"end":235.497,"text":"First comes protocol or registration."},{"start":235.857,"end":239.637,"text":"A protocol is the review's plan, written"},{"start":239.637,"end":240.957,"text":"before it starts."},{"start":241.737,"end":244.557,"text":"Registration means posting the key parts"},{"start":244.557,"end":246.997,"text":"of that plan publicly, with a date."},{"start":247.727,"end":250.247,"text":"Maya searches the methods and finds"},{"start":250.247,"end":250.667,"text":"nothing."},{"start":251.167,"end":253.767,"text":"PRISMA asks authors to locate the"},{"start":253.767,"end":256.447,"text":"protocol, name the register, or say"},{"start":256.447,"end":257.027,"text":"there's none."},{"start":257.267,"end":258.887,"text":"So it's not reported."},{"start":259.207,"end":261.287,"text":"That doesn't mean it wasn't done."},{"start":261.507,"end":263.767,"text":"A reader just can't check."},{"start":264.497,"end":265.997,"text":"Next, the search."},{"start":266.657,"end":269.337,"text":"The methods give a count of databases and"},{"start":269.337,"end":272.757,"text":"a month, but no database names, and only"},{"start":272.757,"end":273.657,"text":"sample terms."},{"start":274.237,"end":277.417,"text":"PRISMA asks for the full search strategies"},{"start":277.417,"end":280.297,"text":"for all databases, so it's partly"},{"start":280.297,"end":280.657,"text":"reported."},{"start":281.567,"end":284.507,"text":"Then there's screening, deciding which"},{"start":284.507,"end":286.107,"text":"studies are in or out."},{"start":286.677,"end":289.747,"text":"Two reviewers independently screened every"},{"start":289.747,"end":292.247,"text":"title, abstract, and full text."},{"start":292.787,"end":296.607,"text":"That's exactly what PRISMA asks about, how"},{"start":296.607,"end":298.567,"text":"many reviewers, working independently."},{"start":298.567,"end":298.867,"text":"So it's reported."},{"start":300.433,"end":302.473,"text":"Last comes the flow diagram."},{"start":302.793,"end":306.213,"text":"A record is one title and abstract a"},{"start":306.213,"end":309.433,"text":"database returns, and the diagram counts"},{"start":309.433,"end":311.133,"text":"records at each step."},{"start":311.573,"end":312.893,"text":"Let's rebuild it."},{"start":313.613,"end":316.013,"text":"The search found one thousand two hundred"},{"start":316.013,"end":318.653,"text":"forty records, and three hundred eighty"},{"start":318.653,"end":319.933,"text":"were duplicates."},{"start":320.133,"end":322.513,"text":"So screening should start with one"},{"start":322.513,"end":324.94,"text":"thousand two hundred forty minus three"},{"start":324.94,"end":327.393,"text":"hundred eighty, which is eight hundred"},{"start":327.393,"end":327.693,"text":"sixty."},{"start":327.953,"end":329.413,"text":"And it does."},{"start":330.223,"end":332.943,"text":"Then seven hundred thirty were excluded at"},{"start":332.943,"end":333.283,"text":"screening."},{"start":334.003,"end":336.15,"text":"Eight hundred sixty minus seven hundred"},{"start":336.15,"end":339.183,"text":"thirty leaves one hundred thirty full"},{"start":339.183,"end":339.623,"text":"texts."},{"start":340.513,"end":341.113,"text":"Last step."},{"start":341.533,"end":344.753,"text":"Eighty-two full texts were excluded, and"},{"start":344.753,"end":347.213,"text":"the review reports fifty-two included."},{"start":347.593,"end":348.953,"text":"Does that add up?"},{"start":349.353,"end":350.813,"text":"Pause and check."},{"start":358.263,"end":358.983,"text":"It doesn't."},{"start":359.363,"end":361.783,"text":"One hundred thirty minus eighty-two is"},{"start":361.783,"end":362.203,"text":"forty-eight."},{"start":362.523,"end":364.703,"text":"So four appear from nowhere."},{"start":365.183,"end":368.203,"text":"Maybe they came from reference lists, but"},{"start":368.203,"end":369.603,"text":"the diagram never says."},{"start":370.223,"end":373.163,"text":"Maya marks it partly, noting the exact"},{"start":373.163,"end":373.603,"text":"numbers."},{"start":374.433,"end":377.913,"text":"Now the fourth move, one strength and one"},{"start":377.913,"end":378.453,"text":"limitation."},{"start":378.873,"end":382.013,"text":"A working test for consequential is this."},{"start":382.433,"end":385.373,"text":"Does it change how much you can trust the"},{"start":385.373,"end":385.693,"text":"conclusion?"},{"start":386.153,"end":387.933,"text":"Take this review's conclusion."},{"start":388.933,"end":390.813,"text":"The strength is the screening."},{"start":390.813,"end":394.453,"text":"PRISMA's explanation paper says double"},{"start":394.453,"end":397.273,"text":"screening may be more reliable than one"},{"start":397.273,"end":399.493,"text":"reviewer, at the cost of time."},{"start":399.573,"end":403.653,"text":"So inclusion rests less on one person."},{"start":403.913,"end":405.633,"text":"Maya adds it."},{"start":406.363,"end":409.323,"text":"The limitation hides in that headline,"},{"start":409.323,"end":411.983,"text":"chatbot feedback improves undergraduate"},{"start":411.983,"end":412.683,"text":"writing."},{"start":413.083,"end":415.123,"text":"That's a does-it-work claim."},{"start":415.463,"end":418.783,"text":"But in Munn's comparison, scoping reviews"},{"start":418.783,"end":421.083,"text":"don't synthesize study findings."},{"start":421.803,"end":424.243,"text":"So the headline outruns the question."},{"start":425.133,"end":428.453,"text":"The fifth move is one improvement, built"},{"start":428.453,"end":429.553,"text":"in three steps."},{"start":430.273,"end":433.213,"text":"She rewrites the headline as a map of what"},{"start":433.213,"end":436.513,"text":"was studied, turns the claim into an open"},{"start":436.513,"end":439.613,"text":"gap, and points to a follow-up systematic"},{"start":439.613,"end":443.133,"text":"review, one of Munn's scoping purposes."},{"start":444.153,"end":445.413,"text":"Here's Maya's argument."},{"start":446.153,"end":448.613,"text":"One decision, keeping the scoping"},{"start":448.613,"end":451.073,"text":"question, drives all three steps."},{"start":451.313,"end":454.313,"text":"The protocol and flow problems remain."},{"start":455.267,"end":456.927,"text":"So, three things to remember."},{"start":457.467,"end":461.207,"text":"First, every row needs a quote or a number"},{"start":461.207,"end":461.887,"text":"from the review."},{"start":463.087,"end":466.687,"text":"Second, silence means not reported, not"},{"start":466.687,"end":467.787,"text":"that it wasn't done."},{"start":468.187,"end":471.167,"text":"And third, recompute the flow numbers"},{"start":471.167,"end":471.707,"text":"yourself."},{"start":472.737,"end":474.137,"text":"Now try it yourself."},{"start":475.017,"end":477.477,"text":"Pick a published systematic or scoping"},{"start":477.477,"end":480.737,"text":"review on a topic you care about, and copy"},{"start":480.737,"end":483.457,"text":"Maya's nine rows onto a blank sheet."},{"start":484.227,"end":486.987,"text":"Fill every row with a sentence you can"},{"start":486.987,"end":490.087,"text":"quote or a number you can recompute, and"},{"start":490.087,"end":492.487,"text":"redo the flow arithmetic yourself."},{"start":493.347,"end":495.887,"text":"Then write down one strength, one"},{"start":495.887,"end":498.687,"text":"limitation, and one improvement you can"},{"start":498.687,"end":499.727,"text":"back with a source."},{"start":500.587,"end":502.447,"text":"And one question to reflect on."},{"start":502.747,"end":505.507,"text":"Does what you found change how much you"},{"start":505.507,"end":506.847,"text":"trust the review's conclusion?"},{"start":507.647,"end":510.787,"text":"You've watched Maya do it, so you can too."}]},"es-short-title-is-not-the-family":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.9,"text":"Here's a review that Maya, a made up"},{"start":2.9,"end":5.4,"text":"doctoral student, keeps coming back to."},{"start":5.58,"end":9.18,"text":"Its title says it's a systematic review of"},{"start":9.18,"end":11.24,"text":"chatbots in writing instruction."},{"start":12.19,"end":13.83,"text":"So that settles it, right?"},{"start":14.49,"end":15.37,"text":"Hold that thought."},{"start":16.07,"end":18.09,"text":"Review labels are slippery."},{"start":18.75,"end":21.55,"text":"Grant and Booth compared fourteen review"},{"start":21.55,"end":25.25,"text":"types and concluded that few have explicit"},{"start":25.25,"end":28.45,"text":"methods, and many aren't even mutually"},{"start":28.45,"end":29.07,"text":"exclusive."},{"start":30.02,"end":31.38,"text":"So don't trust the label."},{"start":31.98,"end":34.92,"text":"Look closely at four processes, they say."},{"start":35.36,"end":39.14,"text":"Search, appraisal, synthesis, and"},{"start":39.14,"end":39.54,"text":"analysis."},{"start":40.49,"end":41.21,"text":"Let's check it."},{"start":41.41,"end":44.75,"text":"A systematic review tries to find every"},{"start":44.75,"end":45.55,"text":"relevant study."},{"start":46.29,"end":49.29,"text":"This one used Google Scholar plus papers"},{"start":49.29,"end":52.21,"text":"the authors knew, and reports no search"},{"start":52.21,"end":55.19,"text":"strings, the exact words you'd type into a"},{"start":55.19,"end":55.45,"text":"database."},{"start":56.28,"end":59.92,"text":"A systematic review also appraises, or"},{"start":59.92,"end":62.38,"text":"judges, each study's quality."},{"start":63.05,"end":66.8,"text":"This one reports no appraisal, so that's a"},{"start":66.8,"end":67.64,"text":"second miss."},{"start":68.48,"end":69.2,"text":"Two misses."},{"start":69.5,"end":72.7,"text":"Before I show the last two rows, how many"},{"start":72.7,"end":74.08,"text":"of the four will fit?"},{"start":74.74,"end":76.22,"text":"Pause and guess."},{"start":81.27,"end":81.75,"text":"Just one."},{"start":82.13,"end":85.65,"text":"The synthesis goes study by study with a"},{"start":85.65,"end":87.97,"text":"summary table, typical of systematic"},{"start":87.97,"end":89.89,"text":"reviews, so that fits."},{"start":90.79,"end":93.67,"text":"But the analysis just argues for chatbots,"},{"start":93.67,"end":95.97,"text":"saying nothing about what's still unknown."},{"start":96.8,"end":98.65,"text":"One fit out of four."},{"start":99.4,"end":100.92,"text":"Now read its purpose."},{"start":101.2,"end":104.38,"text":"It aims to show teachers why chatbots"},{"start":104.38,"end":106.1,"text":"belong in every writing class."},{"start":106.74,"end":110.34,"text":"That's an argument, and arguing a view is"},{"start":110.34,"end":111.84,"text":"a narrative review's job."},{"start":112.71,"end":115.79,"text":"So the purpose, plus those three misses,"},{"start":115.79,"end":117.09,"text":"is your evidence."},{"start":117.43,"end":120.87,"text":"This is a narrative review wearing a"},{"start":120.87,"end":121.91,"text":"systematic label."},{"start":122.69,"end":123.85,"text":"That's not an insult."},{"start":124.55,"end":127.81,"text":"Narrative reviews have their own job, and"},{"start":127.81,"end":130.19,"text":"Greenhalgh and colleagues argue systematic"},{"start":130.19,"end":132.81,"text":"isn't the same as high quality."},{"start":133.71,"end":136.75,"text":"The real problem is claiming a method it"},{"start":136.75,"end":137.43,"text":"didn't use."},{"start":138.13,"end":140.99,"text":"So read past the title, and let the"},{"start":140.99,"end":142.79,"text":"methods have the final say."},{"start":143.61,"end":146.23,"text":"The full video walks through the whole"},{"start":146.23,"end":146.61,"text":"check."},{"start":147.23,"end":148.65,"text":"Here's one to think about."},{"start":149.11,"end":152.03,"text":"Does a review you've cited match its"},{"start":152.03,"end":152.33,"text":"label?"}]},"es-short-choosing-a-review":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.86,"text":"Meet Maya, a made up doctoral student"},{"start":2.86,"end":5.66,"text":"studying AI feedback on undergraduate"},{"start":5.66,"end":6.36,"text":"writing."},{"start":6.97,"end":8.74,"text":"Which review should she do?"},{"start":9,"end":11.86,"text":"It's tempting to pick the one that sounds"},{"start":11.86,"end":12.68,"text":"most rigorous."},{"start":13.62,"end":15.7,"text":"But start from the question instead,"},{"start":15.7,"end":17.74,"text":"because the question decides."},{"start":18.38,"end":20.36,"text":"So let's walk her down the path."},{"start":21.2,"end":23.82,"text":"If her question is whether it works, and"},{"start":23.82,"end":26.64,"text":"for whom, she wants a focused answer."},{"start":27.04,"end":29.64,"text":"That points to a systematic review."},{"start":30,"end":32.48,"text":"If she'd rather know what's been studied"},{"start":32.48,"end":36.28,"text":"and where the gaps are, that's a map, and"},{"start":36.28,"end":37.8,"text":"a scoping review fits."},{"start":38.72,"end":41.2,"text":"Scoping isn't the easy option, though."},{"start":41.36,"end":44.34,"text":"It still needs rigorous, transparent"},{"start":44.34,"end":45.08,"text":"methods."},{"start":45.99,"end":47.31,"text":"Three more forks."},{"start":47.43,"end":49.71,"text":"If she wants to argue a view from her"},{"start":49.71,"end":51.87,"text":"reading, that's a narrative review."},{"start":52.31,"end":54.31,"text":"What if she wants to interpret what"},{"start":54.31,"end":56.27,"text":"students said across interview studies?"},{"start":61.36,"end":63.44,"text":"It's a qualitative meta synthesis."},{"start":64.24,"end":67.1,"text":"And if she wants trials, surveys, and"},{"start":67.1,"end":69.92,"text":"theory in one picture, Whittemore and"},{"start":69.92,"end":72.94,"text":"Knafl describe an integrative review for"},{"start":72.94,"end":73.92,"text":"that kind of mix."},{"start":74.71,"end":77.59,"text":"Now say she's down the systematic path,"},{"start":77.59,"end":79.97,"text":"and her trials are similar enough in who"},{"start":79.97,"end":82.83,"text":"took part, what was compared, and what was"},{"start":82.83,"end":83.17,"text":"measured."},{"start":83.69,"end":86.59,"text":"Then a meta analysis could pool their"},{"start":86.59,"end":87.53,"text":"results statistically."},{"start":88.05,"end":90.43,"text":"And if she wanted to compare three or more"},{"start":90.43,"end":93.03,"text":"kinds of feedback, some never tested head"},{"start":93.03,"end":96.47,"text":"to head, that's a network meta analysis."},{"start":97.16,"end":99.26,"text":"Both of those usually build on a"},{"start":99.26,"end":102.22,"text":"systematic review, and both are beyond"},{"start":102.22,"end":102.82,"text":"this series."},{"start":103.42,"end":105.26,"text":"I'd only take them on with methods"},{"start":105.26,"end":107.94,"text":"training and, often, a statistician."},{"start":108.06,"end":111.98,"text":"This series stays qualitative or non meta"},{"start":111.98,"end":113.82,"text":"analytic, without pooling."},{"start":114.43,"end":116.81,"text":"So no family is automatically best."},{"start":117.21,"end":119.57,"text":"Grant and Booth's phrase for this is"},{"start":119.57,"end":120.77,"text":"fitness for purpose."},{"start":121.31,"end":124.57,"text":"Write your question first, then let it"},{"start":124.57,"end":125.17,"text":"pick the path."},{"start":125.99,"end":128.89,"text":"Watch Review Families and Six Ways to"},{"start":128.89,"end":130.71,"text":"Synthesize to go deeper."},{"start":131.19,"end":132.57,"text":"Here's one to think about."},{"start":133.05,"end":136.43,"text":"What do you need your own review to do?"}]},"es-short-high-agreement-low-kappa":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.3,"text":"Maya and Omar, two made up reviewers,"},{"start":3.3,"end":6.34,"text":"screen the same forty records without"},{"start":6.34,"end":6.84,"text":"talking."},{"start":7.64,"end":10.12,"text":"They agree on thirty seven of them."},{"start":10.42,"end":13.28,"text":"That's ninety two point five percent"},{"start":13.28,"end":13.78,"text":"agreement."},{"start":14.79,"end":18.257,"text":"But Cohen's kappa comes out at zero point"},{"start":18.257,"end":18.79,"text":"three six."},{"start":19.49,"end":20.57,"text":"What happened?"},{"start":21.36,"end":23.92,"text":"Kappa asks how much of that agreement"},{"start":23.92,"end":25.14,"text":"beats luck."},{"start":25.65,"end":28.08,"text":"If each kept records at their own rate,"},{"start":28.08,"end":30.48,"text":"but at random, they'd still match"},{"start":30.48,"end":30.9,"text":"sometimes."},{"start":31.7,"end":33.2,"text":"That's chance agreement."},{"start":34.24,"end":37.66,"text":"Kappa is the share of the room above luck"},{"start":37.66,"end":39,"text":"a pair reaches."},{"start":39.95,"end":40.69,"text":"Here's their table."},{"start":41.41,"end":45.97,"text":"Maya kept three, Omar kept two, and both"},{"start":45.97,"end":46.89,"text":"kept one."},{"start":47.53,"end":50.69,"text":"The other thirty six, they both excluded."},{"start":51.57,"end":54.75,"text":"When nearly everything is an exclude, two"},{"start":54.75,"end":57.63,"text":"people match a lot just by luck."},{"start":58.45,"end":61.31,"text":"Chance agreement, mostly both excluding by"},{"start":61.31,"end":63.894,"text":"luck, comes to zero point eight eight two"},{"start":63.894,"end":64.15,"text":"five."},{"start":64.83,"end":67.73,"text":"That leaves a sliver of room above luck,"},{"start":67.73,"end":70.59,"text":"and they filled just over a third, so"},{"start":70.59,"end":72.41,"text":"kappa's zero point three six."},{"start":73.49,"end":76.85,"text":"An Omar who excluded all forty unread"},{"start":76.85,"end":79.41,"text":"would still agree with Maya thirty seven"},{"start":79.41,"end":80.19,"text":"times."},{"start":81.07,"end":84.63,"text":"Now take another set where keeps were"},{"start":84.63,"end":85.11,"text":"common."},{"start":85.55,"end":88.677,"text":"The agreement's the same, ninety two point"},{"start":88.677,"end":89.53,"text":"five percent."},{"start":89.53,"end":91.97,"text":"Will kappa be the same?"},{"start":92.65,"end":93.95,"text":"Pause and guess."},{"start":98.97,"end":99.85,"text":"Not even close."},{"start":100.29,"end":103.046,"text":"Chance was only zero point six one two"},{"start":103.046,"end":106.83,"text":"five, so kappa was zero point eight one."},{"start":107.72,"end":110.96,"text":"The difference is prevalence, how common"},{"start":110.96,"end":111.7,"text":"keeps are."},{"start":112.12,"end":116.18,"text":"Rare keeps push chance up, and that drags"},{"start":116.18,"end":116.84,"text":"kappa down."},{"start":117.68,"end":120.32,"text":"Feinstein and Cicchetti called this high"},{"start":120.32,"end":122.4,"text":"agreement but low kappa."},{"start":123.1,"end":124.88,"text":"So kappa isn't broken."},{"start":125.18,"end":127.64,"text":"It's pointing at where the disagreement"},{"start":127.64,"end":129.86,"text":"lives, in the rare keeps."},{"start":130.46,"end":133.88,"text":"Only two of their five keep votes matched,"},{"start":133.88,"end":137.68,"text":"zero point four, while excludes matched at"},{"start":137.68,"end":138.7,"text":"zero point nine six."},{"start":139.78,"end":143.74,"text":"So report kappa, the table, and both of"},{"start":143.74,"end":144.3,"text":"those agreements."},{"start":145.21,"end":147.81,"text":"The full video shows the whole pilot."},{"start":147.81,"end":150.31,"text":"Think about your own screening."},{"start":150.31,"end":152.85,"text":"How rare are the keeps?"}]},"es-short-vote-counting":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.82,"text":"Maya, a made up doctoral student, has nine"},{"start":2.82,"end":5.38,"text":"made up studies on whether AI feedback"},{"start":5.38,"end":7.4,"text":"improves undergraduates' writing."},{"start":7.86,"end":10.74,"text":"A friend suggests a shortcut, vote"},{"start":10.74,"end":11.08,"text":"counting."},{"start":11.5,"end":14.76,"text":"Each study votes on one thing, was it"},{"start":14.76,"end":15.2,"text":"significant?"},{"start":15.78,"end":17.58,"text":"Only two of nine were."},{"start":18.06,"end":20.84,"text":"Does AI feedback mostly fail, then?"},{"start":21.36,"end":23.24,"text":"Pause and make your call."},{"start":29.14,"end":29.88,"text":"Not so fast."},{"start":30.58,"end":32.78,"text":"Significant means a result that would be"},{"start":32.78,"end":35.5,"text":"rare if there were no real effect, and"},{"start":35.5,"end":37.64,"text":"small studies often can't get there."},{"start":38,"end":41,"text":"Look at the five smallest, thirty to sixty"},{"start":41,"end":41.76,"text":"students each."},{"start":42.24,"end":45.04,"text":"Every one points up, and none is"},{"start":45.04,"end":45.44,"text":"significant."},{"start":46.08,"end":49.06,"text":"Not significant doesn't mean no effect."},{"start":49.93,"end":53.13,"text":"That's the trap the Cochrane Handbook, a"},{"start":53.13,"end":55.21,"text":"standard review guide, warns about."},{"start":55.87,"end":58.89,"text":"Counting votes by significance can lead to"},{"start":58.89,"end":61.33,"text":"the wrong conclusion, because small"},{"start":61.33,"end":63.47,"text":"studies that can't rule out an important"},{"start":63.47,"end":66.83,"text":"effect get counted as not showing benefit."},{"start":67.57,"end":70.73,"text":"So two of nine doesn't mean it mostly"},{"start":70.73,"end":71.21,"text":"fails."},{"start":71.98,"end":72.84,"text":"Change the vote."},{"start":73.12,"end":76.12,"text":"Don't ask if it's significant, ask which"},{"start":76.12,"end":76.88,"text":"way it points."},{"start":77.14,"end":79.92,"text":"Now it's seven up and two down."},{"start":79.92,"end":83.52,"text":"SW i M, a reporting guideline for"},{"start":83.52,"end":86.2,"text":"synthesis without meta-analysis, names"},{"start":86.2,"end":89.12,"text":"this method, and Cochrane accepts it when"},{"start":89.12,"end":90.82,"text":"effect sizes can't be combined."},{"start":91.71,"end":92.51,"text":"But keep it honest."},{"start":92.87,"end":95.95,"text":"It can't tell you how big the effect is."},{"start":96.21,"end":99.93,"text":"It ignores study size, and with only nine"},{"start":99.93,"end":102.71,"text":"studies, uncertainty is large."},{"start":103.15,"end":106.53,"text":"So seven of nine doesn't prove anything."},{"start":106.93,"end":110.05,"text":"It shows which way the evidence leans."},{"start":110.75,"end":112.77,"text":"Now the real synthesis starts."},{"start":113.59,"end":116.27,"text":"Maya groups them by setting and asks where"},{"start":116.27,"end":116.81,"text":"they split."},{"start":117.45,"end":120.31,"text":"In first year courses, all five point up."},{"start":120.45,"end":123.39,"text":"In upper level courses, two of four."},{"start":123.79,"end":126.31,"text":"Both down arrows are upper level"},{"start":126.31,"end":127.21,"text":"randomized trials."},{"start":127.87,"end":129.59,"text":"Setting, or design?"},{"start":130.48,"end":132.96,"text":"Count direction, then ask where they"},{"start":132.96,"end":133.24,"text":"split."},{"start":133.62,"end":136.5,"text":"The full Table to Claim video picks up"},{"start":136.5,"end":136.94,"text":"from there."},{"start":137.42,"end":138.36,"text":"Here's a question."},{"start":138.82,"end":141.1,"text":"Did the last review you read count"},{"start":141.1,"end":142.06,"text":"significant results?"}]},"es-short-prisma-is-not-quality":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.26,"text":"You've probably read a sentence like this."},{"start":2.72,"end":5.86,"text":"This review followed PRISMA, so you can"},{"start":5.86,"end":6.38,"text":"trust it."},{"start":6.6,"end":8.76,"text":"It sounds like a stamp of quality."},{"start":9.16,"end":10.12,"text":"But is it?"},{"start":10.6,"end":12.28,"text":"Pause and decide."},{"start":18.42,"end":21.8,"text":"It isn't, and PRISMA itself says so."},{"start":22.52,"end":24.68,"text":"PRISMA twenty twenty is a reporting"},{"start":24.68,"end":27.32,"text":"guideline, a twenty seven item checklist"},{"start":27.32,"end":29.24,"text":"of what to tell your readers."},{"start":29.54,"end":32.38,"text":"That includes your full search strategies,"},{"start":32.38,"end":35.48,"text":"how many people screened each record, and"},{"start":35.48,"end":38.06,"text":"how studies flowed from the search to the"},{"start":38.06,"end":38.68,"text":"final set."},{"start":39.45,"end":41.07,"text":"Here's the line that settles it."},{"start":41.55,"end":44.03,"text":"PRISMA twenty twenty, its authors write,"},{"start":44.03,"end":47.17,"text":"should not be used to assess the conduct"},{"start":47.17,"end":49.95,"text":"or methodological quality of systematic"},{"start":49.95,"end":50.45,"text":"reviews."},{"start":50.85,"end":53.57,"text":"Other tools exist for this purpose."},{"start":54.29,"end":56.21,"text":"There are really two separate questions"},{"start":56.21,"end":56.63,"text":"here."},{"start":56.93,"end":60.29,"text":"Was it reported, and was it done well?"},{"start":60.87,"end":63.87,"text":"A review could report, clearly and"},{"start":63.87,"end":66.73,"text":"completely, that it searched just one"},{"start":66.73,"end":67.15,"text":"database."},{"start":67.85,"end":71.01,"text":"That's great reporting of what's likely a"},{"start":71.01,"end":71.69,"text":"thin search."},{"start":72.07,"end":73.69,"text":"And it cuts the other way."},{"start":73.95,"end":77.47,"text":"If a review never mentions a protocol, its"},{"start":77.47,"end":80.15,"text":"plan written in advance, that doesn't"},{"start":80.15,"end":81.25,"text":"prove it had none."},{"start":81.51,"end":83.95,"text":"It just means you can't check."},{"start":84.71,"end":86.67,"text":"What's PRISMA good for, then?"},{"start":87.63,"end":88.43,"text":"Transparency."},{"start":88.59,"end":91.35,"text":"It's a yardstick for what a reader can"},{"start":91.35,"end":91.71,"text":"check."},{"start":91.95,"end":95.097,"text":"In a made up review Maya audited, a"},{"start":95.097,"end":97.35,"text":"hundred and thirty full texts were"},{"start":97.35,"end":100.99,"text":"assessed, eighty two were excluded, and"},{"start":100.99,"end":102.59,"text":"fifty two were included."},{"start":102.91,"end":105.41,"text":"But a hundred and thirty minus eighty two"},{"start":105.41,"end":106.57,"text":"is forty eight."},{"start":107.17,"end":111.07,"text":"Four full texts have no path, and the"},{"start":111.07,"end":113.75,"text":"diagram never says where they came from."},{"start":114.47,"end":116.21,"text":"So keep the two questions apart."},{"start":116.77,"end":117.59,"text":"Was it reported?"},{"start":118.01,"end":119.33,"text":"That's PRISMA's job."},{"start":119.63,"end":120.89,"text":"Was it done well?"},{"start":121.27,"end":123.67,"text":"That's appraisal, and it needs its own"},{"start":123.67,"end":123.99,"text":"tools."},{"start":124.63,"end":127.49,"text":"The full Review Autopsy video shows you"},{"start":127.49,"end":128.37,"text":"exactly how."},{"start":128.77,"end":131.11,"text":"Then try the reporting check yourself."},{"start":131.57,"end":134.27,"text":"Does a published review you've read report"},{"start":134.27,"end":137.37,"text":"its protocol, search, screening, and flow?"}]},"es-short-known-study-recall":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.62,"text":"Meet Maya, a made up doctoral student."},{"start":3.06,"end":5.8,"text":"She knows ten studies that definitely"},{"start":5.8,"end":7.02,"text":"belong in her review."},{"start":7.5,"end":10.26,"text":"She tests her search string, and it finds"},{"start":10.26,"end":11.12,"text":"all ten."},{"start":11.72,"end":12.86,"text":"Ten out of ten."},{"start":13.3,"end":14.7,"text":"So is her search done?"},{"start":15.2,"end":17.14,"text":"Take a guess before I answer."},{"start":23.433,"end":23.973,"text":"Not yet."},{"start":24.553,"end":26.673,"text":"Here's what recall really means."},{"start":26.993,"end":29.473,"text":"Of all the relevant studies out there,"},{"start":29.473,"end":31.793,"text":"it's the share your search finds."},{"start":32.213,"end":35.553,"text":"But nobody knows them all, so you estimate"},{"start":35.553,"end":37.313,"text":"it on the ones you do know."},{"start":37.953,"end":39.813,"text":"That's known-study recall."},{"start":40.273,"end":43.533,"text":"It's a small sample, not the whole field."},{"start":44.267,"end":45.407,"text":"Now watch this."},{"start":46.127,"end":48.487,"text":"Her broad string pulled in two hundred"},{"start":48.487,"end":51.127,"text":"thirty four records and found all ten."},{"start":51.327,"end":54.067,"text":"Her tighter string pulled in forty nine,"},{"start":54.067,"end":56.607,"text":"and it also found all ten."},{"start":57.067,"end":60.467,"text":"Same score, with almost five times the"},{"start":60.467,"end":60.807,"text":"screening."},{"start":61.367,"end":63.847,"text":"Ten out of ten couldn't tell those two"},{"start":63.847,"end":64.087,"text":"apart."},{"start":65,"end":66.3,"text":"And there's a deeper catch."},{"start":66.66,"end":70.24,"text":"A known study can only warn you about the"},{"start":70.24,"end":71.4,"text":"words it uses."},{"start":72.02,"end":74.84,"text":"Imagine a made up study that calls the"},{"start":74.84,"end":76.52,"text":"chatbot a writing assistant."},{"start":77.02,"end":79.78,"text":"If none of your ten known studies uses"},{"start":79.78,"end":83,"text":"that phrase, ten out of ten can't tell you"},{"start":83,"end":83.46,"text":"it's missing."},{"start":84.167,"end":86.327,"text":"So treat it the way the Cochrane Handbook"},{"start":86.327,"end":88.467,"text":"does, as one simple test."},{"start":88.787,"end":90.307,"text":"Then pair it with more."},{"start":90.727,"end":92.607,"text":"Cooper and colleagues' review of the"},{"start":92.607,"end":95.127,"text":"guidance suggests comprehensive searching"},{"start":95.127,"end":98.327,"text":"needs both databases and supplementary"},{"start":98.327,"end":100.627,"text":"methods, like chasing reference lists."},{"start":101.027,"end":103.487,"text":"And it's worth having someone peer review"},{"start":103.487,"end":103.987,"text":"your string."},{"start":104.8,"end":105.88,"text":"And write it all down."},{"start":106.24,"end":107.28,"text":"Try it yourself."},{"start":107.88,"end":110.48,"text":"Run your own string against studies you"},{"start":110.48,"end":113.62,"text":"already know belong, and log the count and"},{"start":113.62,"end":114.36,"text":"every revision."},{"start":114.78,"end":117.08,"text":"Ten out of ten is a good start."},{"start":117.4,"end":119.16,"text":"It's just not the finish line."},{"start":119.4,"end":122.38,"text":"The full video on search strings shows the"},{"start":122.38,"end":122.96,"text":"whole test."},{"start":123.58,"end":124.86,"text":"One last question."},{"start":125.3,"end":128.08,"text":"Which relevant studies might your words"},{"start":128.08,"end":128.36,"text":"miss?"}]},"es-short-ai-tools-dont-exclude":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.68,"text":"Maya's trying out a made up AI screening"},{"start":2.68,"end":3.1,"text":"assistant."},{"start":3.42,"end":6,"text":"It reads her titles and abstracts and"},{"start":6,"end":8.22,"text":"offers to throw out the irrelevant ones."},{"start":8.7,"end":10.66,"text":"That could save her hours."},{"start":11.36,"end":12.36,"text":"Can she let it?"},{"start":13,"end":16.08,"text":"First, she tests it on forty records she'd"},{"start":16.08,"end":17.46,"text":"already screened by hand."},{"start":17.78,"end":19.34,"text":"She'd included six."},{"start":19.76,"end":22.52,"text":"The tool flagged nine as relevant."},{"start":22.94,"end":24.58,"text":"Did it catch all six?"},{"start":25.02,"end":26,"text":"Take a guess."},{"start":32.4,"end":32.9,"text":"Not quite."},{"start":33.28,"end":36.88,"text":"It flagged five of those six, plus four"},{"start":36.88,"end":37.3,"text":"others."},{"start":37.48,"end":39.88,"text":"Which means one study she'd included"},{"start":39.88,"end":41.36,"text":"slipped past it."},{"start":42.033,"end":44.313,"text":"Now imagine she'd let it exclude."},{"start":45.103,"end":48.363,"text":"Every record it didn't flag would vanish,"},{"start":48.363,"end":49.453,"text":"including that one."},{"start":49.943,"end":53.133,"text":"The PRISMA flow diagram has a box for"},{"start":53.133,"end":55.633,"text":"records marked as ineligible by automation"},{"start":55.633,"end":58.513,"text":"tools, so she'd report a count."},{"start":59.163,"end":61.953,"text":"But a count can't tell anyone which study"},{"start":61.953,"end":62.473,"text":"was lost."},{"start":63.333,"end":65.153,"text":"So here's a safe default."},{"start":65.913,"end":69.233,"text":"Tools support workflow, but they don't own"},{"start":69.233,"end":69.733,"text":"the decision."},{"start":70.033,"end":73.173,"text":"A joint statement from Cochrane, Campbell,"},{"start":73.173,"end":75.373,"text":"and two other evidence synthesis groups"},{"start":75.373,"end":78.653,"text":"says AI and automation should be used"},{"start":78.653,"end":79.713,"text":"with human oversight."},{"start":79.993,"end":83.273,"text":"And it says the reviewers are ultimately"},{"start":83.273,"end":86.433,"text":"responsible for their synthesis, including"},{"start":86.433,"end":88.433,"text":"the decision to use AI."},{"start":89.333,"end":92.053,"text":"So under that default, here's its job."},{"start":92.613,"end":95.373,"text":"It sorts, and it never excludes."},{"start":95.533,"end":98.553,"text":"The nine records it flags go to the top of"},{"start":98.553,"end":101.693,"text":"the pile, and Maya still reads all forty,"},{"start":101.693,"end":103.873,"text":"so she catches the one it missed."},{"start":104.153,"end":108.053,"text":"She sees likely includes first, and every"},{"start":108.053,"end":110.113,"text":"eligibility call stays human."},{"start":110.867,"end":111.627,"text":"And write it down."},{"start":112.027,"end":115.787,"text":"That same statement says any use of AI or"},{"start":115.787,"end":117.987,"text":"automation that makes or suggests"},{"start":117.987,"end":120.427,"text":"judgments should be fully and"},{"start":120.427,"end":121.567,"text":"transparently reported."},{"start":122.547,"end":125.047,"text":"It asks you to report the tool's name and"},{"start":125.047,"end":128.027,"text":"version, the dates you used it, what you"},{"start":128.027,"end":130.667,"text":"used it for, and how you verified its"},{"start":130.667,"end":130.967,"text":"output."},{"start":131.627,"end":133.307,"text":"The full video goes further."},{"start":134.027,"end":134.947,"text":"So ask yourself."},{"start":135.707,"end":138.067,"text":"Which calls in your review should stay"},{"start":138.067,"end":138.447,"text":"human?"}]},"es-short-disclosing-ai-use":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.56,"text":"Meet Maya, a made up doctoral student."},{"start":2.98,"end":6.08,"text":"An AI tool helped her find synonyms and"},{"start":6.08,"end":7.3,"text":"poke holes in a draft."},{"start":8,"end":11,"text":"So what should she disclose, and how does"},{"start":11,"end":11.62,"text":"she say so?"},{"start":12.33,"end":15.25,"text":"One publishing guide, the ICMJE"},{"start":15.25,"end":17.51,"text":"recommendations, covers AI."},{"start":18.37,"end":21.33,"text":"Disclose which tool you used, and for what"},{"start":21.33,"end":21.69,"text":"purpose."},{"start":22.17,"end":24.97,"text":"Humans are ultimately responsible for"},{"start":24.97,"end":27.35,"text":"reviewing what it produces and making sure"},{"start":27.35,"end":28.07,"text":"it's accurate."},{"start":28.75,"end":31.49,"text":"And AI shouldn't be listed as an author."},{"start":32.18,"end":35.8,"text":"For a systematic or scoping review, is the"},{"start":35.8,"end":38.1,"text":"tool and its purpose enough?"},{"start":43.19,"end":43.69,"text":"Maybe not."},{"start":44.23,"end":46.51,"text":"Evidence synthesis groups have their own"},{"start":46.51,"end":49.17,"text":"joint statement, from Cochrane, Campbell,"},{"start":49.17,"end":50.19,"text":"and two other groups."},{"start":50.93,"end":54.09,"text":"Reviewers stay ultimately responsible, AI"},{"start":54.09,"end":57.09,"text":"should be used with human oversight, and"},{"start":57.09,"end":59.63,"text":"any use that makes or suggests judgments"},{"start":59.63,"end":61.99,"text":"should be fully and transparently"},{"start":61.99,"end":62.35,"text":"reported."},{"start":63.25,"end":66.31,"text":"Its Table 1 spells out what to report."},{"start":66.81,"end":69.53,"text":"That's the tool's name, version, and"},{"start":69.53,"end":73.17,"text":"dates, its purpose and validation, and the"},{"start":73.17,"end":75.69,"text":"steps you took to verify its output."},{"start":76.55,"end":78.05,"text":"Watch the disclosure grow."},{"start":78.7,"end":82.39,"text":"The ICMJE asks for the tool and its"},{"start":82.39,"end":82.77,"text":"purpose."},{"start":83.46,"end":86.25,"text":"For a review, the joint statement adds the"},{"start":86.25,"end":89.89,"text":"version, the dates, the validation, and"},{"start":89.89,"end":91.17,"text":"how you verified it."},{"start":91.87,"end":94.67,"text":"Here's a made up example for Maya's draft"},{"start":94.67,"end":95.15,"text":"critique."},{"start":95.29,"end":98.79,"text":"It names the tool, its version, and the"},{"start":98.79,"end":99.09,"text":"purpose."},{"start":99.96,"end":102.74,"text":"Her made up version for the synonyms in a"},{"start":102.74,"end":106.74,"text":"review is longer, but you can check every"},{"start":106.74,"end":107.12,"text":"part."},{"start":107.99,"end":110.89,"text":"Keep it short, specific, and checkable."},{"start":111.31,"end":113.97,"text":"The full video on the PRISMA flow and tool"},{"start":113.97,"end":115.27,"text":"audit goes further."},{"start":115.61,"end":117.29,"text":"So here's a question for you."},{"start":117.79,"end":119.91,"text":"What's allowed where your work will go?"},{"start":120.45,"end":122.87,"text":"Check your journal's, funder's, or"},{"start":122.87,"end":123.95,"text":"institution's policy."}]},"es-short-framework-pico":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.06,"text":"PICO is probably the best known question"},{"start":3.06,"end":3.64,"text":"framework."},{"start":4.34,"end":5.32,"text":"The real skill?"},{"start":6.02,"end":8.2,"text":"Knowing what each letter turns into."},{"start":8.96,"end":12.56,"text":"Meet Maya, our made up doctoral student,"},{"start":12.56,"end":15.06,"text":"studying AI chatbot feedback on"},{"start":15.06,"end":16.18,"text":"undergraduate writing."},{"start":16.967,"end":20.587,"text":"P is the population, the people a service"},{"start":20.587,"end":21.047,"text":"is for."},{"start":21.747,"end":25.247,"text":"I's the intervention, whatever service or"},{"start":25.247,"end":26.147,"text":"action they get."},{"start":26.687,"end":29.967,"text":"O's the outcome, how you'd measure whether"},{"start":29.967,"end":30.527,"text":"it worked."},{"start":31.147,"end":32.987,"text":"And C, the comparison?"},{"start":33.327,"end":34.847,"text":"That one's optional."},{"start":35.9,"end":37.2,"text":"It grew out of medicine."},{"start":37.46,"end":40.38,"text":"In nineteen ninety five, Richardson and"},{"start":40.38,"end":42.28,"text":"colleagues described the well built"},{"start":42.28,"end":43.26,"text":"clinical question."},{"start":43.88,"end":47.02,"text":"Booth calls its job making a vague need"},{"start":47.02,"end":47.86,"text":"answerable."},{"start":48.34,"end":51.26,"text":"PRISMA suggests it for effects questions,"},{"start":51.26,"end":54.7,"text":"and Cochrane finds it generally unsuitable"},{"start":54.7,"end":56,"text":"for qualitative ones."},{"start":58,"end":61.06,"text":"For Maya, that's undergraduates, chatbot"},{"start":61.06,"end":63.14,"text":"feedback on drafts, compared with"},{"start":63.14,"end":66.3,"text":"instructor, peer, or no feedback, and"},{"start":66.3,"end":67.96,"text":"writing quality on revision."},{"start":68.84,"end":71.14,"text":"Each element you keep becomes an"},{"start":71.14,"end":74.08,"text":"eligibility clause, a rule for which"},{"start":74.08,"end":75.02,"text":"studies get in."},{"start":75.9,"end":78.92,"text":"Undergraduates becomes students in credit"},{"start":78.92,"end":80.98,"text":"bearing courses, and so on."},{"start":81.85,"end":84.85,"text":"But only some become search blocks, the"},{"start":84.85,"end":86.43,"text":"words you type into a database."},{"start":87.27,"end":89.55,"text":"Population and intervention do."},{"start":90.31,"end":93.49,"text":"Comparison and outcome usually stay screen"},{"start":93.49,"end":96.43,"text":"only, checked by a person reading each"},{"start":96.43,"end":99.61,"text":"study, since Cochrane warns they may not"},{"start":99.61,"end":101.47,"text":"be well described in an abstract."},{"start":103.067,"end":105.047,"text":"Your turn, with a new question."},{"start":105.627,"end":108.707,"text":"It's Grade seven math students, worked"},{"start":108.707,"end":111.727,"text":"example videos, textbook practice, and"},{"start":111.727,"end":112.707,"text":"unit test scores."},{"start":113.207,"end":115.707,"text":"Which would you search, and which would"},{"start":115.707,"end":116.107,"text":"you screen?"},{"start":122.167,"end":124.187,"text":"Search the students and the videos."},{"start":124.807,"end":127.807,"text":"Screen the practice and the scores, by"},{"start":127.807,"end":128.247,"text":"default."},{"start":128.827,"end":131.227,"text":"Searching every letter is the classic"},{"start":131.227,"end":131.627,"text":"slip."},{"start":132.127,"end":135.547,"text":"Cochrane calls it usually unnecessary,"},{"start":135.547,"end":139.447,"text":"maybe even undesirable, and JBI notes"},{"start":139.447,"end":142.307,"text":"measured outcomes don't always reach the"},{"start":142.307,"end":142.607,"text":"abstract."},{"start":143.567,"end":144.307,"text":"Three things."},{"start":144.307,"end":148.487,"text":"PICO has four slots, and C's optional."},{"start":149.007,"end":151.587,"text":"Every element you keep becomes a clause."},{"start":151.587,"end":155.767,"text":"Of the four, usually only population and"},{"start":155.767,"end":157.207,"text":"intervention get searched."},{"start":157.207,"end":160.567,"text":"The full Question Frameworks video goes"},{"start":160.567,"end":160.947,"text":"deeper."}]},"es-short-framework-picos-picot-picoc":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.34,"text":"PICO has cousins."},{"start":1.34,"end":7,"text":"PICOS, PICOT, and PICOC each pin"},{"start":7,"end":8.4,"text":"down one more thing."},{"start":8.78,"end":11.42,"text":"When does that extra letter earn its"},{"start":11.42,"end":11.7,"text":"place?"},{"start":12.6,"end":14.16,"text":"S is study design."},{"start":14.88,"end":18.02,"text":"PRISMA's two thousand nine checklist asked"},{"start":18.02,"end":20.76,"text":"reviews to state their question including"},{"start":20.76,"end":22,"text":"study design."},{"start":22.84,"end":23.72,"text":"T is time."},{"start":24.64,"end":26.86,"text":"Riva and colleagues, writing for"},{"start":26.86,"end":29.9,"text":"clinicians planning studies, call it how"},{"start":29.9,"end":31.54,"text":"long data collection lasts."},{"start":32.1,"end":35.2,"text":"Others mean when the outcome's measured."},{"start":35.96,"end":39.88,"text":"The extra C is context, the setting an"},{"start":39.88,"end":41.32,"text":"intervention's delivered in."},{"start":41.42,"end":45.18,"text":"It traces to Petticrew and Roberts' social"},{"start":45.18,"end":46.32,"text":"science review guide."},{"start":47.133,"end":50.413,"text":"Added to Maya's question, each becomes an"},{"start":50.413,"end":53.373,"text":"eligibility clause, a rule for which"},{"start":53.373,"end":54.313,"text":"studies get in."},{"start":54.713,"end":58.053,"text":"Design becomes randomized or quasi"},{"start":58.053,"end":61.613,"text":"experimental studies, time becomes writing"},{"start":61.613,"end":64.593,"text":"measured in the same course term, and"},{"start":64.593,"end":67.473,"text":"context, first year composition classes"},{"start":67.473,"end":68.873,"text":"allowing AI."},{"start":69.773,"end":72.473,"text":"But do they become search blocks, the"},{"start":72.473,"end":73.933,"text":"words you type into a database?"},{"start":74.833,"end":77.413,"text":"Cochrane's typical search has a block for"},{"start":77.413,"end":81.473,"text":"study design, but not for time or context,"},{"start":81.473,"end":84.793,"text":"so screen those by default, checked by a"},{"start":84.793,"end":86.413,"text":"person reading each study."},{"start":87.167,"end":88.567,"text":"Is a design block free?"},{"start":89.137,"end":92.387,"text":"In one health review, a qualitative design"},{"start":92.387,"end":95.027,"text":"block cut the hits from twenty three"},{"start":95.027,"end":97.987,"text":"thousand seven hundred fifty eight to four"},{"start":97.987,"end":98.827,"text":"hundred forty eight."},{"start":99.227,"end":102.167,"text":"Were all eighteen relevant articles still"},{"start":102.167,"end":102.547,"text":"found?"},{"start":108.517,"end":109.977,"text":"No, only thirteen."},{"start":110.797,"end":113.857,"text":"Screening took hours instead of weeks, but"},{"start":113.857,"end":115.857,"text":"five relevant articles were lost."},{"start":116.137,"end":120.337,"text":"So the authors suggest PICOS only when"},{"start":120.337,"end":121.117,"text":"time is short."},{"start":121.457,"end":125.317,"text":"That block was qualitative, not a trial"},{"start":125.317,"end":128.217,"text":"filter like Maya's, and untested in"},{"start":128.217,"end":128.537,"text":"education."},{"start":129.017,"end":131.797,"text":"Test yours against studies you know"},{"start":131.797,"end":132.097,"text":"belong."},{"start":133.033,"end":133.913,"text":"One more trap."},{"start":134.233,"end":137.233,"text":"T isn't a publication date limit."},{"start":137.533,"end":140.533,"text":"If you need one, justify it separately."},{"start":143.633,"end":144.193,"text":"Three things."},{"start":144.473,"end":147.893,"text":"An extra letter almost always means an"},{"start":147.893,"end":148.673,"text":"extra clause."},{"start":149.153,"end":152.113,"text":"Only S sometimes earns a search block,"},{"start":152.113,"end":153.053,"text":"once tested."},{"start":153.233,"end":155.733,"text":"And T isn't a date limit."},{"start":156.053,"end":159.033,"text":"The full Question Frameworks video goes"},{"start":159.033,"end":159.373,"text":"further."}]},"es-short-framework-peco-peo":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":1.46,"text":"Maya's noticed something."},{"start":2.05,"end":4.98,"text":"In her courses, students already use"},{"start":4.98,"end":7.36,"text":"chatbots for writing, on their own."},{"start":7.74,"end":11.14,"text":"Nobody assigned that, so is it really"},{"start":11.14,"end":12.3,"text":"PICO's intervention?"},{"start":13.267,"end":13.747,"text":"Not really."},{"start":14.067,"end":15.187,"text":"It's an exposure."},{"start":15.767,"end":19.487,"text":"Booth puts it neatly: E replaces I where"},{"start":19.487,"end":22.287,"text":"an action is unintentional or unplanned."},{"start":22.847,"end":25.067,"text":"Morgan and colleagues call the pillars"},{"start":25.067,"end":28.947,"text":"population, exposure, comparator, and"},{"start":28.947,"end":29.287,"text":"outcomes."},{"start":30.137,"end":32.357,"text":"Morgan's group, working in environmental"},{"start":32.357,"end":35.337,"text":"health, found little guidance on writing"},{"start":35.337,"end":36.057,"text":"these questions."},{"start":36.057,"end":40.817,"text":"JBI's three letter cousin, PEO, is for"},{"start":40.817,"end":42.357,"text":"etiology and risk."},{"start":42.957,"end":45.937,"text":"Both ask about association, not whether"},{"start":45.937,"end":46.997,"text":"something works."},{"start":47.8,"end":49.06,"text":"Here's Maya's version."},{"start":49.69,"end":52.78,"text":"Among undergraduates, is frequent, self"},{"start":52.78,"end":55.76,"text":"initiated chatbot use, compared with rare"},{"start":55.76,"end":59.1,"text":"or no use, associated with writing self"},{"start":59.1,"end":59.78,"text":"efficacy?"},{"start":60.44,"end":62.62,"text":"Every element she keeps becomes an"},{"start":62.62,"end":65.04,"text":"eligibility clause, a rule for which"},{"start":65.04,"end":65.84,"text":"studies get in."},{"start":66.3,"end":69.84,"text":"P and E also become search blocks, words"},{"start":69.84,"end":70.94,"text":"typed into a database."},{"start":71.44,"end":75.26,"text":"C and O stay screen only, checked by a"},{"start":75.26,"end":78.12,"text":"person reading each study, since both can"},{"start":78.12,"end":79.54,"text":"be missing from abstracts."},{"start":80.19,"end":82.23,"text":"The comparator's the tricky part."},{"start":82.89,"end":85.69,"text":"Morgan's team gives five ways to set it."},{"start":86.05,"end":88.93,"text":"Maya takes the second, highest versus"},{"start":88.93,"end":91.93,"text":"lowest use, as her studies define it,"},{"start":91.93,"end":93.47,"text":"fixed in her protocol."},{"start":94.3,"end":95.62,"text":"One slip to avoid."},{"start":95.9,"end":99.62,"text":"Saying it improves self efficacy assumes"},{"start":99.62,"end":100.3,"text":"the answer."},{"start":100.3,"end":103.98,"text":"JBI wants outcomes stated non"},{"start":103.98,"end":107.26,"text":"directionally, so it's just writing self"},{"start":107.26,"end":108,"text":"efficacy."},{"start":108.7,"end":109.28,"text":"Your turn."},{"start":109.64,"end":112.86,"text":"Part time paid work over fifteen hours a"},{"start":112.86,"end":114.74,"text":"week, and course persistence."},{"start":115.64,"end":117.56,"text":"Intervention or exposure?"},{"start":123.66,"end":126.66,"text":"Exposure, since nobody assigned those"},{"start":126.66,"end":127.14,"text":"jobs."},{"start":127.32,"end":130.98,"text":"No comparison's named, so it's a PEO"},{"start":130.98,"end":131.38,"text":"question."},{"start":132.333,"end":133.073,"text":"Three things."},{"start":133.353,"end":135.873,"text":"If someone assigned it, it's an"},{"start":135.873,"end":138.873,"text":"intervention, and if students just do it,"},{"start":138.873,"end":139.993,"text":"it's an exposure."},{"start":140.413,"end":145.513,"text":"PECO names a comparison, PEO doesn't."},{"start":145.973,"end":149.353,"text":"And you'll get association, not proof that"},{"start":149.353,"end":150.013,"text":"something works."},{"start":150.873,"end":153.473,"text":"The full Question Frameworks video covers"},{"start":153.473,"end":156.533,"text":"them all, and the SPIDER short tackles"},{"start":156.533,"end":157.513,"text":"experience questions."}]},"es-short-framework-spider":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.74,"text":"Meet Omar, Maya's made up screening"},{"start":2.74,"end":3.2,"text":"partner."},{"start":3.42,"end":6.3,"text":"He asks how undergraduate writers"},{"start":6.3,"end":9.44,"text":"experience chatbot feedback on drafts."},{"start":9.72,"end":12.56,"text":"Nothing's compared and no outcome's"},{"start":12.56,"end":14.96,"text":"measured, so PICO doesn't fit."},{"start":15.667,"end":19.447,"text":"SPIDER comes from Cooke, Smith, and Booth,"},{"start":19.447,"end":21.907,"text":"who saw search tools focused on"},{"start":21.907,"end":24.427,"text":"quantitative research, and built an"},{"start":24.427,"end":27.287,"text":"alternative for qualitative and mixed"},{"start":27.287,"end":28.007,"text":"methods work."},{"start":28.867,"end":31.687,"text":"S is the sample, here undergraduate"},{"start":31.687,"end":32.387,"text":"writers."},{"start":32.387,"end":36.267,"text":"PI, the phenomenon of interest, is their"},{"start":36.267,"end":38.207,"text":"experience of chatbot feedback."},{"start":38.927,"end":41.567,"text":"D is design, like interviews."},{"start":42.167,"end":44.867,"text":"E is evaluation, like trust."},{"start":45.127,"end":49.147,"text":"And R is research type, qualitative or"},{"start":49.147,"end":49.747,"text":"mixed methods."},{"start":50.667,"end":52.867,"text":"Every letter he keeps becomes an"},{"start":52.867,"end":55.367,"text":"eligibility clause, a rule for which"},{"start":55.367,"end":56.187,"text":"studies get in."},{"start":56.767,"end":59.587,"text":"But which become search blocks, words"},{"start":59.587,"end":60.687,"text":"typed into a database?"},{"start":66.797,"end":68.677,"text":"Just the sample and the phenomenon."},{"start":68.937,"end":72.397,"text":"Design, evaluation, and research type stay"},{"start":72.397,"end":75.317,"text":"screen only, checked by a person reading"},{"start":75.317,"end":76.057,"text":"each study."},{"start":76.517,"end":78.577,"text":"That's a default you test."},{"start":79.467,"end":80.727,"text":"Why only two?"},{"start":80.727,"end":84.487,"text":"Methley's team ran one review three ways."},{"start":84.487,"end":87.127,"text":"PICO pulled twenty three thousand, seven"},{"start":87.127,"end":90.797,"text":"hundred fifty eight records, PICOS four"},{"start":90.797,"end":93.517,"text":"hundred forty eight, and SPIDER two"},{"start":93.517,"end":94.507,"text":"hundred thirty nine."},{"start":95.377,"end":96.637,"text":"Eighteen studies belonged."},{"start":96.637,"end":100.657,"text":"PICO found all of them, the other two"},{"start":100.657,"end":102.077,"text":"found thirteen each."},{"start":102.817,"end":105.657,"text":"SPIDER's precision was higher, but it"},{"start":105.657,"end":106.217,"text":"missed five."},{"start":107.157,"end":107.877,"text":"Here's the trap."},{"start":108.077,"end":111.597,"text":"In SPIDER's search, research type had to"},{"start":111.597,"end":113.757,"text":"match too, and the authors suspect"},{"start":113.757,"end":116.817,"text":"requiring qualitative plus a named method"},{"start":116.817,"end":118.237,"text":"was too restrictive."},{"start":118.757,"end":121.597,"text":"Some missed studies just said interviews."},{"start":122.577,"end":123.517,"text":"Two cautions."},{"start":123.837,"end":127.097,"text":"It's one health topic, untested in"},{"start":127.097,"end":129.977,"text":"education, and the tools used different"},{"start":129.977,"end":131.197,"text":"numbers of search blocks."},{"start":131.957,"end":135.137,"text":"Even SPIDER's authors say it needs testing"},{"start":135.137,"end":136.337,"text":"on more topics."},{"start":137.233,"end":138.613,"text":"So, three things."},{"start":139.353,"end":141.473,"text":"SPIDER's a good checklist for experience"},{"start":141.473,"end":141.973,"text":"questions."},{"start":143.013,"end":145.393,"text":"Search the sample and phenomenon, and"},{"start":145.393,"end":146.213,"text":"screen the rest."},{"start":146.613,"end":149.373,"text":"And test your search, because SPIDER"},{"start":149.373,"end":151.273,"text":"itself still needs testing."},{"start":152.113,"end":155.073,"text":"The Question Frameworks video goes deeper."},{"start":155.073,"end":159.553,"text":"PECO gets its own short, for exposure"},{"start":159.553,"end":160.073,"text":"questions."}]},"es-short-framework-pcc-pico":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.82,"text":"Before Maya tests whether chatbot feedback"},{"start":2.82,"end":5.58,"text":"works, she wants a map of what's been"},{"start":5.58,"end":5.98,"text":"studied."},{"start":6.42,"end":8.28,"text":"That's a scoping question."},{"start":8.76,"end":11.32,"text":"It's broader, and it can generate"},{"start":11.32,"end":11.88,"text":"hypotheses."},{"start":12.56,"end":15.86,"text":"For that, JBI suggests PCC."},{"start":18.233,"end":21.993,"text":"Population is who, with details like age."},{"start":22.833,"end":26.253,"text":"Concept is the core idea you're mapping, a"},{"start":26.253,"end":29.353,"text":"big bucket for interventions, phenomena,"},{"start":29.353,"end":30.393,"text":"even outcomes."},{"start":31.153,"end":34.653,"text":"Context could be a culture, place, or"},{"start":34.653,"end":34.973,"text":"setting."},{"start":35.7,"end":38.48,"text":"JBI's Munn and colleagues repeat that"},{"start":38.48,"end":41.28,"text":"advice, and a scoping map can include"},{"start":41.28,"end":43.74,"text":"theses, reports, even blogs."},{"start":44.667,"end":46.537,"text":"Let's build Maya's."},{"start":46.537,"end":48.707,"text":"Every element you keep becomes an"},{"start":48.707,"end":51.247,"text":"eligibility clause, a rule for which"},{"start":51.247,"end":52.107,"text":"studies get in."},{"start":52.667,"end":55.527,"text":"Population becomes undergraduate writers."},{"start":56.047,"end":59.607,"text":"Concept becomes any study or report on"},{"start":59.607,"end":60.567,"text":"chatbot feedback."},{"start":61.467,"end":64.707,"text":"Some also become search blocks, words you"},{"start":64.707,"end":65.647,"text":"type into a database."},{"start":66.647,"end":70.107,"text":"Population gives one, concept gives two."},{"start":70.877,"end":72.597,"text":"She leaves context open."},{"start":72.777,"end":75.837,"text":"That's allowed, since JBI says one"},{"start":75.837,"end":77.457,"text":"element may not be required."},{"start":78.333,"end":81.193,"text":"Now Omar asks how students experience"},{"start":81.193,"end":82.353,"text":"chatbot feedback."},{"start":83.043,"end":86.833,"text":"For qualitative reviews, JBI uses PICo"},{"start":86.833,"end":88.013,"text":"with a small o."},{"start":88.843,"end":91.673,"text":"Population, phenomenon of interest, and"},{"start":91.673,"end":94.393,"text":"context, but no outcome slot."},{"start":95.223,"end":96.843,"text":"He'd search the first two."},{"start":97.403,"end":99.743,"text":"His first context said undergraduate"},{"start":99.743,"end":103.523,"text":"writing courses, but JBI warns elements"},{"start":103.523,"end":106.943,"text":"shouldn't repeat each other, so he trims"},{"start":106.943,"end":106.983,"text":"it."},{"start":107.733,"end":108.353,"text":"Your turn."},{"start":108.753,"end":111.873,"text":"Should his context be a search block, or"},{"start":111.873,"end":114.333,"text":"screen only, where a person checks it"},{"start":114.333,"end":115.653,"text":"while reading each study?"},{"start":121.603,"end":124.823,"text":"Screen only is a good default, since"},{"start":124.823,"end":126.463,"text":"abstracts may not name settings"},{"start":126.463,"end":127.123,"text":"consistently."},{"start":127.603,"end":130.163,"text":"If they do, test it as a block."},{"start":130.953,"end":134.393,"text":"Honestly, I found no study testing either"},{"start":134.393,"end":135.813,"text":"framework for searching."},{"start":136.6,"end":137.28,"text":"Three things."},{"start":137.28,"end":141.66,"text":"PCC maps a field; the small o version"},{"start":141.66,"end":143.24,"text":"explores experiences."},{"start":144.38,"end":146.94,"text":"Every element you keep becomes a clause."},{"start":147.34,"end":150.76,"text":"Search people and concept, and usually"},{"start":150.76,"end":152.22,"text":"screen context."},{"start":153.15,"end":155.41,"text":"The full Question Frameworks video"},{"start":155.41,"end":159.01,"text":"compares them, and the SPIDER short covers"},{"start":159.01,"end":159.77,"text":"experiences."}]},"es-short-framework-spice-eclipse":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.18,"text":"Some questions aren't about a treatment."},{"start":2.56,"end":5.78,"text":"They're about a service, and whose view"},{"start":5.78,"end":6.3,"text":"counts."},{"start":7.46,"end":10.56,"text":"Say Maya's writing center adds a chatbot"},{"start":10.56,"end":11.96,"text":"for first pass feedback."},{"start":12.64,"end":14.56,"text":"Booth built SPICE for that."},{"start":15.333,"end":16.893,"text":"Setting asks where."},{"start":17.613,"end":19.913,"text":"Perspective asks for whom."},{"start":20.453,"end":22.633,"text":"Intervention asks what."},{"start":23.233,"end":26.273,"text":"Comparison asks, compared with what?"},{"start":26.883,"end":30.273,"text":"And evaluation asks, with what result?"},{"start":31.1,"end":34.64,"text":"He devised it for library work, not health"},{"start":34.64,"end":35,"text":"care."},{"start":35,"end":38.58,"text":"He split population into setting and"},{"start":38.58,"end":41.64,"text":"perspective, and swapped outcomes for"},{"start":41.64,"end":45.86,"text":"evaluation, covering outputs, impact, and"},{"start":45.86,"end":47.16,"text":"less tangible effects."},{"start":48.067,"end":49.407,"text":"Here's Maya's question."},{"start":50.147,"end":52.727,"text":"Every element you keep becomes an"},{"start":52.727,"end":55.747,"text":"eligibility clause, a rule for which"},{"start":55.747,"end":56.667,"text":"studies get in."},{"start":57.227,"end":58.807,"text":"Each letter gets one."},{"start":59.6,"end":62.68,"text":"Some also become search blocks, the words"},{"start":62.68,"end":63.86,"text":"you type into a database."},{"start":64.65,"end":67.84,"text":"The rest are screen only, checked by a"},{"start":67.84,"end":69.4,"text":"person reading each study."},{"start":70.03,"end":71.88,"text":"Which two would you search?"},{"start":77.85,"end":80.35,"text":"Setting and intervention make a good"},{"start":80.35,"end":83.11,"text":"default, since authors usually name them."},{"start":83.57,"end":85.67,"text":"The other three get screened."},{"start":85.79,"end":88.87,"text":"That's advice, not Booth's rule."},{"start":89.567,"end":90.267,"text":"Here's the trap."},{"start":90.827,"end":92.987,"text":"Perspective isn't just population."},{"start":93.467,"end":96.267,"text":"Booth says evaluation is usually"},{"start":96.267,"end":99.367,"text":"subjective, so name whose view counts."},{"start":100.233,"end":103.093,"text":"SPICE's sibling for policy requests is"},{"start":103.093,"end":103.493,"text":"ECLIPSE."},{"start":104.233,"end":106.773,"text":"Health policy librarians Wildridge and"},{"start":106.773,"end":110.353,"text":"Bell found PICO didn't fit, and by the"},{"start":110.353,"end":112.853,"text":"end of two thousand one, their earlier"},{"start":112.853,"end":115.073,"text":"CLIP had become ECLIPSE."},{"start":115.983,"end":120.143,"text":"Its first E, expectation, asks what the"},{"start":120.143,"end":121.243,"text":"information is for."},{"start":121.923,"end":125.943,"text":"Then come client group, location, impact,"},{"start":125.943,"end":127.823,"text":"professionals, and service."},{"start":128.483,"end":132.023,"text":"Of CLIP, they wrote not every element fits"},{"start":132.023,"end":135.123,"text":"every search, but consider each at the"},{"start":135.123,"end":135.403,"text":"start."},{"start":136.143,"end":138.763,"text":"Honestly, I couldn't find a study testing"},{"start":138.763,"end":142.043,"text":"either one, and Booth admits cynics may"},{"start":142.043,"end":144.023,"text":"see little reason for a separate variant."},{"start":144.867,"end":145.547,"text":"Three things."},{"start":146.327,"end":148.827,"text":"SPICE weighs a service through a"},{"start":148.827,"end":151.747,"text":"stakeholder's eyes, ECLIPSE handles"},{"start":151.747,"end":152.227,"text":"policy."},{"start":152.967,"end":155.447,"text":"Every element you keep becomes a clause."},{"start":156.307,"end":158.947,"text":"Search setting and intervention, and"},{"start":158.947,"end":160.527,"text":"usually screen the rest."},{"start":161.357,"end":163.617,"text":"The full Question Frameworks video"},{"start":163.617,"end":166.637,"text":"compares them, and another short adds"},{"start":166.637,"end":168.517,"text":"environment and time."}]},"es-short-framework-cimo":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.4,"text":"PICO asks whether something works."},{"start":3.38,"end":6.24,"text":"Maya's committee keeps asking how, and in"},{"start":6.24,"end":7.12,"text":"what circumstances."},{"start":7.72,"end":9.9,"text":"That's a question for CIMO."},{"start":11.833,"end":15.413,"text":"C is the context, the people, settings, or"},{"start":15.413,"end":16.553,"text":"systems being studied."},{"start":16.873,"end":20.073,"text":"I is the intervention, the thing whose"},{"start":20.073,"end":21.133,"text":"effects you're after."},{"start":21.633,"end":24.953,"text":"M, the mechanism, is what explains the"},{"start":24.953,"end":27.653,"text":"link to the outcome, and when it kicks in."},{"start":27.933,"end":32.033,"text":"And O covers the outcomes, intended and"},{"start":32.033,"end":32.573,"text":"unintended."},{"start":33.633,"end":35.053,"text":"It's from management research."},{"start":35.693,"end":39.073,"text":"Denyer, Tranfield, and van Aken used it"},{"start":39.073,"end":41.493,"text":"for design propositions, where an"},{"start":41.493,"end":44.253,"text":"intervention works through a mechanism to"},{"start":44.253,"end":45.153,"text":"give an outcome."},{"start":45.773,"end":49.373,"text":"Design means designing a fix here, not"},{"start":49.373,"end":50.153,"text":"study design."},{"start":50.753,"end":53.913,"text":"Later, drawing on Pawson, Denyer and"},{"start":53.913,"end":56.813,"text":"Tranfield reworked PICO into CIMO."},{"start":58.533,"end":59.813,"text":"Here's Maya's version."},{"start":60.363,"end":63.193,"text":"In big first year sections where feedback"},{"start":63.193,"end":66.733,"text":"comes too late, chatbot feedback plus a"},{"start":66.733,"end":69.373,"text":"short reflection task may prompt self"},{"start":69.373,"end":71.813,"text":"regulated revision, and more substantive"},{"start":71.813,"end":72.653,"text":"revisions."},{"start":73.5,"end":75.08,"text":"What does each letter turn into?"},{"start":75.88,"end":78.96,"text":"Context, intervention, and outcome become"},{"start":78.96,"end":81.72,"text":"eligibility clauses, rules for which"},{"start":81.72,"end":82.54,"text":"studies get in."},{"start":83.08,"end":85.58,"text":"The first two usually become search blocks"},{"start":85.58,"end":88.14,"text":"too, sets of synonyms you type into a"},{"start":88.14,"end":88.42,"text":"database."},{"start":89.12,"end":92.4,"text":"The outcome's usually screen only, checked"},{"start":92.4,"end":93.92,"text":"by whoever reads each study."},{"start":94.667,"end":95.267,"text":"And the mechanism?"},{"start":95.827,"end":98.807,"text":"Should self regulation go in her search?"},{"start":104.787,"end":106.847,"text":"Usually not, as a default."},{"start":107.647,"end":109.807,"text":"Mechanisms tend to be explained in full"},{"start":109.807,"end":113.267,"text":"texts, not named in abstracts, so she"},{"start":113.267,"end":114.987,"text":"reads for it and records it."},{"start":114.987,"end":117.927,"text":"Booth and Carroll found theory hides like"},{"start":117.927,"end":118.427,"text":"that too."},{"start":119.133,"end":121.773,"text":"Denyer warns against unfocused questions,"},{"start":121.773,"end":123.853,"text":"like what is known about leadership."},{"start":124.113,"end":127.413,"text":"You needn't use CIMO at all, but keep"},{"start":127.413,"end":129.573,"text":"your question clear and answerable."},{"start":129.673,"end":132.533,"text":"And honestly, we found no study testing"},{"start":132.533,"end":132.773,"text":"it."},{"start":133.4,"end":134.16,"text":"Three things."},{"start":134.56,"end":138.42,"text":"Use CIMO when how and where matter."},{"start":138.78,"end":142.4,"text":"Search context and intervention, screen"},{"start":142.4,"end":143.08,"text":"the outcome."},{"start":143.56,"end":145.14,"text":"Read for the mechanism."},{"start":145.56,"end":147.98,"text":"The full video has the rest."}]},"es-short-framework-perspectif-behemoth":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.34,"text":"Does it work isn't the only question."},{"start":2.86,"end":5.82,"text":"Maya's committee asks whose view counts,"},{"start":5.82,"end":8.7,"text":"where, and when, and which theories"},{"start":8.7,"end":9.58,"text":"explain it."},{"start":10.06,"end":12.02,"text":"Two Booth frameworks help."},{"start":12.867,"end":14.127,"text":"First, PerSPEcTiF."},{"start":14.707,"end":16.607,"text":"Booth's team checked thirty eight"},{"start":16.607,"end":19.607,"text":"frameworks for context, whose view counts,"},{"start":19.607,"end":22.227,"text":"time and place, and fit with qualitative"},{"start":22.227,"end":22.587,"text":"data."},{"start":23.047,"end":26.767,"text":"None had all four, so they built one for"},{"start":26.767,"end":28.867,"text":"qualitative reviews of complex"},{"start":28.867,"end":29.347,"text":"interventions."},{"start":30.467,"end":31.687,"text":"Whose view counts?"},{"start":32.047,"end":34.587,"text":"Writing instructors, in community"},{"start":34.587,"end":35.127,"text":"colleges."},{"start":35.467,"end":38.887,"text":"The phenomenon is how they adopt chatbot"},{"start":38.887,"end":42.327,"text":"feedback, under an AI policy that changed"},{"start":42.327,"end":43.147,"text":"mid year."},{"start":43.367,"end":45.907,"text":"She skips the optional comparison."},{"start":46.567,"end":50.127,"text":"Timing is the first semester, and findings"},{"start":50.127,"end":52.367,"text":"are perceptions and workload."},{"start":53.367,"end":56.447,"text":"Booth's team listed terms for most"},{"start":56.447,"end":56.867,"text":"letters."},{"start":57.407,"end":59.187,"text":"Should Maya search all seven?"},{"start":65.167,"end":65.447,"text":"No."},{"start":65.727,"end":68.747,"text":"Their table never says to combine all"},{"start":68.747,"end":72.527,"text":"seven, and every search block, synonyms a"},{"start":72.527,"end":75.067,"text":"study must match, can lose studies."},{"start":75.467,"end":78.447,"text":"So by default she searches the phenomenon"},{"start":78.447,"end":81.327,"text":"and setting, and the rest stay screen"},{"start":81.327,"end":83.167,"text":"only, checked while reading."},{"start":83.917,"end":86.697,"text":"Every letter she keeps becomes an"},{"start":86.697,"end":90.157,"text":"eligibility clause, a rule for who gets"},{"start":90.157,"end":93.057,"text":"in, like describing the AI policy."},{"start":93.933,"end":96.413,"text":"Now BeHEMoTh, for finding theory."},{"start":96.993,"end":100.133,"text":"Of thirty four reviews they checked, only"},{"start":100.133,"end":102.393,"text":"twelve said how they found theirs."},{"start":103.233,"end":106.793,"text":"Be is the behaviour, students' uptake of"},{"start":106.793,"end":107.153,"text":"feedback."},{"start":107.913,"end":112.093,"text":"H is the context, originally health, here"},{"start":112.093,"end":113.913,"text":"chatbot feedback on writing."},{"start":114.653,"end":117.733,"text":"Then come theory words, like model or"},{"start":117.733,"end":118.173,"text":"framework."},{"start":118.853,"end":120.993,"text":"E is for exclusions."},{"start":121.673,"end":122.053,"text":"Why?"},{"start":122.553,"end":126.033,"text":"Model often means a statistical model, and"},{"start":126.033,"end":128.273,"text":"in AI papers, the chatbot itself."},{"start":128.693,"end":132.613,"text":"So she searches behaviour, context, and"},{"start":132.613,"end":135.313,"text":"theory, minus exclusions."},{"start":136.033,"end":138.993,"text":"Keywords alone still miss theory, which"},{"start":138.993,"end":141.853,"text":"often isn't in titles and abstracts, so"},{"start":141.853,"end":144.313,"text":"the authors add citation searching."},{"start":144.573,"end":147.353,"text":"And we found neither formally evaluated."},{"start":149.933,"end":150.733,"text":"Three things."},{"start":151.433,"end":153.893,"text":"Reach for PerSPEcTiF when context,"},{"start":153.893,"end":156.893,"text":"timing, and whose view counts matter."},{"start":157.553,"end":159.933,"text":"Reach for BeHEMoTh when you need theory."},{"start":160.453,"end":162.913,"text":"Treat both as checklists first."},{"start":162.913,"end":165.533,"text":"The full video has the rest."}]},"cscl-who-learns-when-a-group-learns":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.04,"text":"Three made-up students crack a dice puzzle"},{"start":3.04,"end":4.3,"text":"together in a chat."},{"start":4.62,"end":7.86,"text":"The next day, only one of them does well"},{"start":7.86,"end":9.14,"text":"on a new one alone."},{"start":9.72,"end":12.7,"text":"So, did the group learn, or did one"},{"start":12.7,"end":13.14,"text":"person?"},{"start":13.833,"end":16.213,"text":"Researchers call this the unit of"},{"start":16.213,"end":19.113,"text":"analysis, meaning whose thinking or"},{"start":19.113,"end":20.753,"text":"learning you actually measure."},{"start":21.013,"end":24.133,"text":"And the disagreement isn't one famous"},{"start":24.133,"end":24.533,"text":"exchange."},{"start":24.953,"end":28.073,"text":"It's a tension in how papers measure"},{"start":28.073,"end":28.493,"text":"things."},{"start":29.4,"end":31.88,"text":"On one side is Gerry Stahl."},{"start":32.06,"end":36.82,"text":"In CSCL, he argues, it is not so much"},{"start":36.82,"end":39.34,"text":"the individual student who learns and"},{"start":39.34,"end":42.62,"text":"thinks, as it is the collaborative group."},{"start":43.42,"end":44.26,"text":"But he's careful."},{"start":44.6,"end":47.62,"text":"He calls it a methodological, rather than"},{"start":47.62,"end":48.74,"text":"ontological issue."},{"start":49.42,"end":52.42,"text":"It's about how to study groups, not a"},{"start":52.42,"end":54.68,"text":"claim that some kind of group mind exists."},{"start":55.67,"end":59.09,"text":"Thoughts hide in heads, but group thinking"},{"start":59.09,"end":62.27,"text":"has to be publicly visible, in the chat"},{"start":62.27,"end":64.15,"text":"and on the whiteboard."},{"start":64.933,"end":66.853,"text":"On the other side is the cognitive"},{"start":66.853,"end":69.913,"text":"tradition, much of it from Paul Kirschner"},{"start":69.913,"end":70.633,"text":"and colleagues."},{"start":71.563,"end":74.673,"text":"Their collective working memory, members"},{"start":74.673,"end":77.433,"text":"sharing a hard task across their working"},{"start":77.433,"end":80.653,"text":"memories, is strongly linked to group"},{"start":80.653,"end":81.113,"text":"cognition."},{"start":82.113,"end":84.793,"text":"But it has an important focus on the"},{"start":84.793,"end":87.053,"text":"learning of individuals in the group."},{"start":87.193,"end":91.273,"text":"On complex tasks, collaboration becomes a"},{"start":91.273,"end":94.613,"text":"scaffold, like a worked example, for each"},{"start":94.613,"end":95.573,"text":"person's learning."},{"start":96.333,"end":97.313,"text":"Back to our chat."},{"start":97.313,"end":100.333,"text":"Ana draws a half-wrong tree."},{"start":100.793,"end":103.293,"text":"Chloe asks why there are only six"},{"start":103.293,"end":103.793,"text":"branches."},{"start":104.273,"end":106.873,"text":"Then Ben types the key move."},{"start":107.673,"end":110.293,"text":"It's thirty-six, because order matters."},{"start":111.273,"end":113.093,"text":"The group's answer is right."},{"start":113.743,"end":116.593,"text":"But the next day, working alone, Ana"},{"start":116.593,"end":120.193,"text":"scores nine out of ten, Ben five, and"},{"start":120.193,"end":121.073,"text":"Chloe six."},{"start":121.633,"end":123.453,"text":"So, did this group learn?"},{"start":123.773,"end":124.853,"text":"Take a guess."},{"start":129.767,"end":132.447,"text":"Both sides are right, about different"},{"start":132.447,"end":132.907,"text":"things."},{"start":133.087,"end":136.607,"text":"On Stahl's reading, the group built an"},{"start":136.607,"end":138.507,"text":"answer none of them had alone."},{"start":138.787,"end":142.087,"text":"The uneven scores tell you about"},{"start":142.087,"end":142.527,"text":"individuals."},{"start":143.757,"end":146.817,"text":"So the fight is mostly not about the data."},{"start":147.057,"end":149.637,"text":"It's about which of those counts as"},{"start":149.637,"end":153.077,"text":"learning, and no experiment settles a"},{"start":153.077,"end":153.457,"text":"definition."},{"start":154.367,"end":156.887,"text":"A two thousand seven review by authors"},{"start":156.887,"end":160.167,"text":"from both camps says the dispute is no"},{"start":160.167,"end":162.587,"text":"longer about individual versus group."},{"start":163.047,"end":165.767,"text":"It's about how a person and the social"},{"start":165.767,"end":167.687,"text":"world around them fit together."},{"start":168.537,"end":172.257,"text":"Both sides keep the individual, and both"},{"start":172.257,"end":175.077,"text":"now ask for more than one level of"},{"start":175.077,"end":175.337,"text":"analysis."},{"start":176.457,"end":177.697,"text":"One thing is settled."},{"start":178.197,"end":180.857,"text":"Students in one group affect each other,"},{"start":180.857,"end":183.977,"text":"so their scores aren't independent, and"},{"start":183.977,"end":186.497,"text":"the analysis has to model that nesting,"},{"start":186.497,"end":188.997,"text":"for example with multilevel models."},{"start":189.937,"end":192.937,"text":"What's still open is which level comes"},{"start":192.937,"end":193.397,"text":"first."},{"start":193.677,"end":197.337,"text":"In two thousand seventeen, the editors of"},{"start":197.337,"end":200.637,"text":"the main CSCL journal listed the most"},{"start":200.637,"end":203.837,"text":"appropriate units of analysis as an open"},{"start":203.837,"end":204.237,"text":"question."},{"start":205.167,"end":208.367,"text":"So when you read a paper, ask three"},{"start":208.367,"end":208.847,"text":"things."},{"start":209.487,"end":213.487,"text":"Is the claim about a person, a group, or a"},{"start":213.487,"end":213.747,"text":"community?"},{"start":214.607,"end":217.627,"text":"Does the evidence live at that same level?"},{"start":217.807,"end":221.027,"text":"And did the analysis account for students"},{"start":221.027,"end":222.227,"text":"sitting in groups?"},{"start":222.957,"end":226.177,"text":"A group claim backed only by averaged"},{"start":226.177,"end":229.757,"text":"post-tests is a mismatch, and so is the"},{"start":229.757,"end":230.017,"text":"reverse."},{"start":230.867,"end":233.407,"text":"Here's the whole debate on one card."},{"start":234.967,"end":236.167,"text":"Here's one to think about."},{"start":236.687,"end":239.427,"text":"Picture the last group project you studied"},{"start":239.427,"end":239.927,"text":"or taught."},{"start":240.247,"end":242.947,"text":"What would you have to record to show that"},{"start":242.947,"end":245.287,"text":"the group learned, and not just its"},{"start":245.287,"end":245.587,"text":"members?"}]},"cscl-collaborative-cognitive-load":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":3.26,"text":"If one brain has a small working memory,"},{"start":3.26,"end":6.8,"text":"the space where you juggle new ideas, do"},{"start":6.8,"end":8.9,"text":"three brains have a bigger one?"},{"start":9.46,"end":12,"text":"That's the bet of collaborative cognitive"},{"start":12,"end":15.62,"text":"load theory, and it asks when a teacher"},{"start":15.62,"end":17.56,"text":"shouldn't use group work."},{"start":18.333,"end":20.433,"text":"There's no famous rebuttal here."},{"start":20.613,"end":23.933,"text":"The pushback comes from three places."},{"start":24.833,"end":27.373,"text":"In two thousand eighteen, Kirschner,"},{"start":27.373,"end":29.713,"text":"Sweller and colleagues turned about a"},{"start":29.713,"end":32.333,"text":"decade of work into a theory of groups."},{"start":32.973,"end":36.233,"text":"On a complex task, members spread the"},{"start":36.233,"end":38.653,"text":"pieces across several working memories."},{"start":39.533,"end":41.833,"text":"But coordinating costs effort."},{"start":41.833,"end":45.513,"text":"They call these transaction costs, and"},{"start":45.513,"end":46.733,"text":"they can annul the gain."},{"start":47.863,"end":51.403,"text":"So group work pays off only when the task"},{"start":51.403,"end":52.623,"text":"is complex enough."},{"start":52.983,"end":55.303,"text":"The paper ends bluntly."},{"start":55.783,"end":58.943,"text":"The decision could very well be to not use"},{"start":58.943,"end":59.983,"text":"collaborative learning."},{"start":60.767,"end":63.727,"text":"First, the journal's own editors called"},{"start":63.727,"end":66.887,"text":"the model strictly information processing,"},{"start":66.887,"end":69.267,"text":"learning as information moving through"},{"start":69.267,"end":69.567,"text":"memory."},{"start":70.127,"end":72.567,"text":"They saw no apparent epistemological"},{"start":72.567,"end":76.107,"text":"alignment with most CSCL theory,"},{"start":76.107,"end":78.987,"text":"meaning a different idea of what learning"},{"start":78.987,"end":79.667,"text":"even is."},{"start":79.847,"end":82.447,"text":"They still published it, and said"},{"start":82.447,"end":84.027,"text":"diversity is essential."},{"start":84.877,"end":86.877,"text":"Second, group-cognition researchers,"},{"start":86.877,"end":90.617,"text":"writing before CCLT, already treated"},{"start":90.617,"end":93.257,"text":"the group's talk as the learning itself,"},{"start":93.257,"end":95.177,"text":"not a cost on top of it."},{"start":95.777,"end":99.437,"text":"Third, experiments, some co-written by"},{"start":99.437,"end":100.077,"text":"Sweller himself."},{"start":100.357,"end":103.737,"text":"With worked examples, or when students"},{"start":103.737,"end":107.037,"text":"already knew enough, individuals beat"},{"start":107.037,"end":107.437,"text":"groups."},{"start":108.333,"end":110.033,"text":"Picture a made-up French class."},{"start":110.853,"end":114.653,"text":"Task A, memorizing fifty word pairs, is"},{"start":114.653,"end":114.993,"text":"simple."},{"start":115.693,"end":118.973,"text":"Task B, writing sentences with them, is"},{"start":118.973,"end":119.413,"text":"complex."},{"start":120.333,"end":123.993,"text":"On Task B, about a third of one triad's"},{"start":123.993,"end":127.553,"text":"chat is just who's typing, and the rest is"},{"start":127.553,"end":130.113,"text":"a fight over le chat versus la chat."},{"start":130.893,"end":133.933,"text":"So is that grammar fight overhead, or"},{"start":133.933,"end":134.553,"text":"learning?"},{"start":134.933,"end":135.853,"text":"Take a guess."},{"start":140.867,"end":143.807,"text":"By the theory's own rules, it depends what"},{"start":143.807,"end":144.587,"text":"the talk does."},{"start":145.327,"end":148.347,"text":"It's productive if it fixes understanding,"},{"start":148.347,"end":151.827,"text":"and extraneous, wasted load, if it spreads"},{"start":151.827,"end":152.267,"text":"errors."},{"start":152.627,"end":156.307,"text":"The group-cognition side says the fight is"},{"start":156.307,"end":159.747,"text":"the learning, and CCLT would call who's"},{"start":159.747,"end":161.507,"text":"typing pure overhead."},{"start":162.407,"end":164.767,"text":"So the split isn't about the data."},{"start":165.127,"end":168.607,"text":"It's whether cost is the right word for"},{"start":168.607,"end":168.907,"text":"talk."},{"start":169.767,"end":170.487,"text":"What's solid?"},{"start":170.707,"end":173.387,"text":"On average, collaboration in"},{"start":173.387,"end":175.087,"text":"computer-based settings helps."},{"start":175.307,"end":177.807,"text":"A meta-analysis of four hundred"},{"start":177.807,"end":180.847,"text":"twenty-five studies put its effect size on"},{"start":180.847,"end":183.307,"text":"knowledge at about zero point four two"},{"start":183.307,"end":184.987,"text":"standard deviations."},{"start":185.427,"end":189.267,"text":"But that's an average, not a test of the"},{"start":189.267,"end":189.967,"text":"theory's conditions."},{"start":191.037,"end":193.657,"text":"The complexity prediction held in an early"},{"start":193.657,"end":195.997,"text":"experiment, but it's shakier now."},{"start":196.177,"end":198.997,"text":"A two thousand twenty-six online study"},{"start":198.997,"end":201.177,"text":"found partly the opposite pattern."},{"start":201.337,"end":204.917,"text":"But its hard tasks didn't feel very hard,"},{"start":204.917,"end":207.537,"text":"and its sample was smaller than planned."},{"start":208.367,"end":211.307,"text":"Both sides agree collaboration isn't"},{"start":211.307,"end":214.327,"text":"automatically good, and process matters,"},{"start":214.327,"end":215.787,"text":"not just outcomes."},{"start":216.767,"end":218.027,"text":"So check three things."},{"start":218.247,"end":222.167,"text":"Was the task really complex, and how was"},{"start":222.167,"end":222.707,"text":"that checked?"},{"start":223.567,"end":226.867,"text":"Was the outcome a group product or a later"},{"start":226.867,"end":227.847,"text":"individual test?"},{"start":228.487,"end":232.247,"text":"In one study, experienced teams' edge over"},{"start":232.247,"end":234.847,"text":"new teams was gone after a week."},{"start":235.327,"end":238.267,"text":"And did they code the talk, or just"},{"start":238.267,"end":239.767,"text":"collect one effort rating?"},{"start":240.533,"end":243.073,"text":"Here's the whole debate on one card."},{"start":244.633,"end":245.753,"text":"Here's one to think about."},{"start":246.033,"end":249.013,"text":"In a group task you know, which part of"},{"start":249.013,"end":252.113,"text":"the talk was overhead, and which part was"},{"start":252.113,"end":252.993,"text":"the learning?"},{"start":252.993,"end":255.913,"text":"Would both camps draw that line in the"},{"start":255.913,"end":256.513,"text":"same place?"}]},"cscl-scripts-guidance-or-straitjacket":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0.03,"end":2.217,"text":"Here's a form with three boxes."},{"start":2.64,"end":5.32,"text":"Researchers call this a collaboration"},{"start":5.32,"end":5.814,"text":"script."},{"start":6.237,"end":9.271,"text":"Is it a ladder that helps a group argue,"},{"start":9.271,"end":9.976,"text":"or a cage?"},{"start":10.399,"end":13.574,"text":"Computer-supported collaborative learning,"},{"start":13.574,"end":16.607,"text":"CSCL for short, still argues about it."},{"start":18.087,"end":21.079,"text":"Picture a made-up ninth grade class"},{"start":21.079,"end":24.652,"text":"debating phones at lunch, boxes in every"},{"start":24.652,"end":25.068,"text":"post."},{"start":26.167,"end":29.351,"text":"Leo's on the debate team, and soon he's"},{"start":29.351,"end":32.232,"text":"typing see above into the because box."},{"start":34.067,"end":37.527,"text":"Jun rarely speaks up, but now he writes"},{"start":37.527,"end":39.752,"text":"his first counter-argument."},{"start":40.867,"end":43.482,"text":"Pierre Dillenbourg called this worry"},{"start":43.482,"end":45.955,"text":"over-scripting in two thousand two."},{"start":46.379,"end":49.559,"text":"In Wise and Schwarz's summary, scripts can"},{"start":49.559,"end":52.033,"text":"be demotivating, produce stilted"},{"start":52.033,"end":55.001,"text":"observance, or even deter students from"},{"start":55.001,"end":56.203,"text":"successful moves."},{"start":57.307,"end":61.14,"text":"Their Provocateur, a composite voice, asks"},{"start":61.14,"end":63.668,"text":"when negotiation and a class's"},{"start":63.668,"end":66.93,"text":"self-determination clash, which do we"},{"start":66.93,"end":67.827,"text":"value more?"},{"start":68.977,"end":71.969,"text":"Side B is the script theory of guidance,"},{"start":71.969,"end":73.917,"text":"from Fischer and colleagues."},{"start":74.335,"end":76.979,"text":"You already carry internal scripts,"},{"start":76.979,"end":80.11,"text":"know-how for collaborating, from the whole"},{"start":80.11,"end":81.919,"text":"task down to single moves."},{"start":82.867,"end":86.232,"text":"A good external script aims at the highest"},{"start":86.232,"end":89.597,"text":"level you can't manage alone, resting on"},{"start":89.597,"end":91.397,"text":"moves you already have."},{"start":93.327,"end":96.592,"text":"Over-scripting, then, isn't just too much"},{"start":96.592,"end":97.089,"text":"script."},{"start":97.515,"end":100.568,"text":"It's a script aimed at the wrong level for"},{"start":100.568,"end":101.491,"text":"this learner."},{"start":102.633,"end":105.79,"text":"Side A sees Leo's stilted compliance."},{"start":106.302,"end":109.885,"text":"Side B sees the wrong level for him, so"},{"start":109.885,"end":113.468,"text":"lift or fade his boxes, while Jun still"},{"start":113.468,"end":114.321,"text":"needs his."},{"start":115.383,"end":118.523,"text":"A third voice, Pierre Tchounikine, would"},{"start":118.523,"end":121.454,"text":"call see above Leo's appropriation of the"},{"start":121.454,"end":124.315,"text":"script, a clue to how he read the task."},{"start":125.51,"end":128.22,"text":"Now jump to week five, when the teacher"},{"start":128.22,"end":129.575,"text":"takes the boxes away."},{"start":129.962,"end":132.543,"text":"Will Jun keep writing counter-arguments?"},{"start":137.92,"end":140.617,"text":"Probably not, if they simply vanish."},{"start":141.043,"end":144.024,"text":"In Wecker and Fischer's twenty eleven lab"},{"start":144.024,"end":146.651,"text":"study, one session with university"},{"start":146.651,"end":149.419,"text":"students, fading alone wasn't enough."},{"start":149.845,"end":152.542,"text":"Fading plus a peer checking the steps"},{"start":152.542,"end":153.394,"text":"worked best."},{"start":154.367,"end":157.638,"text":"A twenty seventeen meta-analysis by Vogel,"},{"start":157.638,"end":160.692,"text":"which pools many studies, found a small"},{"start":160.692,"end":163.964,"text":"gain in subject knowledge, d of zero point"},{"start":163.964,"end":166.872,"text":"two zero, about a fifth of a standard"},{"start":166.872,"end":169.271,"text":"deviation, and a bigger one in"},{"start":169.271,"end":172.18,"text":"collaboration skills, zero point nine"},{"start":172.18,"end":175.306,"text":"five, or zero point six five without two"},{"start":175.306,"end":175.96,"text":"outliers."},{"start":176.877,"end":179.853,"text":"And it found no sign of over-scripting for"},{"start":179.853,"end":181.306,"text":"collaboration skills."},{"start":181.721,"end":184.559,"text":"But it couldn't confirm the theory's own"},{"start":184.559,"end":187.466,"text":"right level principle either, since few"},{"start":187.466,"end":190.165,"text":"studies measured what learners already"},{"start":190.165,"end":190.511,"text":"knew."},{"start":191.767,"end":194.775,"text":"A twenty twenty review by Radkowitsch"},{"start":194.775,"end":196.201,"text":"tested motivation."},{"start":196.676,"end":200.001,"text":"It found g of zero point one three, but"},{"start":200.001,"end":203.01,"text":"the range of plausible values crosses"},{"start":203.01,"end":206.415,"text":"zero, with nine effects, so no average"},{"start":206.415,"end":208.632,"text":"harm, not proven harmless."},{"start":209.757,"end":212.599,"text":"Both reviews share authors with the theory"},{"start":212.599,"end":213.062,"text":"itself."},{"start":213.458,"end":214.45,"text":"Worth noticing."},{"start":215.787,"end":217.096,"text":"Where do they meet?"},{"start":217.509,"end":220.679,"text":"Dillenbourg, with Tchounikine, wrote that"},{"start":220.679,"end":223.435,"text":"too rigid scripts spoil the richness of"},{"start":223.435,"end":226.053,"text":"collaborative interactions, and too"},{"start":226.053,"end":228.947,"text":"flexible ones fail to induce the targeted"},{"start":228.947,"end":229.843,"text":"interactions."},{"start":230.847,"end":234.243,"text":"The two sides also define over-scripting"},{"start":234.243,"end":237.97,"text":"differently, so one study can be read both"},{"start":237.97,"end":238.384,"text":"ways."},{"start":238.881,"end":242.029,"text":"And underneath, is agency a path to"},{"start":242.029,"end":244.68,"text":"learning, or a goal in itself?"},{"start":245.687,"end":249.012,"text":"When you read a scripts paper, ask three"},{"start":249.012,"end":249.553,"text":"things."},{"start":250.017,"end":252.415,"text":"Which outcome did they measure?"},{"start":252.879,"end":255.508,"text":"What level does the script aim at?"},{"start":255.972,"end":257.983,"text":"And does it fade or adapt?"},{"start":259.033,"end":260.152,"text":"So, to sum up."},{"start":260.571,"end":263.438,"text":"On average, scripts help a little with"},{"start":263.438,"end":265.955,"text":"content and more with collaborating."},{"start":266.374,"end":269.171,"text":"Over-scripting can mean too rigid, or"},{"start":269.171,"end":270.918,"text":"aimed at the wrong level."},{"start":271.338,"end":274.204,"text":"And how much agency is worth is a values"},{"start":274.204,"end":274.554,"text":"call."},{"start":275.64,"end":276.975,"text":"Here's a question."},{"start":277.42,"end":280.609,"text":"If a structure helps a quiet student speak"},{"start":280.609,"end":283.575,"text":"up but makes a confident one go through"},{"start":283.575,"end":287.06,"text":"the motions, when would you remove it, and"},{"start":287.06,"end":288.395,"text":"who should decide?"}]},"cscl-eight-provocations-for-cscl":{"language":"en","provenance":"Provided timed English captions (VTT)","cues":[{"start":0,"end":2.34,"text":"In twenty seventeen, a journal for"},{"start":2.34,"end":4.26,"text":"computer-supported collaborative learning,"},{"start":4.26,"end":7.98,"text":"CSCL, printed an argument between two"},{"start":7.98,"end":9.5,"text":"characters who don't exist."},{"start":10.14,"end":12.6,"text":"Who are they, and why invent them?"},{"start":13.3,"end":16.3,"text":"Alyssa Wise and Baruch Schwarz gathered"},{"start":16.3,"end":19.64,"text":"twenty three email responses from CSCL"},{"start":19.64,"end":22.36,"text":"researchers, plus two public conference"},{"start":22.36,"end":22.88,"text":"sessions."},{"start":23.65,"end":26.11,"text":"From those they wrote eight deliberately"},{"start":26.11,"end":29.11,"text":"extreme provocations, each a dialogue"},{"start":29.11,"end":31.63,"text":"between a Provocateur who wants to shake"},{"start":31.63,"end":34.71,"text":"the field up and a Conciliator who builds"},{"start":34.71,"end":35.59,"text":"on what works."},{"start":36.4,"end":38.62,"text":"Neither voice is a real person."},{"start":39.32,"end":42.36,"text":"They're composites, so no line belongs to"},{"start":42.36,"end":45.34,"text":"any one researcher, and the paper says it"},{"start":45.34,"end":48.78,"text":"plainly, there are no resolutions offered."},{"start":49.567,"end":50.967,"text":"Here are all eight."},{"start":51.647,"end":55.607,"text":"Six push the field to do more, and two ask"},{"start":55.607,"end":56.687,"text":"whether it should stop."},{"start":57.497,"end":60.497,"text":"Let's test three of them, numbers three,"},{"start":60.497,"end":63.537,"text":"six and eight, on a made-up eighth grade"},{"start":63.537,"end":66.717,"text":"class, Room twelve, using a chat and"},{"start":66.717,"end":69.217,"text":"dashboard tool called ThinkBoard."},{"start":69.8,"end":72.72,"text":"The team's press release calls Room twelve"},{"start":72.72,"end":74.84,"text":"a thriving learning community."},{"start":75.54,"end":78.32,"text":"Provocation three asks whether that's"},{"start":78.32,"end":81.28,"text":"shown, or just assumed, since"},{"start":81.28,"end":83.4,"text":"collaboration should be an empirical"},{"start":83.4,"end":85.8,"text":"matter, not an article of faith."},{"start":86.57,"end":89.29,"text":"By the Provocateur's yardstick, Room"},{"start":89.29,"end":92.05,"text":"twelve shares a culture, but nothing"},{"start":92.05,"end":94.01,"text":"carries over to next year's class."},{"start":94.39,"end":97.07,"text":"The Provocateur would call that community"},{"start":97.07,"end":100.43,"text":"pro tem, a community for the time being."},{"start":101.22,"end":103.42,"text":"The Conciliator pushes back."},{"start":103.62,"end":107.08,"text":"If every study must first prove that"},{"start":107.08,"end":110.56,"text":"community is present, that becomes the"},{"start":110.56,"end":112.36,"text":"entirety of our work."},{"start":113.1,"end":116.4,"text":"Provocation six makes analytics, tools"},{"start":116.4,"end":118.44,"text":"that turn traces of group work into"},{"start":118.44,"end":122.14,"text":"feedback, a top priority, since a system"},{"start":122.14,"end":124.44,"text":"doesn't need to be perfect to be useful."},{"start":125.12,"end":128.64,"text":"So ThinkBoard tells Group B, strong groups"},{"start":128.64,"end":130.44,"text":"write longer turns than you."},{"start":131.06,"end":133.44,"text":"Will Group B collaborate any better next"},{"start":133.44,"end":133.74,"text":"week?"},{"start":133.98,"end":135.06,"text":"Take a guess."},{"start":139.98,"end":140.7,"text":"Probably not."},{"start":141.06,"end":143.88,"text":"The Conciliator says you'd mostly just get"},{"start":143.88,"end":146.3,"text":"longer turns, because length is a"},{"start":146.3,"end":148.9,"text":"by-product of making a well-argued point,"},{"start":148.9,"end":150.42,"text":"not what causes it."},{"start":151.11,"end":154.15,"text":"In a later reply, Pierre Tchounikine went"},{"start":154.15,"end":154.61,"text":"further."},{"start":154.81,"end":158.23,"text":"He wrote that automated adaptation is"},{"start":158.23,"end":160.53,"text":"antinomical to an emancipatory"},{"start":160.53,"end":161.01,"text":"perspective."},{"start":161.49,"end":164.91,"text":"In plain words, a system that steers"},{"start":164.91,"end":167.89,"text":"learners for them works against freeing"},{"start":167.89,"end":169.49,"text":"learners to steer themselves."},{"start":170.533,"end":173.513,"text":"In June the researchers leave, and"},{"start":173.513,"end":175.133,"text":"ThinkBoard goes with them."},{"start":175.713,"end":178.493,"text":"Provocation eight says the field should"},{"start":178.493,"end":181.853,"text":"admit it no longer aims at educational"},{"start":181.853,"end":182.553,"text":"change."},{"start":183.453,"end":187.433,"text":"The Conciliator says, you go too far, and"},{"start":187.433,"end":190.473,"text":"later concedes impact is very small so"},{"start":190.473,"end":194.273,"text":"far, but says that means realigning the"},{"start":194.273,"end":197.573,"text":"effort, not abandoning the field's reason"},{"start":197.573,"end":198.133,"text":"for being."},{"start":198.813,"end":200.093,"text":"Then, a twist."},{"start":200.723,"end":202.673,"text":"The Provocateur ends up calling"},{"start":202.673,"end":204.953,"text":"partnership work with schools worth it,"},{"start":204.953,"end":208.473,"text":"and a twenty eighteen reply by Hod, Sagy"},{"start":208.473,"end":210.653,"text":"and Kali backs the Conciliator."},{"start":211.163,"end":213.573,"text":"For Room twelve, that would mean building"},{"start":213.573,"end":216.373,"text":"ThinkBoard with the school from the start."},{"start":217.167,"end":219.627,"text":"Of the replies we checked, only"},{"start":219.627,"end":223.587,"text":"provocation two, scripts versus agency,"},{"start":223.587,"end":226.007,"text":"got a direct quantitative test."},{"start":226.347,"end":229.987,"text":"The rest live on in short replies and"},{"start":229.987,"end":230.547,"text":"agendas."},{"start":231.347,"end":234.947,"text":"When you read a CSCL paper now, ask"},{"start":234.947,"end":237.767,"text":"which provocation it quietly takes a side"},{"start":237.767,"end":240.607,"text":"on, and whether each claim is about"},{"start":240.607,"end":243.547,"text":"evidence, definitions, or values."},{"start":244.467,"end":245.807,"text":"So, to sum up."},{"start":245.867,"end":248.787,"text":"The paper gives us eight provocations from"},{"start":248.787,"end":251.627,"text":"two invented voices, and it never picks a"},{"start":251.627,"end":251.827,"text":"winner."},{"start":252.187,"end":254.747,"text":"Some of the fights are about evidence,"},{"start":254.747,"end":257.787,"text":"some about definitions, and some are about"},{"start":257.787,"end":259.567,"text":"what the field is even for."},{"start":260.4,"end":261.46,"text":"Here's one to try."},{"start":261.94,"end":264.88,"text":"Pick a CSCL study you've read recently."},{"start":265.4,"end":268.04,"text":"Which side of which provocation does it"},{"start":268.04,"end":269.84,"text":"take, without saying so?"}]}};
